WITH payload AS (SELECT $archive_payload$[{"id":"8b04df07-0d4d-506d-98d9-5838e44c1c0c","document_type":"judgment","category":"judicial","subcategory":"general","title":"حرابة -لواط -ارتكاب فاحشة اللواط بالقوة حتت تهديد السكني -شرب املسكر -إقامة حد املسكر -التعزير بالسجن واجللد - التوصية بعاج من اإلدمان.","document_number":"32312933","case_number":"32320638","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بتبوك","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1332/11/31","year":"1434","subject":"حرابة -لواط -ارتكاب فاحشة اللواط بالقوة حتت تهديد السكني -شرب املسكر -إقامة حد املسكر -التعزير بالسجن واجللد - التوصية بعاج من اإلدمان.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 32312933 :‬تاريخه‪1332/11/31 :‬هـ‬\n                    ‫رقم الدعوى‪32320638 :‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34240312‬تاريخه ‪1434/6/13 :‬هـ‬\n\n\n ‫حرابــة ‪ -‬لــواط ‪ -‬ارتــكاب فاحشــة اللــواط بالقــوة حتــت تهديــد الســكني‬\n ‫‪ -‬شــرب املســكر ‪ -‬إقامــة حــد املســكر ‪ -‬التعزيــر بالســجن واجللــد ‪-‬‬\n                                         ‫التوصيــة بعــاج مــن اإلدمــان‪.‬‬\n\n\n\n ‫أ‪ -‬ماجــاء يف كتــاب كشــاف القنــاع عــن اإلقناع لإلمــام البهوتي رحمه‬\n ‫اهلل ‪ 63-48/14‬ونــص احلاجــة منــه (وحــد اللــواط الفاعــل واملفعــول بــه‬\n ‫كــزان لقولــه صلــى اهلل عليــه وســلم ‪( :‬إذا أتــى الرجــل الرجــل فهمــا‬\n ‫زانيــان) وألنــه فــرج مقصــود باالســتمتاع فوجــب فيــه احلــد كفــرج‬\n ‫املــرأة فــإن كان محصنــا رجــم وإال جلــد حــر مائــة وغــرب عامــا وقــن‬\n ‫خمســن وال يجــب احلــد للزنــا إال بشــروط منهــا ثبــوت الزنــا وال يثبــت‬\n ‫إال بأحــد أمريــن أحدهمــا‪ :‬أن يقــر بــه أربــع مــرات يف مجلــس أو مجالس‬\n ‫واألمــر الثانــي أن يشــهد عليــه ولــو ذميــا أربعــة رجــال مســلمني عــدول)‬\n         ‫أ‪.‬ه ـ وإلقــرار املدعــى عليــه بشــربه املســكر باختيــاره وهــو مكلــف‪.‬‬\n ‫‪ -2‬جــاء يف كشــاف القنــاع عــن اإلقنــاع ‪ 98/14‬مــا نصــه (وإذا شــربه أي‬\n ‫املســكر احلــر املســلم املكلــف مختــارا حللــه ملكــره عاملــا أن كثيــره يســكر‬\n ‫ســواء كان الشــراب املســكر مــن عصيــر العنــب أو غيــره مــن املســكرات‬\n ‫ملــا ســبق قليــا كان الــذي شــربه مــن املســكر أو كثيــرا أو لــم يســكر‬\n ‫الشــارب فعليــه احلــد ملــا روى أبــو هريــرة أن النبــي صلــى اهلل عليــه وســلم‬\n ‫قال‪(:‬مــن شــرب اخلمــر فاجلــدوه ) رواه أحمــد وأبــوداود والنســائي وقــد‬\n\n                                                                                       ‫‪156‬‬\n\f      ‫ثبــت أن أبــا بكــر وعمــر وعليــا جلــدوا شــاربها وألن القليــل خمــر فيدخــل‬\n      ‫يف العمــوم ثمانــون جلــدة إلجمــاع الصحابــة ملــا روي‪ :‬أن عمــر استشــار‬\n      ‫النــاس يف حــد اخلمــر فقــال عبــد الرحمــن ‪ :‬اجعلــه كأخــف احلــدود‬\n      ‫ثمانــن جلــدة فضــرب عمــر ثمانــن وكتــب بــه إلــى خالــد وأبــي عبيــدة‬\n      ‫بالشــام وروي أن عليــا قــال يف املشــورة‪ :‬إذا ســكر هــذى وإذا هــذى افتــرى‬\n                                     ‫وعلــى املفتــري ثمانــون رواه اجلوزانــي ‪.‬أ‪.‬ه ـ ‪..‬‬\n\n\n\n\n      ‫توجيــه اإلتهــام للمدعــى عليــه بإســتدراج شــخص ملنزلــه و فعــل الفاحشــة‬\n      ‫بــه بالقــوة حتــت التهديــد بالســكني وشــرب املســكر‪-‬حيث تقــدم‬\n      ‫املجنــي عليــه ببــاغ ملركــز الشــرطة مفــاده أنــه حضــر إليــه بســاعة‬\n      ‫متأخــرة مــن الليــل املدعــى عليــه وطلــب مــن املجنــي عليــه وابــن خالتــه‬\n      ‫املجــيء لبيتــه فحضــر إلــى بيــت املدعــى عليــه و برفقتــه ابــن خالتــه‬\n      ‫ولــم يكــن يف املجلــس غيرهــم و بعــد قرابــة الســاعتني أراد املجنــي‬\n      ‫عليــه الذهــاب فرفــض املدعــى عليــه ودخــل داخــل املنــزل وعــاد و بيــده‬\n      ‫ســكينة وطلــب املدعــى عليــه مــن ابــن خالــة املجنــي عليــه اخلــروج مــن‬\n      ‫املنــزل وطلــب مــن املجنــي عليــه متكينــه مــن نفســه لفعــل فاحشــة اللــواط‬\n      ‫فرفــض املجنــي عليــه فقــام املدعــى عليــه بتهديــده بالســكني حتــى‬\n      ‫مكنــه مــن فعــل الفاحشــة بــه وفعــل الفاحشــة بإيــاج ‪ ،‬طلــب املدعــي‬\n      ‫العــام إثبــات مــا أســند للمدعــى عليــه واحلكــم عليــه بحــد املســكر‬\n      ‫لقــاء شــربه لــه واحلكــم عليــه بحــد احلرابــة‪ ،‬أنكــر املدعــى عليــه فعــل‬\n      ‫الفاحشــة وأقــر بشــرب املســكر يف منزلــه مــع مجموعــه مــن األشــخاص‬\n      ‫مــن ضمنهــم املجنــي عليــه وابــن خالتــه وأقــر بالســابقة‪ ،‬جــرى رجــوع‬\n\n‫‪157‬‬\n\f‫احملكمــة إلــى أدلــة املدعــي العــام ورصدهــا‪ ،‬وجــرى عــرض هــذه األدلــة‬\n‫علــى املدعــى عليــه فأنكرهــا ‪ ،‬صــدر احلكــم بعــدم ثبــوت مــا أســند‬\n‫للمدعــى عليــه مــن إســتدراجه للمجنــي عليــه وفعــل فاحشــة اللــواط‬\n‫بالقــوة وصــرف النظــر عــن دعــوى املدعــي العــام مــن إقامــة حــد احلرابــة‬\n‫وإقامــة حــد املســكر علــى املدعــى عليــه بجلــده ثمانــن جلــدة وتعزيــزه‬\n‫لقــاء إصــراره علــى اســتعمال املســكرات واجتماعــه علــى ذلــك ولشــبهة‬\n‫فعــل الفاحشــة بســجنه ثمانيــة أشــهر وجلــده مائــة وخمســن جلــده‬\n‫مفرقــة علــى خمــس دفعــات والتوصيــة بعالجــه مــن اإلدمــان ‪ -‬لوحــظ‬\n‫علــى احلكــم مــن محكمــة االســتئناف مت إجــراء الــازم حيــال مالحظــة‬\n          ‫أصحــاب الفضيلــة وصــدر احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n‫احلمــد هلل وحــده وبعــد يف يــوم الثالثــاء ‪1432/11/6‬ه ـ لدينــا نحــن‬\n‫القضــاة باحملكمــة العامــة بتبــوك ‪ ...‬وفضيلــة القاضــي ‪ ...‬وفضيلــة‬\n‫القاضــي ‪ ...‬وبنــاء علــى ورود املعاملــة إلــى احملكمــة العامــة بتبــوك‬\n‫بخطــاب رئيــس فــرع هيئــة التحقيــق واالدعــاء العــام مبنطقــة تبــوك رقــم‬\n‫‪ 12290‬وتاريــخ ‪1432/07/27‬ه ـ واملقيــدة يف احملكمــة العامــة بتبــوك‬\n‫برقــم ‪ 32975660‬وتاريــخ ‪1432/08/02‬ه ـ واحملالــة إلــى مكتبنــا مــن‬\n‫رئيــس احملكمــة العامــة بتبــوك املســاعد برقــم ‪ 32320638‬وتاريــخ‬\n‫‪1432/08/02‬ه ـ بشــأن دعــوى املدعــي العــام ضــد ‪ ...‬بشــأن قضيــة فعــل‬\n‫الفاحشــة افتتحــت اجللســة األولــى يف متــام الســاعة ‪12 : 11‬وفيهــا حضــر‬\n‫املدعــي العــام ‪ ...‬بالســجل املدنــي رقــم (‪ )...‬وحضــر حلضــوره املدعــى‬\n‫عليــه ‪ ...‬الســعودي بالســجل املدنــي رقــم (‪ )...‬ســجل تبــوك وقــدم دعــواه‬\n\n                                                                                   ‫‪158‬‬\n\f      ‫قائــا بصفتــي مدعيـ ًا عامـ ًا بدائــرة االدعــاء العــام لفــرع الهيئــة مبنطقــة‬\n      ‫تبــوك أدعــي علــى احلاضــر ‪ ...‬إنــه بتاريــخ ‪1432/4/27‬ه ـ تقــدم املدعو ‪...‬‬\n      ‫بشــكوى ملركــز شــرطة ‪ .......‬مفادهــا تعرضــه لفعــل فاحشــة اللــواط‬\n      ‫مــن قبــل املدعــى عليــه املذكــور يف منــزل األخيــر وقــد مت القبــض علــى‬\n      ‫املدعــى عليــه املذكــور وإيقافــه اســتناد ًا للقــرار الــوزاري رقــم(‪)1900‬‬\n      ‫وتاريــخ ‪1428/7/9‬ه ـ الفقــرة (‪ )1‬مــن أو ًال وبضبــط إفــادة املجنــي عليــه‬\n      ‫‪ ...‬البالــغ مــن العمــر(‪ )20‬عامــا أفــاد بأنــه يف يــوم اجلمعــة املوافــق‬\n      ‫‪1432/4/27‬ه ـ ويف الســاعة الرابعــة فجــر ًا حضــر املدعــى عليــه ‪ ...‬إلــى‬\n      ‫منزلهــم بحــي ‪ .....‬وقــام بطــرق البــاب فخــرج وكان معــه ابــن خالتــه ‪...‬‬\n      ‫بــن ‪ ...‬فطلــب منهمــا املدعــى عليــه احلضــور ملنزلــه وعندمــا ذهبــا ملنزلــه‬\n      ‫وجلســا بــه ولــم يكــن باملجلــس غيرهمــا وبعــد قرابــة ســاعتني أراد‬\n      ‫املجنــي عليــه أن يذهــب ملنزلــه فرفــض املدعــى عليــه خروجــه ثــم ذهــب‬\n      ‫املتهــم داخــل املنــزل وعــاد وبيــده ســكني وطلــب املدعــى عليه مــن املدعو‬\n      ‫‪ ...‬اخلــروج مــن املنــزل وطلــب منــه البقــاء وعــدم اخلــروج وكان يهــدد‬\n      ‫بســكني وأن لــون مقبضهــا بنــي وطلــب املدعــى عليــه منــه متكينــه مــن‬\n      ‫نفســه لفعــل الفاحشــة بــه وعندمــا رفــض قــام املدعــى عليــه بتهديــده‬\n      ‫بالســكني حتــى مكنــه مــن فعــل الفاحشــة بــه وبعدهــا طلب منــه اخلروج‬\n      ‫مــن املنــزل وأفــاد بــأن املدعــى عليــه قــام بفعــل الفاحشــة بــه بإيــاج وأنــزل‬\n      ‫علــى مؤخرتــه وبســماع أقــوال املدعــى عليــه ‪ ...‬أفــاد بأنــه حضــر ملنــزل‬\n      ‫املجنــي عليــه وطلــب مــن املجنــي عليــه وابــن خالتــه أن يحضــرا ملنزلــه‬\n      ‫وأفــاد بأنــه كان يف حالــة ســكر وال يعلــم عــن نفســه وأنكــر قيامــه‬\n      ‫بفعــل الفاحشــة باملجنــي عليــه أوتهديــده بالســكني وباســتجواب املدعى‬\n      ‫عليــه أفــاد بأنــه ذهــب ملنــزل املجنــي عليــه وطلــب مــن املدعــو ‪ ...‬احلضــور‬\n\n\n‫‪159‬‬\n\f‫ملنزلــه وكان برفقتــه ابــن خالتــه ‪ ..‬وجلســا عنــده باملجلس وقاموا بشــرب‬\n‫املســكر وبعــد ذلــك اســتأذن املجنــي عليــه للذهــاب ملنزلــه وذهــب‬\n‫وأنكــر قيامــه بتهديــد املجنــي عليــه بالســكني أوفعــل الفاحشــة بــه‬\n‫وبســؤاله عــن التقريــر الطبــي الصــادر بحــق املجنــي عليــه واملتضمــن‬\n‫وجــود ســحجات ســطحية حــول الشــرج أفــاد بأنــه ال يعلــم بــأي شــيئ‬\n‫وبســماع أقــوال الشــاهد ‪ ...‬أفــاد بأنــه يف يــوم اجلمعــة املوافــق‬\n‫‪1432/4/27‬ه ـ ويف الســاعة الرابعــة فجــر ًا حضــر املدعــى عليــه ‪ ...‬إلــى‬\n‫منزلهــم بحــي ‪ ....‬وطلــب منــه احلضــور ملنزلــه فذهــب هــو وابــن خالتــه ‪...‬‬\n‫إلــى منــزل املدعــى عليــه وجلســا باملجلــس قرابــة الســاعة ولــم يكــن‬\n‫باملجلــس غيرهمــا ثــم قــام‪ ...‬باالســتئذان للذهــاب للمنــزل فطلــب منــه‬\n‫ا ثــم قــام املدعــى عليــه بالدخــول عليهمــا‬    ‫املدعــى عليــه االنتظــار قلي ـ ً‬\n‫باملجلــس وبيــده ســكني وقــام بتهديــد ‪ ...‬وطلــب منــه اخلــروج مــن املنــزل‬\n‫وتــرك ‪ ...‬عنــده باملجلــس فقــام الشــاهد باخلــروج مــن منــزل املدعــى عليــه‬\n‫والتوجــه ملنزلهــم وأخبــر أخيــه مبــا حصــل ثــم عــاد هــو وأخيــه ‪ ...‬ملنــزل‬\n‫املدعــى عليــه وقامــا بطــرق البــاب ولــم يفتــح لهمــا البــاب وبعــد ذلــك قــام‬\n‫‪ ...‬باخلــروج مــن منــزل املدعــى عليــه وكان يبكــي وبإجــراء املواجهــة‬\n‫بــن املجنــي عليــه ‪ ...‬والشــاهد ‪ ...‬وبــن املدعــى عليــه أصــر كل مــن‬\n‫املدعــى عليــه علــى أقوالــه وظهــر علــى املجنــي عليــه والشــاهد الثقــة فيما‬\n‫يقــوالن وظهــر علــى املدعــى عليــه عــدم املبــاالة وكان يبتســم وقــد صــدر‬\n‫بحــق املجنــي عليــه التقريــر الطبــي الصــادر مــن مستشــفى ‪ .....‬الطبــي‬\n‫بتبــوك رقــم الطــوارئ (‪ )46093‬وتاريــخ ‪1432/4/27‬ه ـ واملتضمــن‬\n‫(وجــود ســحجات ســطحية حــول الشــرج ومت أخــذ مســحات داخليــة‬\n‫وخارجيــة مــن الشــرج) وقــد ورد التقريــر الفنــي رقــم (‪ )365‬املتضمــن‬\n\n\n                                                                                        ‫‪160‬‬\n\f      ‫إيجابيــة العينــة رقــم (‪ )6‬واملشــتملة علــى ســروال طويــل كحلــي اللــون‬\n      ‫عائــد للمجنــي عليــه ‪ ...‬وقــد ورد خطــاب مديــر إدارة األدلــة اجلنائيــة رقــم‬\n      ‫(‪ )895/7/1/700/2‬وتاريــخ ‪1432/7/23‬ه ـ ومرفــق التقريــر الفنــي‬\n      ‫رقــم (‪ / )57‬فحــوص وراثيــة ‪1432/‬ه ـ للنتيجــة النهائيــة لتحليــل احلمــض‬\n      ‫النــووي الوراثــي (‪ )DNA‬بســلبية األمنــاط الوراثيــة للعينــة ممــا يتعــذر‬\n      ‫معــه حتديــد مصــدر تلــك العينــات وقــد انتهــى التحقيــق إلــى توجيــه‬\n      ‫االتهــام للمدعــو ‪ ...‬باســتدراج شــخص ملنزلــه وفعــل الفاحشــة بــه بالقــوة‬\n      ‫حتــت التهديــد بســكني وشــرب املســكر وذلــك لألدلة والقرائــن التالية‬\n      ‫‪ -1‬مــا جــاء بإقــراره املنــوه عنــه واملــدون علــى الصفحــة رقــم (‪ )16‬مــن‬\n      ‫دفتــر االســتدالل املرفــق لفــة رقــم (‪ )1‬والصفحــة رقــم (‪ )2‬مــن دفتــر‬\n      ‫التحقيــق لفــة رقــم (‪ -2 - )15‬مــا جــاء بأقوالــه املنــوه عنهــا واملدونــة‬\n      ‫علــى الصفحــة رقــم (‪ )2‬مــن دفتــر التحقيــق لفــة رقــم (‪ -3 - )15‬مــا جــاء‬\n      ‫بشــهادة الشــاهد املنــوه عنهــا واملدونــة علــى الصفحــة رقــم (‪ )9-8‬مــن‬\n      ‫دفتــر التحقيــق لفــة رقــم (‪ -4- )15‬التقريــر الطبــي املرفــق لفــة رقــم (‪)6‬‬\n      ‫‪ -5-‬نتيجــة محضــر املواجهــة بــن املدعــي والشــاهد وبــن املدعــى عليــه‬\n      ‫و عــدم املبــاالة مــن قبــل املدعــى عليــه املدونــة علــى الصفحــة رقــم (‪)10‬‬\n      ‫مــن دفتــر التحقيــق املرفــق لفــة رقــم (‪ -6- )15‬مــا جــاء بالتقريــر الفنــي‬\n      ‫للعينــة رقــم (‪ )6‬املرفــق لفــة رقــم (‪ )22‬وحيــث أن مــا قــام بــه املدعــى عليــه‬\n      ‫املذكــور همــا فعلــن محرمــن ومعاقــب عليهمــا شــرعا وانتهــاك ًا‬\n      ‫ألعــراض املســلمني علــى ســبيل الغلبــة والقــوة والقهــر وضربـ ًا من أضرب‬\n      ‫احلرابــة واإلفســاد يف األرض ‪ -‬لــذا أطلــب‪ -1:‬إثبــات مــا أســند إليــه ‪-2‬‬\n      ‫احلكــم عليــه بحــد املســكر لقــاء شــربه له وفق ًا للنصــوص من الكتاب‬\n      ‫والســنة ‪ -3‬واحلكــم عليــه بحــد احلرابــة وفقــا لآليــة الكرميــة (‪ )33‬مــن‬\n\n\n‫‪161‬‬\n\f‫ســورة املائــدة وعلــى ضــوء املــادة األولــى مــن قــرار هيئــة كبــار العلمــاء‬\n‫رقــم (‪ )85‬وتاريــخ ‪1401/11/11‬ه ـ علمـ ًا بــأن احلــق اخلاص مــا زال قائم ًا‬\n‫هكــذا أجــاب وبعــرض دعــوى املدعــي العــام علــى املدعــى عليــه أجــاب‬\n‫قائــا مــا جــاء يف دعــوى املدعــي العــام مــن فعــل الفاحشــة باملدعــو ‪...‬‬\n‫فغيــر صحيــح والصحيــح إنــه يف يــوم اخلميــس ليلــة اجلمعــة ال أذكــر‬\n‫التاريــخ كنــت يف منزلــي مــع مجموعــة مــن األصحــاب وبدأنــا بشــرب‬\n‫املســكر مــن بعــد صــاة العشــاء إلــى الســاعة الرابعــة فجــرا ويف متــام‬\n‫الســاعة احلاديــة والنصــف خرجــت مــن بيتــي وأردت الذهــاب إلــى البقالــة‬\n‫لشــراء عصيــرات وبعــد خروجــي مــن البقالــة واجهــت املجنــي عليــه ‪...‬‬\n‫وابــن خالتــه ‪ .....‬بجانــب بيتهمــا وطلبــا منــي مرافقتــي إلــى منزلــي‬\n‫فأخذتهمــا معــي إلــى املنــزل وكانــوا أصحابــي مــا زالــوا موجوديــن‬\n‫وســكرانني ثــم أكملنــا شــرب املســكر مــع املدعــو ‪ ...‬وابــن خالتــه‪...‬‬\n‫ثــم يف متــام الســاعة الثانيــة مــن نفــس الليلــة طلــب املدعــو ‪ ...‬وابــن خالتــه‬\n‫االنصــراف مــن بيتــي فأذنــت لهمــا باالنصــراف ثــم رجــع إلــي املدعــو ‪...‬‬\n‫وطلــب منــي أن أعطيــه قطعــة احلشــيش التــي تخصــه والتــي نســاها‬\n‫عنــدي يف بيتــي فأعطيتــه إياهــا وانصــرف ثــم أكملــت الســهرة مــع‬\n‫أصحابــي املتبقــن وهــم ‪ ...‬و‪...‬و‪...‬وأخــي ‪ ...‬وهــم مســتعدين للشــهادة علــى‬\n‫مــا ذكرتــه ويف اليــوم الــذي بعــده أخذونــي البحــث اجلنائــي وحققــوا‬\n‫معــي ووجهــوا لــي هــذه التهمــة كمــا أقــر بــأن لــدي ســابقة اســتعمال‬\n‫مخــدرات وقــد حوكمــت بســببها هــذه إجابتــي وجــرى ســؤاله هــل‬\n‫تربطــك باملدعــو ‪ ...‬صلــة قرابــة أو صداقــة فأجــاب قائــا ال تربطنــي‬\n‫باملدعــو ‪ ...‬صلــة قرابــة وإمنــا أعرفــه منــذ زمــن وهــو رجــل فاســد ويتعاطــى‬\n‫املخــدرات هكــذا أجــاب وبســؤال املدعــي العــام عــن بينتــه علــى طبــق‬\n\n\n                                                                                          ‫‪162‬‬\n\f      ‫دعــواه أجــاب قائــا ســأحضرها يف اجللســة القادمــة هكــذا أجــاب عليــه‬\n      ‫ويف جلســة أخــرى وفيهــا حضــر املدعــي العــام ‪ ...‬الســعودي بالســجل‬\n      ‫املدنــي رقــم ‪ ...‬ســجل تبــوك مبوجــب خطــاب التكليــف رقــم ‪ 16419‬يف‬\n      ‫‪1432/11/13‬ه ـ وحضــر حلضــوره املدعــى عليــه وبســؤال املدعــي العــام‬\n      ‫عــن بينتــه التــي وعــد بإحضارهــا يف هــذه اجللســة فأجــاب قائــا بينتــي‬\n      ‫هــي مــا يلــي ‪ -1‬مــا جــاء بإقــرار املدعــى عليــه املنــوه عنــه واملــدون علــى‬\n      ‫الصفحــة رقــم (‪ )16‬مــن دفتــر االســتدالل املرفــق لفــة رقــم (‪ -2 )1‬مــا‬\n      ‫جــاء بأقوالــه املنــوه عنهــا واملدونــة علــى الصفحــة رقــم (‪ )2‬مــن دفتــر‬\n      ‫التحقيــق لفــة رقــم (‪ -3 )15‬مــا جاء بشــهادة الشــاهد املنــوه عنها واملدونة‬\n      ‫علــى الصفحــة رقــم (‪ )9-8‬مــن دفتــر التحقيــق لفــة رقــم (‪ -4 )15‬التقرير‬\n      ‫الطبــي املرفــق لفــة رقــم (‪ -5 )6‬نتيجــة محضــر املواجهــة بــن املدعــي‬\n      ‫والشــاهد وبــن املدعــى عليــه و عــدم املبــاالة مــن قبــل املدعــى عليــه‬\n      ‫املدونــة علــى الصفحــة رقــم (‪ )10‬مــن دفتــر التحقيــق املرفــق لفــة رقــم‬\n      ‫(‪ -6 )15‬مــا جــاء بالتقريــر الفنــي للعينــة رقــم (‪ )6‬املرفــق لفــة رقــم (‪)22‬‬\n      ‫هــذه بينتــي وجــرى منــا االطــاع علــى الدليــل األول مــن أدلــة املدعــي‬\n      ‫العــام وهــو إقــرار املدعــى عليــه املــدون علــى الصفحــة رقــم (‪ )16‬لفــة رقــم‬\n      ‫(‪ )1‬ووجدنــاه عبــارة عــن اســتجواب احملقــق للمدعــى عليــه ونصه(أثبــت‬\n      ‫أنــا مســاعد محقــق مبركــز شــرطة ‪ ......‬جــرى فتــح هــذا احملضــر يف‬\n      ‫متــام الســاعة الثانيــة والنصــف ظهــر ًا يــوم اجلمعــة املوافــق ‪1432/4/27‬ه ـ‬\n      ‫أعطنــي املعلومــات اإلحصائيــة عــن نفســك؟ االســم ‪ ....‬العمــر ‪22‬ســنة‬\n      ‫ســعودي اجلنســية مبوجــب الســجل (‪ )...‬الســكن ‪ .....‬احلالــة االجتماعيــة‬\n      ‫أعــزب املهنــة عاطــل س‪ /‬يدعــي عليــك املدعــو ‪ ...‬بأنــك قمــت بفعــل‬\n      ‫فاحشــة اللــواط بــه أفدنــا عــن ذلــك؟ أفيدكــم بــأن هــذا الــكالم غيــر‬\n\n\n‫‪163‬‬\n\f‫صحيــح وإنــي كنــت بحالــة غيــر طبيعيــة وال أعلــم عــن نفســي وكان هو‬\n‫شــارب معــي س‪ /‬هــل أتيــت لــه عنــد املنــزل وطلبــت منــه أن يذهــب معــك‬\n‫للمنــزل هــو واملدعــو ‪...‬؟ نعــم حضــرت لهــم باملنــزل وطلــع معــي هــو ‪...‬‬\n‫وابــن خالتــه ‪ ...‬وحضــرا للمنــزل وكان معــه ‪ ...‬وكان معــي شــقيقي س‪/‬‬\n‫هــل قمــت بتهديــده بالســكني؟ ال س‪ /‬ذكــر أنــك قمــت بتهديــده‬\n‫بســكني قــد هــددت املدعــو ‪ ...‬بــن ‪ ...‬بالســكني حتــى خــرج مــن املنــزل‬\n‫أفدنــا عــن ذلــك بالتفصيــل ؟ أفيدكــم بــأن هــذا الــكالم غيــر صحيــح‬\n‫وأنــه طلــب اخلــروج مــن املنــزل وقلــت لــه خــاص روح وخــرج مــن املنــزل‬\n‫وبعدهــا خــرج املدعــو ‪ ...‬وبقــي أنــا وشــقيقي باملجلــس وكنــا متناولــن‬\n‫العــرق املســكر ويف حالــة ســكر س‪ /‬ملــاذا يدعــي عليــك بهــذه الدعــوى‬\n‫؟ ال أعلــم س‪ /‬هــل تعــرف املدعــو ‪ ...‬مــن قبــل ذلــك؟ نعــم أعرفــه مــن قبــل‬\n‫زمــان س‪ /‬هــل قابلتــه قبــل ذلــك مــرة حيــث ذكــر بأنــه ال يعرفــك وأنــه‬\n‫أول مــرة يشــاهدك كيــف تفســر ذلــك أفدنــي باحلقيقــة؟ نعــم قابلتــه‬\n‫أكثــر مــن مــرة وقبــل زمــان هــو يعرفنــي وكــم مــرة يطلــع معــي وأكثــر‬\n‫مــن مــرة يدخــل املنــزل س‪ /‬هــل لديــك ســوابق؟ نعــم ســابقة مخــدرات‬\n‫س‪ /‬هــل لديــك أقــوال أخــرى؟ ال س‪ /‬هــل تصــادق علــى أقوالــك؟ نعــم )‬\n‫أ‪.‬ه ـ املقــر مبــا فيــه ‪ ...‬بصمتــه مســاعد محقــق ‪ ...‬توقيعــه وجــرى منــا‬\n‫االطــاع علــى الدليــل الثانــي مــن أدلــة املدعــي العــام وهــي أقــوال املدعــى‬\n‫عليــه املدونــة علــى الصفحــة رقــم (‪ )2‬لفــة رقــم (‪ )15‬ونــص احلاجــة منــه‬\n‫(س‪ /‬يدعــي عليــك املدعــو ‪ ...‬بأنــك حضــرت إلــى منزلــه وطرقــت البــاب‬\n‫وقــام باخلــروج هــو وابــن خالتــه وذهبــا معــك إلــى منزلــك وقمــت بإخــراج‬\n‫ســكني وطــردت ابــن خالتــه ثــم قمــت بفســخ ســرواله وقمــت بفعــل‬\n‫الفاحشــة بإيــاج فمــا قولــك؟ ج‪ /‬أفيدكــم بأننــي ذهبــت إلــى منــزل‬\n\n\n                                                                                       ‫‪164‬‬\n\f      ‫املدعــو ‪ ...‬يف يــوم اخلميــس املوافــق ‪1432/4/26‬ه ـ وطلبــت منــه أن يأتــي‬\n      ‫معــي إلــى منزلــي وفعــا أتــى معــي وكان برفقتــه ابــن خالتــه املدعــو ‪...‬‬\n      ‫ومــن ثــم ذهبنــا إلــى منزلــي وجلســنا باملجلــس وكان متواجــد معنــا‬\n      ‫باملجلــس أخــي ‪ ...‬واملدعــو ‪ ...‬واملدعــو ‪ ...‬وأخــوه ال أذكــر اســمه وقمنــا‬\n      ‫جميعــا بشــرب املســكر وبعدهــا أســتأذن منــي ‪ ...‬وابــن خالتــه وأذنــت‬\n      ‫لهمــا باخلــروج ومــا ذكــره املدعــي ‪ ...‬بأننــي قمــت بتهديــده وفعــل‬\n      ‫الفاحشــة بــه فهــذا غيــر صحيــح س‪ /‬مــن الــذي يســكن معــك باملنــزل؟‬\n      ‫ج‪ /‬أنــا ســاكن مبنــزل األســرة مــع أهلــي س‪ /‬مــا غرضــك مــن ذهابــك‬\n      ‫ملنــزل املدعــو ‪ ...‬وطلبــك منــه احلضــور معــك ملنزلــك؟ ج‪ /‬أنــا ذهبــت إلــى‬\n      ‫منــزل صديقــي ‪ ...‬وكان يســكن معــه باملنــزل املدعــو ‪ ....‬حيــث أن‪ ..‬ابــن‬\n      ‫خالــة ‪...‬حيــث قمــت بطــرق البــاب وخــرج لــي ‪....‬وطلبــت منــه الذهــاب‬\n      ‫معــي إلــى منزلــي وكان يرافقــه ‪ ...‬س‪ /‬ذكــرت بأقوالــك الســابقة‬\n      ‫بأنــك ذهبــت إلــى منــزل ‪ ...‬وطلبــت منــه أن يرافقــك إلــى منزلــك ثــم‬\n      ‫ذكــرت اآلن بأنــك ذهبــت ملنــزل ‪ ...‬وطلبــت منــه مرافقتــك ملنزلــك وهــذا‬\n      ‫تناقــض بأقوالــك فمــاذا تفســر ذلــك؟ ج‪ /‬الصحيــح أننــي أتيــت إلــى منــزل‬\n      ‫‪ ...‬وطلبــت منــه أن يرافقنــي إلــى منزلــي ألنــه زميلــي وحضــر إلــي ومعــه ‪...‬‬\n      ‫علمــا بــأن ‪ ...‬يســكن مــع ‪ ...‬بنفــس املنزل)أ‪.‬ه ـ وجــرى منــا االطــاع علــى‬\n      ‫الدليــل الثالــث مــن أدلــة املدعــي العــام وهــي شــهادة الشــاهد املدونــة‬\n      ‫علــى الصفحــة رقــم (‪ )9-8‬لفــة رقــم (‪ )15‬ونصها(بصفتــي عضــو هيئــة‬\n      ‫التحقيــق احملقــق ‪ ...‬مت ضبــط إفــادة املدعــو ‪ ...‬ســعودي اجلنســية مبوجــب‬\n      ‫الســجل املدنــي رقــم ‪ ...‬العمــر (‪ )23‬عامــا الســكن حــي ‪ ....‬رقــم اجلــوال‬\n      ‫(‪ )...‬س‪ /‬مــا هــي إفادتــك بالتفصيــل؟ ج‪ /‬أفيدكــم بأنــه حضــر املدعــو‬\n      ‫‪ ...‬إلــى منزلنــا بحــي ‪ ....‬وطلــب منــا احلضــور إلــى منزلــه وذلــك يف يــوم‬\n\n\n‫‪165‬‬\n\f‫اجلمعــة الســاعة الرابعــة فجــرا وذهبــت أنــا و‪...‬إلــى منــزل ‪ ...‬ودخلنــا‬\n‫املجلــس وجلســنا قرابــة الســاعة ثــم قــام ‪ ...‬باالســتئذان باخلــروج فطلــب‬\n‫منــه ‪ ...‬االنتظــار قليــا ثــم عنــد خــروج ‪ ...‬مــن املجلــس عــاد للمجلــس‬\n‫وأخبرنــي بــأن ‪ ...‬يســحبه يريــد إدخالــه داخــل املنــزل ثــم دخــل علينــا ‪ ...‬يف‬\n‫املجلــس وكان معــه ســكني وقــام بإخــراج الســكني وقــام بتهديــدي‬\n‫وإخراجــي مــن املجلــس وجعــل ‪ ...‬عنــده باملجلــس وأخرجنــي مــن املنــزل‬\n‫وذهبــت ملنزلنــا وأخبــرت أخــي ‪ ...‬مبــا حصــل وحضرنــا ملنــزل ‪ ...‬وقمنــا‬\n‫بطــرق البــاب ولــم يفتــح لنــا البــاب ثــم خــرج ‪ ....‬مــن منــزل ‪ ...‬وكان‬\n‫يبكــي وحاولنــا التفاهــم مــع ‪ ...‬فلــم يتجــاوب معنــا وأغلــق البــاب بعــد‬\n‫ذاك ذهبنــا ملنزلنــا وأخبرنــا والــد ‪ ...‬مبــا حصــل س‪ /‬مــن كان معكمــا‬\n‫باملجلــس؟ ج‪ /‬لــم يكــن معنــا أحــد ســوى أنــا و‪...‬و‪...‬فقــط س‪ /‬هــل كان‬\n‫‪ ...‬بحالــة طبيعيــة ؟ ج‪ /‬أحــس أنــه يف حالــة غيــر طبيعيــة س‪ /‬مــا نــوع‬\n‫الســكني؟ ج‪ /‬ســكني خضــار طويلــة وال أذكــر لونهــا س‪ /‬هــل قــام‪...‬‬\n‫بتهديــدك بالســكني؟ ج‪ /‬قــام بتوجيــه الســكني يف وجهــي وطلــب منــي‬\n‫اخلــروج مــن املنــزل س‪/‬هــل لديــك مــا تضيفــه ؟ ج‪ /‬ال)أ‪.‬ه ـ املقــر مبــا فيــه‬\n‫‪ ...‬توقيعــه احملقــق ‪ ...‬توقيعــه وجــرى منــا االطــاع علــى الدليــل الرابــع مــن‬\n‫أدلــة املدعــي العــام وهــو التقريــر الطبــي املــدون علــى اللفــة رقــم (‪)6‬‬\n‫واملتضمــن تقريــر طبــي أولــي اســم املصــاب ‪ ...‬ســعودي اجلنســية النــوع‬\n‫ذكــر العمــر (‪ )20‬ســنة نفيدكــم بأنه بالكشــف الطبي على املذكور‬\n‫تبــن وجــود ســحجات ســطحية حــول الشــرج ومت أخــذ مســحات داخليــة‬\n‫وخارجيــة مــن الشــرج ومت حتريــز املالبــس الداخليــة وتســليمها ملنــدوب‬\n‫الشــرطة‪.‬أ‪.‬هـ وجــرى منــا االطــاع علــى الدليــل اخلامــس مــن أدلــة املدعــي‬\n‫العــام وهــو محضــر املواجهــة بــن املدعــي والشــاهد وبــن املدعــى عليــه‬\n\n\n                                                                                        ‫‪166‬‬\n\f      ‫املــدون علــى الصفحــة رقــم (‪ )10‬لفــة رقــم (‪ )15‬ونصــه (محضــر مواجهــة‬\n      ‫يف يــوم األحــد املوافــق ‪1432/4/29‬ه ـ بصفتــي محقــق القضيــة ‪ ...‬جــرى‬\n      ‫مواجهــة أطــراف القضيــة حيــث أفــاد الطــرف األول ‪ ...‬و‪...‬أنهمــا حضــرا‬\n      ‫منــزل الطــرف الثانــي ‪ ...‬وعندمــا أراد ‪ ...‬االســتئذان واخلــروج مــن املنــزل‬\n      ‫قــام الطــرف الثانــي ‪ ...‬بإحضــار ســكني وقــام بتهديــد ‪ ...‬بالســكني‬\n      ‫وطلــب منــه اخلــروج وخــرج مــن املنــزل وأفــاد ‪ ...‬بــأن الطــرف الثانــي ‪ ...‬قــام‬\n      ‫بتهديــده بالســكني وفعــل الفاحشــة بــه بالقــوة وأفــاد الطــرف الثانــي ‪...‬‬\n      ‫بــأن الطــرف الثانــي ‪ ...‬و‪...‬حضــرا عنــده باملنــزل وجلســا يف املجلــس‬\n      ‫وكان باملجلس ‪ ...‬وأخيه ‪ ...‬وأخي ‪ ...‬و‪...‬وقمنا بشــرب املســكر جميع ًا‬\n      ‫وبعــد ذلــك قــام ‪ ...‬و‪...‬باخلــروج مــن منزلــي وأنكــر فعــل الفاحشــة ب‪...‬‬\n      ‫وتهديــده بالســكني أو تهديــد ‪ ...‬وأفــاد الطــرف األول ‪ ...‬و‪...‬أنــه لــم‬\n      ‫يكــن باملجلــس غيرهمــا و‪...‬فقــط ولــم يوجــد معهمــا مــا ذكــره الطــرف‬\n      ‫األول وأصــر كل مــن الطرفــن علــى أقوالــه ولــم يظهــر خــال املواجهــة‬\n      ‫مــا يفيــد التحقيــق إال أنــه ظهــر علــى الطــرف األول ‪ ...‬و‪...‬أنهمــا واثقــان‬\n      ‫مــن نفســهما وفيمــا يقــوالن وظهــر علــى الطــرف الثانــي ‪ ...‬أنــه غيــر‬\n      ‫مبالــي ويظهــر عليــه االبتســامة ولــم يظهــر خــاف ذلــك وحفظ ـ ًا للواقــع‬\n      ‫دون هــذا احملضر)أ‪.‬ه ـ الطــرف األول ‪ ....‬توقيعــه ‪ ....‬توقيعــه الطــرف‬\n      ‫الثانــي ‪ ...‬بصمتــه محقــق القضيــة ‪ ...‬توقيعــه وجــرى منــا االطــاع علــى‬\n      ‫الدليــل الســادس مــن أدلــة املدعــي العــام وهــو التقريــر الفنــي للعينــة رقــم‬\n      ‫(‪ )6‬لفــة رقــم (‪ )22‬ويتضمــن‪ :‬تقريــر فنــي رقــم ‪/365‬فحــوص حيويــة‬\n      ‫(مني)‪1432‬ه ـ فحــص مالبــس ومســحات عائــدة للمدعــو ‪ ....‬عينــة رقــم‬\n      ‫(‪ )6‬ســروال طويــل كحلــي اللــون عائــد للمدعــو ‪ ....‬و‪ ...‬مت أخــذ مســحة‬\n      ‫قضيــب داخليــة وخارجيــة وكذلــك الكشــف عــن الســروال القصيــر‬\n\n\n‫‪167‬‬\n\f‫الداخلــي للمدعــو ‪ ...‬والنتيجــة ســلبية ومت أخــذ مســحة شــرجية داخليــة‬\n‫وخارجيــة مــن املدعــو ‪ ...‬والنتيجــة ســلبية وكذلــك مت الكشــف علــى‬\n‫ســروال طويــل كحلــي اللــون عائــد للمدعــو ‪ ....‬والنتيجــة إيجابيــة أ‪.‬ه ـ‬\n‫الفاحصــون فنــي مختبــر جنائــي جنــدي أول ‪ ....‬توقيعــه مديــر قســم‬\n‫الفحــوص احليويــة مــازم ‪ ....‬توقيعــه تصديــق مديــر شــعبة املختبــرات‬\n‫اجلنائيــة مقــدم كيميائــي ‪ ...‬توقيعــه وبعــرض أدلــة املدعــي العــام علــى‬\n‫املدعــى عليــه أجــاب قائــا مــا ذكــره املدعــي العــام يف دليلــه األول وهــو‬\n‫اإلقــرار املنســوب لــي ومــا ذكــره يف الدليــل الثانــي مــن أقوالــي املنســوبة‬\n‫لــي ومــا ذكــره يف الدليــل اخلامــس مــن محضــر املواجهــة ومــا ذكــره يف‬\n‫الدليــل الســادس مــن التقريــر الفنــي مــن ســلبية الفحوصــات فصحيــح‬\n‫أمــا مــا ذكــره املدعــي العــام يف دليلــه الثالــث وهــي شــهادة املدعــو ‪....‬‬\n‫ضــدي فغيــر صحيــح والصحيــح مــا ذكرتــه يف إجابتــي علــى دعــوى‬\n‫املدعــي العــام ومــا ذكــره املدعــي العــام يف دليلــه الرابــع وهــو التقريــر‬\n‫الطبــي املتضمــن وجــود ســحجات ســطحية حــول شــرج املدعــو ‪ ....‬فــا‬\n‫أعلــم عنهــا ولســت أنــا املتســبب يف هــذه الســحجات هكــذا أجــاب‬\n‫وبســؤال املدعــي العــام واملدعــى عليــه هــل لديهمــا مــا يريــدان إضافتــه يف‬\n‫هــذه القضيــة فأجابــا قائلــن ليــس لدينــا ســوى مــا قدمنــا ونطلب احلكم‬\n‫يف هــذه القضيــة هكــذا أجابــا فبنــاء علــى مــا تقــدم مــن الدعــوى‬\n‫واإلجابــة وإلنــكار املدعــى عليــه فعــل الفاحشــة باملدعــو ‪ ....‬وال بينــة‬\n‫موصلــة للمدعــي العــام علــى ذلــك وملــا جــاء يف التقريــر الفنــي املذكــور‬\n‫مــن ســلبية فحوصــات احليوانــات املنويــة وألن فاحشــة اللــواط كالزنــا ال‬\n‫تثبــت إال بأحــد أمريــن كمــا جــاء ذلــك يف كالم أهــل العلــم ومــن ذلــك‬\n‫مــا جــاء يف كتــاب كشــاف القنــاع عــن اإلقنــاع لإلمــام البهوتــي رحمــه‬\n\n\n                                                                                      ‫‪168‬‬\n\f      ‫اهلل ‪ 63-48/14‬ونــص احلاجــة منــه (وحــد اللــواط الفاعــل واملفعــول بــه‬\n      ‫كــزان لقولــه صلــى اهلل عليــه وســلم ‪( :‬إذا أتــى الرجــل الرجــل فهمــا‬\n      ‫زانيــان) وألنــه فــرج مقصــود باالســتمتاع فوجــب فيــه احلــد كفــرج املــرأة‬\n      ‫فــإن كان محصنــا رجــم وإال جلــد حــر مائــة وغــرب عامــا وقــن خمســن‬\n      ‫وال يجــب احلــد للزنــا إال بشــروط منهــا ثبــوت الزنــا وال يثبــت إال بأحــد‬\n      ‫أمريــن أحدهمــا‪ :‬أن يقــر بــه أربــع مــرات يف مجلــس أو مجالــس واألمــر‬\n      ‫الثانــي أن يشــهد عليــه ولــو ذميــا أربعــة رجــال مســلمني عــدول) أ‪.‬ه ـ‬\n      ‫وإلقــرار املدعــى عليــه بشــربه املســكر باختيــاره وهــو مكلــف‪ .‬وملــا جــاء‬\n      ‫يف كشــاف القنــاع عــن اإلقنــاع ‪ 98/14‬مــا نصــه (وإذا شــربه أي‬\n      ‫املســكر احلــر املســلم املكلــف مختــارا حللــه ملكــره عاملــا أن كثيــره‬\n      ‫يســكر ســواء كان الشــراب املســكر مــن عصيــر العنــب أو غيــره مــن‬\n      ‫املســكرات ملــا ســبق قليــا كان الــذي شــربه مــن املســكر أو كثيــرا‬\n      ‫أو لــم يســكر الشــارب فعليــه احلــد ملــا روى أبــو هريــرة أن النبــي صلــى‬\n      ‫اهلل عليــه وســلم قال‪(:‬مــن شــرب اخلمــر فاجلــدوه ) رواه أحمــد وأبــوداود‬\n      ‫والنســائي وقــد ثبــت أن أبــا بكــر وعمــر وعليــا جلــدوا شــاربها وألن‬\n      ‫القليــل خمــر فيدخــل يف العمــوم ثمانــون جلــدة إلجماع الصحابــة ملا روي‪:‬‬\n      ‫أن عمــر استشــار النــاس يف حــد اخلمــر فقــال عبــد الرحمــن ‪ :‬اجعلــه‬\n      ‫كأخــف احلــدود ثمانــن جلــدة فضــرب عمــر ثمانــن وكتــب بــه إلــى‬\n      ‫خالــد وأبــي عبيــدة بالشــام وروي أن عليــا قــال يف املشــورة‪ :‬إذا ســكر‬\n                 ‫هذى وإذا هذى افترى وعلى املفتري ثمانون رواه اجلوزاني ‪.‬أ‪.‬هـ ‪.‬‬\n      ‫وإلقــرار املدعــى عليــه بســابقته وهــي اســتعمال املخــدرات ممــا يــدل‬\n      ‫ذلــك علــى عــدم توبتــه منهــا وارتداعــه بالعقوبــة الصــادرة بحقــه وحبــه‬\n      ‫للمســكرات واجتماعــه عليــه لــذا فقــد حكمنــا مبــا يلــي أوال لــم يثبــت‬\n\n\n‫‪169‬‬\n\f‫لدينــا قيــام املدعــى عليــه ‪ .... ....‬باســتدراج املجنــي عليــه ‪ ...‬وفعل فاحشــة‬\n‫اللــواط بــه بالقــوة وصرفنــا النظــر عــن طلــب املدعــي العــام مــن إقامــة حد‬\n‫احلرابــة علــى املدعــى عليــه ثانيــا إقامــة حــد املســكر علــى املدعــى عليــه‬\n‫وذلــك بجلــده ثمانــون جلــدة ثالثــا تعزيــره لقــاء إصــراره علــى اســتعماله‬\n‫املســكرات واجتماعــه عليــه وذلــك بســجنه ثمانيــة أشــهر تبــدأ مــن‬\n‫تاريــخ إيقافــه بســبب هــذه القضيــة وجلــده مائتــي وخمســن جلــدة‬\n‫مفرقــة علــى خمســة دفعــات بــن كل دفعــة وأخــرى خمســة عشــر يومــا‬\n‫هكــذا حكمنــا وبعــرض احلكــم علــى الطرفــن قــرر املدعــى عليــه‬\n‫قناعتــه باحلكــم واعتــرض عليــه املدعــي العــام وطلــب متييــزه مــع تقــدمي‬\n‫الئحــة اعتراضيــة فأجيــب إلــى طلبــه وســلم صــورة مــن القــرار الشــرعي‬\n‫يف هــذه اجللســة بتاريــخ ‪1432/11/13‬ه ـ وأفهمنــاه بــأن لــه مــدة أقصاهــا‬\n‫ثالثــون يومــا مــن هــذا التاريــخ فــإذا انقضــت املــدة ولــم يقــدم اعتراضــه‬\n‫فإنــه يســقط حقــه يف االعتــراض وترفــع املعاملــة إلــى مقــام محكمــة‬\n‫االســتئناف املوقــرة باجلــوف لتدقيــق احلكــم حســب املتبــع وقــرر املدعــى‬\n‫عليــه قائــا إننــي أرغــب مــن هيئــة احملكمــة أن توصــي لــي بالعــاج مــن‬\n‫اإلدمــان هكــذا قــرر وبنــاء علــى مــا قــرره املدعــى عليــه نوصــي بعالجــه‬\n‫مــن اإلدمــان يف أحــد املستشــفيات املتخصصــة ففهــم ذلــك واختتمــت‬\n‫اجللســة يف متــام الســاعة الثانيــة عشــر وللبيــان حــرر يف ‪1432/11/13‬ه ـ‬\n                                        ‫وصلــى اهلل وســلم علــى نبينــا محمــد ‪.‬‬\n‫احلمــدهلل وحــده وبعــد يف يــوم الســبت ‪1433/6/7‬ه ـ افتتحــت اجللســة‬\n‫الرابعــة يف متــام الســاعة العاشــرة وفيهــا حضــر املدعــي العــام ولــم يحضــر‬\n‫املدعــى عليــه فقــد عــادت املعاملــة مــن مقــام محكمــة االســتئناف‬\n‫املوقــرة باجلــوف مبوجــب خطــاب فضيلــة رئيســها رقــم ‪ 3324343‬يف‬\n\n\n                                                                                       ‫‪170‬‬\n\f      ‫‪1433/5/12‬ه ـ وبرفقهــا القــرار الصــادر مــن الدائــرة اجلزائية اخلماســية‬\n      ‫األولــى برقــم ‪ 33235344‬يف ‪1433/5/9‬ه ـ ونص احلاجة منه (وبدراســة‬\n      ‫القــرار وصــورة ضبطــه وأوراق املعاملــة لوحــظ أوال‪:‬حكــم أصحــاب‬\n      ‫الفضيلــة بصــرف النظــر عــن طلــب املدعــي العــام إقامــة حــد احلرابــة ولــم‬\n      ‫جنــد أنهــم عــزروا املدعــى عليــه لقــاء تهمــة فعــل الفاحشــة بالقــوة نظــرا‬\n      ‫لتوفــر القرائــن ضــده ومنهــا التقريــر الطبــي وشــهادة ابــن خالــة املجنــي‬\n      ‫عليــه ثانيــا أن مــا حكــم بــه أصحــاب الفضيلــة يف ثالثــا يف غيــر محلــه‬\n      ‫حيــث أن االســتعمال ال يــزاد فيــه عــن احلــد فعلــى أصحــاب الفضيلــة‬\n      ‫إكمــال الــازم وإحلــاق مــا يجــد للضبــط وصورتــه والقــرار وســجله ثــم‬\n      ‫إعــادة املعاملــة كاملتبــع هــذا وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى‬\n      ‫الــه وصحبــه وســلم أجمعني)أ‪.‬ه ـ قاضــي اســتئناف ‪ ...‬ختمــه وتوقيعــه‬\n      ‫قاضــي اســتئناف ‪ ...‬ختمــه وتوقيعــه قاضــي اســتئناف د‪ .../‬ختمــه‬\n      ‫وتوقيعــه قاضــي اســتئناف ‪ ...‬وقــع األصــل ومجــاز قاضــي اســتئناف ‪...‬‬\n      ‫ختمــه وتوقيعــه عليــه جنيــب أصحــاب الفضيلــة حفظهــم اهلل بالنســبة‬\n      ‫للمالحظــة األولــى فلــم يتــم تعزيــر املدعــى عليــه لضعــف األدلــة وملــا جــاء‬\n      ‫يف التقريــر الفنــي للحيوانــات املنويــة مــن أنــه مت أخــذ مســحة مــن قضيــب‬\n      ‫املدعــى عليــه داخليــة وخارجيــة ومت الكشــف عــن ســرواله القصيــر‬\n      ‫الداخلــي وظهــرت النتيجــة ســلبية وجــرى ســؤال املدعــي العــام لتكملــة‬\n      ‫اإلجابــة عــن الفقــرة األولــى هــل تســتطيع إحضــار ابــن خالــة املجنــي‬\n      ‫عليــه للشــهادة فأجــاب قائــا إننــي اتصلــت عليــه مــرارا ولــم يــرد علــى‬\n      ‫اتصاالتــي وأكتفــي بشــهادته املذكــورة هكــذا أجــاب أمــا بالنســبة‬\n      ‫للمالحظــة الثانيــة فقــد حكمنــا يف الفقــرة الثانيــة مــن حكمنــا بإقامــة‬\n      ‫حــد املســكر علــى املدعــى عليــه أمــا بالنســبة للفقــرة الثالثــة فحكمنــا‬\n\n\n‫‪171‬‬\n\f‫هــو ليــس علــى اســتعمال املســكرات وإمنــا علــى إصــرار املدعــى عليــه‬\n‫علــى اســتعمال املســكرات واالجتمــاع عليــه وحلبــه الشــديد لــه وعــدم‬\n‫ارتداعــه بالعقوبــة الصــادرة بحقــه فهــذه عقوبــة تعزيريــة ال حديــة‬\n‫هــذا جوابنــا وألصحــاب الفضيلــة فائــق التقديــر واالحتــرام وســيتم‬\n‫بعــث كامــل املعاملــة إلــى أصحــاب الفضيلــة لالطــاع علــى إجابتنــا‬\n‫واختتمــت اجللســة يف متــام الســاعة العاشــرة وثالثــن دقيقــة وللبيــان حــرر‬\n                   ‫يف ‪1433/6/7‬ه ـ وصلــى اهلل وســلم علــى نبينــا محمــد‪.‬‬\n‫احلمــد هلل وحــده وبعــد يف يــوم الثالثــاء ‪1433/11/2‬ه ـ فقــد وردتنــا‬\n‫املعاملــة مــن مقــام محكمــة االســتئناف املوقــرة باجلــوف مبوجــب‬\n‫خطــاب فضيلــة رئيســها رقــم ‪ 331113666‬يف ‪1433/7/19‬ه ـ وبرفقــه‬\n‫القــرار الصــادر مــن الدائــرة اجلزائيــة اخلماســية األولــى رقــم ‪33330309‬‬\n‫يف ‪1433/7/7‬ه ـ ونــص احلاجــة منــه (وباإلطــاع علــى مــا أجــاب بــه‬\n‫أصحــاب الفضيلــة القضــاة وأحلقــوه بالقــرار وصــورة ضبطــه وســجله بناء‬\n‫علــى قرارنــا الســابق رقــم ‪ 33235344‬وتاريــخ ‪1433/5/9‬ه ـ لوحــظ أن‬\n‫جــواب أصحــاب الفضيلــة غيــر مــاق وال مقنــع ولــو جعــل أصحــاب‬\n‫الفضيلــة مــا حكمــوا بــه مــن ســجن وجلــد بحــق املدعــى عليــه يشــمل‬\n‫تهمــه فعــل الفاحشــة لــكان حســن فعلــى أصحــاب الفضيلــة تأمــل ذلــك‬\n‫والرجــوع إلــى قرارنــا الســابق وإكمــال الــازم وإحلــاق مــا يجــد للضبــط‬\n‫وصورتــه والقــرار وســجله وإعــادة املعاملــة كاملتبــع واهلل املوفــق وصلــى‬\n‫اهلل علــى نبينــا محمــد وعلــى الــه وصحبــه وســلم ) قاضــي اســتئناف‬\n‫‪ ...‬وقــع األصــل ومجــاز قاضــي اســتئناف ‪ ...‬ختمــه وتوقيعــه قاضــي‬\n‫اســتئناف الدكتــور ‪ ...‬ختمــه وتوقيعــه قاضــي اســتئناف ‪ ...‬وقــع األصــل‬\n‫ومجــاز رئيــس الدائــرة ‪ ...‬ختمــه وتوقيعــه جنيــب أصحــاب الفضيلــة بأنــه‬\n\n\n                                                                                   ‫‪172‬‬\n\f      ‫ســبق وأن أجبنــا عــن ســبب تعزيــر املدعــى عليــه علــى التهمــة يف فعــل‬\n      ‫الفاحشــة وناقشــنا يف ذلــك األدلــة وإذا ظهــر ألصحــاب الفضيلــة أي‬\n      ‫دليــل مؤثــر فيمكــن بيانــه حتــى يتــم علــى ضوئــه تعزيــر املدعــى عليــه‬\n      ‫مــن عدمــه الســيما وأننــا ذكرنــا أن املدعــي العــام عجــز عــن إحضــار‬\n      ‫الشــاهد كمــا أن التقريــر الطبــي أثبــت ســلبيته فكيــف يتــم واحلــال‬\n      ‫مــا ذكــر تعزيــر املدعــى عليــه علــى تهمــة ليــس هنــاك مــا يؤيدهــا مــن‬\n      ‫أدلــة أو قرائــن مؤثــرة هــذا جوابنــا وبعرضــه علــى املدعــي العــام قــرر‬\n      ‫اعتراضــه مكتفيــا مبــا قدمــه مــن الئحــة اعتراضيــة وأمرنــا بإحلاقــه يف‬\n      ‫الضبــط وصورتــه ويف القــرار ثــم إرســال كامــل املعاملــة إلــى محكمــة‬\n      ‫االســتئناف املوقــرة بتبــوك إلكمــال الزمهــا واختتمــت اجللســة يف متــام‬\n      ‫الســاعة العاشــرة وثالثــن دقيقــة وللبيــان حــرر يف ‪1433/11/2‬ه ـ‬\n                                             ‫وصلــى اهلل وســلم علــى نبينــا محمــد‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد يف يــوم الســبت ‪1434/5/11‬ه ـ افتتحــت اجللســة‬\n      ‫يف متــام الســاعة احلاديــة عشــرة وثالثــن دقيقــة وفيهــا حضــر املدعي العام‬\n      ‫وحضــر حلضــوره املدعــى عليــه وقــد وردتنــا املعاملــة مــن مقــام محكمــة‬\n      ‫االســتئناف املوقــرة باجلــوف مبوجــب خطــاب فضيلــة رئيســها رقــم‬\n      ‫‪ 332212669‬يف ‪1434/1/27‬ه ـ وبرفقــه القــرار الصــادر مــن الدائــرة‬\n      ‫اجلزائيــة اخلماســية األولــى رقــم ‪ 3413095‬يف ‪1434/1/14‬ه ـ ونــص‬\n      ‫احلاجــة منــه (وباالطــاع علــى مــا أجــاب بــه أصحــاب الفضيلــة القضــاة‬\n      ‫وأحلقــوه بالصــك وصــورة ضبطــه وســجله بنــاء علــى قرارنــا الســابق رقــم‬\n      ‫‪ 33330309‬يف ‪1433/7/7‬ه ـ لوحــظ أن أصحــاب الفضيلة أصروا على‬\n      ‫عــدم تعزيــر املدعــى عليــه لقــاء شــبهة توجــه التهمــة للمدعــى عليــه بفعــل‬\n      ‫الفاحشــة بالقــوة وقــد ذكــر مــا يوجههــا يف قــرار الدائــرة األول مفــرق‬\n\n\n‫‪173‬‬\n\f‫بــن ثبــوت التهمــة وبــن توجههــا مبجمــوع مــن القرائــن ال ســيما وقــد دون‬\n‫أصحــاب الفضيلــة نــص شــهادة ابــن خالــة املجنــي عليــه والتقريــر الطبــي‬\n‫يف حــق املجنــي عليــه وإقــرار املدعــى عليــه بحضــور املجنــي عليــه وابــن‬\n‫خالتــه عنــده ليلــة إعــداد التقريــر الطبــي وأنــه كان يف حالــة ســكر‬\n‫ولــو جعــل أصحــاب الفضيلــة مــا حكمــوا بــه مــن تعزيــر املدعــى عليــه يف‬\n‫الفقــرة الثالثــة مــن حكــم يشــمل فعــل الفاحشــة لــكان ســائغا وحســنا‬\n‫حســب توجيــه الدائــرة يف قرارهــا الثانــي فعلــى أصحــاب الفضيلــة‬\n‫إكمــال الــازم وإحلــاق مــا يجــد للضبــط وصورتــه والقــرار وســجله ثــم‬\n‫إعــادة املعاملــة املتبــع واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n‫آلــه وصحبــه وســلم)أ‪.‬هـ وملــا رأه أصحــاب الفضيلــة فقــد رجعنــا عمــا‬\n‫حكمنــا بــه يف الفقــرة األولــى مــن حكمنــا مــن عــدم اإلثبــات وتوجــه‬\n‫لنــا شــبهة توجــه التهمــة املنســوبة للمدعــى عليــه وقررنــا تعزيــره لقــاء‬\n‫مــا ذكــر يف الفقــرة الثالثــة مــن حكمنــا هكــذا جوابنــا وألصحــاب‬\n‫الفضيلــة التقديــر واالحتــرام وبعرضــه علــى الطرفــن قــرر املدعــى عليــه‬\n‫قناعتــه باحلكــم واعتــرض عليــه املدعــي العــام مكتفيــا مبــا قدمــه مــن‬\n‫الئحــة اعتراضيــة ولئــا يخفــى جــرى إحلاقــه بضبطــه وصورته وســيجري‬\n‫إحلاقــه بالقــرار ثــم إعــادة املعاملــة حملكمــة االســتئناف املوقــرة باجلــوف‬\n‫وللبيــان حــرر يف ‪1434/5/11‬ه ـ وصلــى اهلل علــى نبينــا محمــد وآلــه‬\n                                                                 ‫وصحبــه وســلم ‪.‬‬\n‫احلمــد هلل وحــده وبعــد يف يــوم الســبت ‪1434/7/15‬ه ـ وبنــاء علــى‬\n‫رجــوع املعاملــة مــن مقــام محكمــة االســتئناف املوقــرة باجلــوف مبوجــب‬\n‫خطــاب رئيســها رقــم ‪ 341311683‬يف ‪1434/6/21‬ه ـ وبرفقــه القــرار‬\n‫الصــادر مــن الدائــرة اجلزائيــة اخلماســية األولــى رقــم ‪ 34240312‬يف‬\n\n\n                                                                                     ‫‪174‬‬\n\f      ‫‪1434/6/13‬ه ـ واملتضمــن املوافقــة علــى احلكــم وللبيــان حــرر يف‬\n                      ‫‪1434/7/15‬ه ـ وصلــى اهلل وســلم علــى نبينــا محمــد‪.‬‬\n\n\n\n\n‫‪175‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"41499c81-d627-5952-8b7f-c01b2e788165","source_page_start":156,"source_page_end":175,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"059cbcfe686387da26a539887b0e3f108461a41ae7e4f2491a4f07b5a5239ea5","normalized_text_hash":"63b6bc2c4c2c3a361089e52f15d9d6fd6c02ed801fd57fe04c51a68d78821bfc","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v27-p156-32312933"},{"id":"4c81a8a8-a694-5565-8175-0cd37a633021","document_type":"judgment","category":"judicial","subcategory":"general","title":"حرابة -قطع طريق -إخافة سبيل -حيازة ساح أبيض « سكني» -سلب مال -اشتراك يف جرمية -تعاطي مادة اإلمفيتامن -قيادة السيارة حتت تأثير املخدر -تقرير قصاص األثر -رد دعوى املدعي العام -تعزير للشبهة -تعزير بالسجن واجللد.","document_number":"33396148","case_number":"33399702","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالباحة و","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/8/27","year":"1434","subject":"حرابة -قطع طريق -إخافة سبيل -حيازة ساح أبيض « سكني» -سلب مال -اشتراك يف جرمية -تعاطي مادة اإلمفيتامن -قيادة السيارة حتت تأثير املخدر -تقرير قصاص األثر -رد دعوى املدعي العام -تعزير للشبهة -تعزير بالسجن واجللد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 33396148 :‬تاريخه‪1433/8/27:‬هـ‬\n                 ‫رقم الدعوى‪33399702 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 3425845‬تاريخه ‪1434/1/28 :‬هـ‬\n\n\n‫حرابــة ‪ -‬قطــع طريــق ‪ -‬إخافــة ســبيل ‪ -‬حيــازة ســاح أبيــض « ســكني»‬\n‫‪ -‬ســلب مــال ‪ -‬اشــتراك يف جرميــة ‪ -‬تعاطــي مــادة اإلمفيتامــن ‪ -‬قيــادة‬\n‫الســيارة حتــت تأثيــر املخــدر ‪ -‬تقريــر قصــاص األثــر ‪ -‬رد دعــوى املدعــي‬\n                        ‫العــام ‪ -‬تعزيــر للشــبهة‪ -‬تعزيــر بالســجن واجللــد‪.‬‬\n\n\n\n\n           ‫‪ -1‬قول اهلل تعالى ‪ ( :‬وال تفسدوا يف األرض بعد إصالحها )‪.‬‬\n‫‪ -2‬قولــه صلــى اهلل عليــه وســلم « املســلم مــن ســلم املســلمون مــن لســانه‬\n                                                                        ‫ويــده» ‪.‬‬\n\n\n\n\n‫الئحــة الدعــوى العامــة ضــد املدعــى عليهمــا باالشــتراك يف ارتــكاب‬\n‫جرميــة قطــع الطريــق‪ ،‬وإخافــة الســبيل‪ ،‬وذلــك بإشــهار الســاح األبيــض‬\n‫علــى شــخص‪ ،‬وســلبه مبلغـ ًا ماليـاً‪ ،‬وجهــاز جــوال وقيــادة ســيارة حتــت‬\n‫تأثيــر املخــدر‪ ،‬وتعاطــي مــادة اإلمفتامــن املنبــه احملظــورة‪ ،‬وطلــب‬\n‫املدعــي العــام إثبــات مــا اســند إليــه واحلكــم بإقامــة حــد احلرابــة‪،‬‬\n‫ومصــادرة الســيارة‪ ،‬ومصــادرة الســكني‪ ،‬واحلكــم عليهمــا بالســجن‬\n‫ومنعهمــا مــن الســفر‪ ،‬بعــد االنتهــاء مــن تنفيــذ العقوبــة وإثبــات إدانــة‬\n‫األول بقيــادة الســيارة حتــت تأثيــر املخــدر وإفهامــه بــأن عقابــه عائــد‬\n\n                                                                                    ‫‪176‬‬\n\f      ‫للجهــات املختصــة ‪ ،‬مت القبــض علــى املدعــى عليهمــا لوجــود بــاغ‬\n      ‫مــن مواطــن يفيــد بوجــود شــخص يف الطريــق يدعــى تعرضــه للتهديــد‬\n      ‫بالســاح األبيــض مــن نــوع ســكني مــن قبــل شــخصني ال يعرفهمــا‬\n      ‫وهمــا علــى ســيارة وأخــذا منــه جهــاز الهاتــف اجلــوال ومبلــغ مالــي بعــد‬\n      ‫إركابهمــا لــه يف ســيارة وإيهامهمــا لــه بالعمــل معهمــا مقابــل مبلــغ مالــي‬\n      ‫وقــد مت القبــض عليهمــا بعــد التعميــم عليهمــا مــن واقــع أوصافهمــا‪،‬‬\n      ‫مت عــرض الدعــوى علــى املدعــى عليهمــا فأجابــا باإلنــكار‪ ،‬مت طلــب‬\n      ‫البينــة مــن املدعــي العــام فأجــاب بــان بينتــه مــا يف أوراق املعاملــة‪ ،‬ووجــد‬\n      ‫فيهــا تقريــر األدلــة اجلنائيــة ومحضــر قصــاص األثــر ومحاضــر التعــرف‬\n      ‫والقبــض والتفتيــش وشــهادة املبلــغ‪ ،‬و التقريريــن الكيمائيــن‪ ،‬مت‬\n      ‫اطــاع حــكام القضيــة علــى البينــات وتقريــر عــدم وجــود بينــة موصلــة‬\n      ‫وبنــاء علــى مــا جــاء يف محضــر قصــاص األثــر وإفــادة املبلــغ ومحضــر‬\n      ‫التعــرف ومطابقــة مالبــس املدعــى عليهمــا حــن القبــض مــع مــا جــاء يف‬\n      ‫إفــادة املجنــي عليــه و هــذه قرائــن تقــوي التهمــة مــع مــا جــاء يف التقريــر‬\n      ‫الكيميائــي ولوجــود ســوابق علــى املدعــى عليــه األول فقــد صــدر‬\n      ‫احلكــم بــرد دعــوى املدعــي العــام بطلــب إقامــة حــد احلرابــة ومصــادرة‬\n      ‫الســيارة والســكني واحلكــم بالســجن واملنــع مــن الســفر وإدانــة األول‬\n      ‫بقيــادة الســيارة حتــت تأثيــر املخــدر‪ ،‬لعــدم ثبوتهــا‪ ،‬وتعزيــر املدعــى‬\n      ‫عليــه األول لقــاء التهمــة بالســجن عشــرة أشــهر وجلــده مائــه وخمســن‬\n      ‫جلــده مفرقــة علــى ثــاث دفعــات متســاوية‪ ،‬وتعزيــر املدعــى عليــه الثانــي‬\n      ‫لقــاء التهمــة املوجهــة إليــه بالســجن ثمانيــة أشــهر وجلــده مائــة وخمســن‬\n      ‫جلــده مفرقــة علــى ثــاث دفعــات متســاوية‪ ،‬ومت تصديــق احلكــم مــن‬\n                                                               ‫محكمــة االســتئناف‪.‬‬\n\n\n‫‪177‬‬\n\f‫احلمد هلل وحده والصالة والســام على من ال نبي بعده وبعد لدينا نحن‬\n‫‪ ....‬القاضــي باحملكمــة العامــة بالباحة و‪.......‬القاضي باحملكمة العامة‬\n‫بالباحــة ‪ ......‬القاضــي باحملكمــة العامــة بالباحــة وبنــاء علــى املعاملــة‬\n‫الــواردة إلينــا مــن هيئــة التحقيــق واالدعــاء العــام برقــم ه ـ ب ‪4320/2/1‬‬\n‫يف ‪1433/6/11‬ه ـ واحملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة‬\n‫بالباحــة برقــم ‪ 33399702‬وتاريــخ ‪1433/06/14‬ه ـ املقيــدة باحملكمــة‬\n‫برقــم ‪ 331110862‬وتاريــخ ‪ 1433/06/14‬ه ـ ويف يــوم االثنــن املوافــق‬\n‫‪1433/07/21‬ه ـ افتتحــت اجللســة الســاعة احلاديــة عشــرة وفيهــا حضــر‬\n‫املدعــي العــام ‪ .....‬حامــل الســجل املدنــي رقــم ‪ .....‬مبوجــب التكليــف‬\n‫رقــم ‪ 1/5978/8‬يف ‪1430/12/28‬ه ـ وقــدم الئحــة الدعــوى العامــة رقــم‬\n‫‪ 502‬لعــام ‪1433‬ه ـ واملرفقــة باملعاملــة علــى ســي دي والتــي جــاء فيهــا مــا‬\n‫نصــه‪ :‬أدعــي علــى كل مــن ‪ ..... /1‬ســعودي اجلنســية مبوجــب الســجل‬\n‫املدنــي رقــم ‪ .....‬العمــر ‪ 36‬عامــا ومهنتــه موظــف قطــاع خــاص موقــوف‬\n‫مبوجــب األمــر رقــم ‪ 2447/14/26‬وتاريــخ ‪1432/4/25‬ه ـ بالســجن‬\n‫العــام بالباحــة ‪ ..... /2‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n‫‪ ......‬العمــر ‪ 27‬عامــا ومهنتــه جنــدي أول بالشــرطة العســكرية اخلاصــة‬\n‫موفــوق مبوجــب األمــر رقــم ‪ 2448/14/26‬وتاريــخ ‪1432/4/25‬ه ـ‬\n‫بالســجن العــام بالباحــة أنــه بتاريخ‪1433/04/18‬ه ـ تلقــى مخفــر شــرطة‬\n‫(‪ )....‬مبحافظــة ‪ .....‬مبنطقــة ‪ ....‬بالغ ـ ًا مــن غرفــة العمليــات الرئيســية‬\n‫مفــاده وجــود مبلــغ يدعــى‪ .... /‬يفيــد بوجــود شــخص علــى طريــق ‪.....‬‬\n‫يدعــي أنــه تعــرض للتهديــد بســاح أبيــض مــن نــوع ســكني مــن قبــل‬\n\n                                                                                    ‫‪178‬‬\n\f      ‫شــخصني ال يعرفهمــا علــى ســيارة (‪ .... )....‬وأخــذا منــه جــوال ‪ .....‬ومبلــغ‬\n      ‫ســتمائة وعشــرين ريــاال (‪ )620‬بعــد إركابهمــا لــه يف تلــك الســيارة‬\n      ‫املشــار لهــا وإيهامــه بالعمــل لديهمــا مقابــل مبلــغ مالــي وباالنتقــال ملوقــع‬\n      ‫وجــد املبلــغ‪ .... /‬الــذي أفــاد بأنــه وجــد املجنــي عليــه على‬\n                                                                       ‫البــاغ واملعاينــة ِ‬\n      ‫طريــق ‪ ......‬وأبلغــه بســرقة جوالــه واملبلــغ املالــي الــذي بحوزتــه مــن قبــل‬\n      ‫شــخصني يركبــان ســيارة ‪ ......‬وأفــاد انــه شــاهد تلــك الســيارة خارجــة‬\n      ‫مــن نفــس املوقــع باجتــاه مركــز جــرب فقــام باإلبــاغ بهاتفــه اجلــوال‪،‬‬\n      ‫وجــد املجنــي عليــه مجهــول هويــة مــن اجلنســية الصوماليــة أســمى‬      ‫كمــا ِ‬\n      ‫نفســه ‪ .... /‬يبلــغ مــن العمــر (‪ )25‬ســنة أعــزب ومتعلــم بلغــة بــاده يجيــد‬\n      ‫التحــدث باللغــة العربيــة ديانتــه اإلســام (مت إحالتــه إلدارة الوافديــن بعــد‬\n      ‫تنازلــه عــن حقــه اخلــاص مبوجــب خطــاب الشــرطة رقــم ‪2455/14/26‬‬\n      ‫يف ‪1433/04/25‬هــ) وأفــاد بأنــه كان متجه ـ ًا مــن ‪ ....‬علــى قدميــه‬\n      ‫وحضــر لــه شــخصان يركبــان ســيارة صغيــرة قادمــن مــن ‪ .....‬واتفقــا‬\n      ‫معــه علــى رعــي الغنــم واصطحبــاه معهمــا يف الســيارة املشــار لهــا حيــث‬\n      ‫ركــب يف املرتبــة اخللفيــة وقاما بالســير مســافة ثــم توقفا بجانب الطريق‬\n      ‫ونــزل الســائق وقــام الراكــب الــذي يجلــس باملرتبــة األماميــة باإلمســاك‬\n      ‫بيديــه وهــو بداخــل الســيارة باملرتبــة اخللفيــة وفتــح الســائق عليــه بــاب‬\n      ‫الســيارة وهــدده بســكني وفتشــه وأخــذا منــه جــوال ‪ .....‬ومبلــغ ســتمائة‬\n      ‫وعشــرين ريــا ًال وتــركاه يف نفــس املوقــع ثــم حضــر لــه شــخصان ال‬\n      ‫يعرفهمــا وأبلغهمــا مبــا حــدث معــه وقامــا بإبــاغ الشــرطة وذكــر بــأن‬\n      ‫أوصــاف الســائق أبيــض البشــرة طويــل القامــة لــه ذقــن خفيــف يرتــدي‬\n      ‫بنطــا ًال أســود وفنيلــة بيضــاء اللــون أمــا الراكــب ملــيء اجلســم طويــل‬\n      ‫القامــة يلبــس ثوب ـ ًا ملون ـ ًا لــه ذقــن طويــل ‪ ،‬وأفــاد بأنــه يوجــد يف مرتبــة‬\n\n\n‫‪179‬‬\n\f‫الســيارة اخللفيــة ثــوب ملــون وعقــال أســود عندمــا ركــب فيهــا ‪ ،‬واتضــح‬\n‫إن اجلرميــة وقعــت علــى طريــق ‪ ......‬املــار مــن اجلنــوب باجتــاه الشــمال‬\n‫ويبعــد عــن مخفــر شــرطة ‪ ......‬قرابــة خمس ـ ًة وعشــرون كيلــو متــر ًا‬\n‫شــما ًال وهــو عبــارة عــن موقــع بــري بعيــد عــن العمــران والســكان تكثــر‬\n‫بــه أشــجار الســلم والســمر والعشــر ولوحــظ باملوقــع خــروج ســيارة مــن‬\n‫الطريــق املســفلت جهــة الغــرب يف مســيل وادي صغيــر ميــر مــن الشــرق‬\n‫باجتــاه الغــرب بدليــل وجــود آثــار إطاراتهــا يف نفــس املوقــع حتــى توقــف‬\n‫قائدهــا بــن أشــجار العشــر ولوحــظ باملوقــع آثــار أقــدام محتذيــة مــع‬\n‫وجــود محفظــة جلــد لونهــا بنــي وشــاحن جــوال ماركــة ‪ ....‬ومقــص شــعر‬\n‫صغيــر لونــه ‪ ...‬مبقبــض بالســتيك لونــه ‪ ...‬وقلــم أزرق ناشــف وقطعــة‬\n‫مــرآة صغيــرة ثــم رجــع قائــد تلــك الســيارة للخلــف ثــم اجتــه لألمــام‬\n‫مــرة أخــرى وكان اجتاهــه علــى شــكل انحــراف مــن جهــة الغــرب ثــم‬\n‫الشــمال ثــم الشــرق رجوعـ ًا للطريــق املســفلت طريــق جــرب القوامــة وقــد‬\n‫مت توثيــق املعاينــة بالتصويــر الفوتوغــرايف ‪ ،‬وحضــرت األدلــة اجلنائيــة‬\n‫وقامــت برفــع آثــار األقــدام وآثــار اإلطــارات مــن موقــع اجلرميــة كمــا‬\n‫حضــر قصــاص األثــر وقــام برفــع اآلثــار مــن مســرح اجلرميــة مت التعميــم‬\n‫يف حينــه عــن الســيارة واألشــخاص املشــتبه بهمــا مــن واقــع أوصافهمــا‬\n‫يف البــاغ ومت القبــض عليهمــا يف الســيارة املنــوه عنهــا مــن نــوع ‪ ......‬اللــون‬\n‫حتمــل اللوحــة رقــم (‪ ).....‬بقيــادة املدعــى عليــه األول يرافقــه املدعــى‬\n‫عليــه الثانــي وتعــود ملكيتهــا للمدعــو‪ ........ /‬مــن قبــل دوريــات مخفــر‬\n‫شــرطة كــرا احلائــط بتاريخ‪1433/4/18‬ه ـ واتضــح إنهمــا املدعــى‬\n‫عليهمــا أعــاه ومبعاينــة الســيارة ‪ .....‬حتمــل لوحــة رقــم (‪ )....‬اتضــح‬\n‫وجــود الثــوب امللــون بداخلهــا يف املــكان الــذي أشــار لــه املجنــي عليــه‬\n\n\n                                                                                         ‫‪180‬‬\n\f      ‫كمــا مت العثــور علــى ســكني بداخــل الســيارة املنــوه عنهــا وبســماع‬\n      ‫أقــوال املدعــو ‪ ...‬أفــاد بأنــه بــاع تلــك الســيارة علــى املدعــى عليــه الثانــي‬\n      ‫مبوجــب كمبيــاالت ولــم ُينقــل ملكيتهــا باســم املشــتري وقــدم صــورة‬\n      ‫مــن كمبيــاالت املبايعــة املرفقــة لفــة (‪ )95‬وبعــرض املدعــى عليهمــا‬\n      ‫ضمــن مجموعــة أشــخاص علــى الوافــد املجنــي عليــه أســتطاع ذلــك‬\n      ‫الوافــد التعــرف عليهمــا وبعــرض الســيارة املنــوه عنهــا علــى املجنــي عليــه‬\n      ‫اســتطاع التعــرف عليهــا وبعــرض الســكني التــي مت ضبطهــا بداخــل‬\n      ‫الســيارة املشــار إليهــا ضمــن مجموعــة ســكاكني اســتطاع املجنــي‬\n      ‫عليــه التعــرف عليهــا وأفــاد بأنهــا نفــس الســكني التــي قــام قائــد تلــك‬\n      ‫الســيارة بتهديــده بهــا ‪ ،‬أثبــت التقريــر الفنــي املرفــق الصــادر مــن األدلــة‬\n       ‫اجلنائيــة برقــم (‪ 199/14/26‬د) يف (‪1433/04/24‬هــ) تشــابه إلــى حــدٍ‬\n      ‫كبيــر آثــار اإلطــارات يف موقــع القضية مع إطارات الســيارة املشــتبه بها‬\n      ‫وتشــابه إلــى حــدٍ كبيــر أثــر األقــدام يف موقــع القضيــة مــع حــذاء املدعى‬\n      ‫عليــه األول ‪ ،‬أثبــت تقريــر قصــاص األثــر بــأن أثــر اإلطــارات يف موقــع‬\n      ‫القضيــة يعــود للســيارة ‪ ......‬التــي مت ضبطهــا بحوزة املدعى عليهما كما‬\n      ‫ورد التقريــران الكيميائيــان الشــرعيان رقــم ‪ /9857‬س‪1433/3‬ه ـ‬\n      ‫ورقم‪/9858‬س‪1433/3‬ه ـ الصــادران مــن مركــز مراقبــة الســموم‬\n      ‫والكيميــاء الشــرعية مبنطقــة مكــة املكرمــة مثبت ـ ًا أن العينتــن‬\n      ‫املرســلتني للتحليــل دم‪ /‬وبــول باحلــرز الســري رقــم (‪ )12‬ورقــم(‪-)13‬‬\n      ‫العائدتــن للمتهمــن حســب البيــان املرفــق لفــة(‪ -)61‬حتتويــان علــى‬\n      ‫مــادة االمفيتامــن املنبــه احملظــور وهــو مــن املــواد املدرجــة بجــداول املــواد‬\n      ‫املخــدرة واملؤثــرات العقليــة املرفقــة بالتعميــم البرقــي لصاحــب الســمو‬\n      ‫امللكــي وزيــر الداخليــة رقــم ‪ 89400/19‬يف ‪1426/10/15‬ه ـ والصادر‬\n\n\n‫‪181‬‬\n\f‫املرســوم امللكــي الكــرمي رقــم م‪ 39/‬يف ‪1426/7/8‬ه ـ وبالبحــث عــن‬\n‫ســوابقهما اتضــح عــدم وجــود ســوابق مســجلة علــى املدعــى عليــه الثانــي‬\n‫فيمــا اتضــح وجــود ثــاث ســوابق مســجلة علــى املدعــى عليــه األول وهــي‪:‬‬\n‫األولــى‪ /‬حيــازة قــات ‪ ،‬والثانيــة‪ /‬ســرقة أمــوال والثالثــة‪ /‬مقاومــة رجــال‬\n‫األمــن ‪ ،‬هــروب مــن الســلطة العامــة ‪ ،‬ســرقة ‪ ،‬وباســتجواب املدعــى‬\n‫عليهمــا أنكــرا مــا نســب إليهمــا جمل ـ ًة وتفصيــا وأقــر املدعــى عليــه‬\n‫الثانــي بــأن الســيارة املنــوه عنهــا اشــتراها مــن املدعــو ‪ ......‬املشــار إليــه‬\n‫منــذ ســنتني ولــم يقــم بنقــل ملكيتهــا ‪ ،‬وانتهــى التحقيــق إلــى توجيــه‬\n‫االتهــام لــكل مــن‪ ...... /‬و ‪ .....‬باالشــتراك يف ارتــكاب جرميــة قطــع‬\n‫الطريــق وإخافــة الســبيل وذلــك بإشــهار الســاح األبيــض علــى شــخص‬\n‫وســلبه مبلغ ـ ًا مالي ـ ًا وقــدره ســتمائة وعشــرون ريــال وجهــاز جــوال علــى‬\n‫ســبيل الغلبــة والقهــر احملــرم شــرع ًا وتعاطــي مــادة االمفيتامــن املنبــه‬\n‫احملظــور احملــرم شــرع ًا ونظامـ ًا مبوجــب الفقــرة الثانيــة مــن املــادة الثالثة‬\n‫مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم‬\n‫امللكــي رقــم (م‪ )39/‬لعــام ‪1426‬ه ـ وقيــادة الســيارة حتــت تأثيــر املخــدر‬\n‫لألدلــة والقرائــن التاليــة ‪ -1 :‬محضــر االنتقــال واملعاينــة املنــوه عنــه‬\n‫املــدون علــى ص (‪ )4-1‬مــن ملــف االســتدالل املرفــق لفــه (‪ )4‬وص (‪)4‬‬\n‫مــن ملــف التحقيــق املرفــق لفــه رقــم (‪ -2 . )1‬تقريــر األدلــة اجلنائيــة املنــوه‬\n‫عنــه املرفــق لفــه (‪ -3 )30-24‬تقريــر قصــاص األثــر املنــوه عنــه املــدون‬\n‫علــى ص (‪ )8‬مــن ملــف التحقيــق املرفــق لفــه رقــم (‪ -4 . )2‬محاضــر‬\n‫التعــرف املنــوه عنهــا املدونــة علــى ص (‪ )6-3‬مــن ملــف التحقيــق املرفــق‬\n‫لفــه رقــم (‪ -5 .)2‬محضــر القبــض والتفتيــش املنــوه عنــه املرفــق لفــة‬\n                                                                               ‫(‪. )32‬‬\n\n\n                                                                                          ‫‪182‬‬\n\f      ‫‪ -6‬مــا ورد بشــهادة املبلــغ املنــوه عنهــا املدونــة علــى ص (‪ )6-5‬مــن‬\n      ‫ملــف التحقيــق املرفــق رقــم (‪ -7 . )4‬التقريريــن الكيميائيــن املنــوه‬\n      ‫عنهمــا املرفقــن لفــه رقــم (‪ )102‬و لفــه رقــم (‪ ، )103‬وحيــث إن مــا‬\n      ‫أقــدم عليــه املذكــوران وهمــا بكامــل أهليتهمــا املعتبــرة شــرع ًا فعــل‬\n      ‫محــرم ومعاقــب عليــه شــرع ًا لــذا أطلــب إحالتهمــا إلــى احملكمــة‬\n      ‫العامــة اســتناد ًا للمادتــن(‪ )129(،)126‬مــن نظــام اإلجــراءات اجلزائيــة‬\n      ‫إلثبــات إدانتهمــا مبــا أســند إليهمــا واحلكــم عليهمــا بحــد احلرابــة الــوارد‬\n      ‫يف اآليــة الكرميــة رقــم (‪ ) 33‬مــن ســورة املائــدة يف ضــوء قــرار هيئــة‬\n      ‫كبــار العلمــاء رقــم (‪ )85‬وتاريــخ ‪1401/1/11‬ه ـ واحلكــم مبصــادرة‬\n      ‫الســيارة ‪ -‬بعــد تعديــل وضعهــا النظامــي إلــى ملكيــة املتهــم الثانــي‬\n      ‫‪ -‬ومصــادرة الســكني املنــوه عنهــا لكونهــا مســتخدمة يف اجلرميــة‬\n      ‫واحلكــم عليهمــا بالســجن اســتناد ًا للفقــرة األولــى مــن املــادة احلاديــة‬\n      ‫واألربعــن مــن نظــام مكافحــة املخــدرات املشــار إليــه ومنعهمــا مــن‬\n      ‫الســفر إلــى خــارج اململكــة بعــد االنتهــاء مــن تنفيــذ العقوبــة اســتناد ًا‬\n      ‫للفقــرة األولــى مــن املــادة السادســة واخلمســن مــن ذات النظــام وإثبــات‬\n      ‫إدانــة األول بقيادتــه للســيارة حتــت تأثيــر املخــدر وإفهامــه بــأن عقابــه‬\n      ‫علــى ذلــك عائــد للجهــة املختصــة علمـ ًا بــأن احلــق اخلــاص انتهــى بالتنــازل‬\n      ‫هــذه دعــواي وبعــرض مــا جــاء يف دعــوى املدعــي العــام علــى املدعــي‬\n      ‫عليهمــا وســؤالهما عنهــا أجــاب كل منهمــا بقولــه مــا جــاء يف دعــوى‬\n      ‫املدعــي العــام مــن اتهامــي باالشــتراك يف ارتــكاب جرميــة قطــع الطريــق‬\n      ‫وإخافــة الســبيل بإشــهار الســاح األبيــض علــى الشــخص وســلبه مبلغــا‬\n      ‫مالــي قــدره ســتمائة وعشــرون ريــاال وجهــاز جــوال علــى ســبيل الغلبــة‬\n      ‫والقهــر وتعاطــي االمفيتامــن املنبــه احملظــور وقيــادة الســيارة حتــت‬\n\n\n‫‪183‬‬\n\f‫تأثيــر املخــدر كلــه غيــر صحيــح هكــذا أجــاب وبســؤال املدعــي العــام‬\n‫هــل لديــك بينــة أجــاب قائــا لــدي مــا يف أوراق املعاملــة أطلــب الرجــوع‬\n‫إليهــا هكــذا أجــاب ثــم رفعــت اجللســة لالطــاع علــى أوراق املعاملــة إلــى‬\n‫يــوم اإلثنــن املوافــق ‪1433/8/26‬ه ـ ويف املوعــد احملــدد افتتحــت اجللســة‬\n‫وفيهــا حضــر املدعــي العــام ‪ ......‬حامــل الســجل املدنــي رقــم ‪ ...‬املكلــف‬\n‫مــن قبــل رئيــس فــرع هيئــة التحقيــق بالباحــة بخطابهــم الــوارد إلينــا برقــم‬\n‫ه ـ ب ‪ 5830/2/1‬يف ‪1433/8/11‬ه ـ وحضــر املدعــى عليهمــا ثــم جــرى‬\n‫منــا الرجــوع إلــى أوراق املعاملــة لالطــاع عليهــا فجــرى االطــاع علــى‬\n‫محضــر االنتقــال واملعاينــة املــدون علــى الصحيفــة رقــم ‪ 4-1‬مــن ملــف‬\n‫التحقيــق املرفــق باملعاملــة لفــة رقــم ‪ 4‬فوجدنــاه تضمــن وصف ـ ًا ملوقــع‬\n‫احلادثــة وأنــه تبــن باملعاينــة وجــود آثــار إلطــارات ســيارة وأن اإلطاريــن‬\n‫األماميــن مختلفــن ويظهــر مــن األثــر أنهمــا مســتخدمان ملــدة طويلــة‬\n‫وأمــا اإلطاريــن اخللفيــن فهمــا مــن نــوع واحــد وحالتهــا جديــدة كمــا‬\n‫شــوهد أثــر أقــدام وأنــه مبقارنــة آثــار إطــارات ســيارة املدعــى عليهمــا‬\n‫‪ .....‬ومقارنــة آثــار األقــدام بأحذيــة املدعــى عليهمــا ظهــر أن آثــار إطــارات‬\n‫مســرح اجلرميــة عائــدة للســيارة املشــتبه بهــا كمــا أن هنــاك أثــر لقــدم‬\n‫يســرى يف مســرح اجلرميــة ينطبــق علــى حــذاء املتهــم ‪ .....‬انتهــى مضمونــه‬\n‫وبعــرض مــا جــاء فيــه علــى املدعــى عليهمــا أنكــرا صحــة مــا جــاء فيــه‬\n‫ثــم جــرى االطــاع علــى تقريــر األدلــة اجلنائيــة املرفــق باملعاملــة لفــة رقــم‬\n‫‪ 30-24‬فوجدنــاه تضمــن صــور ًا إلطــارات الســيارة املشــتبه بهــا العائــدة‬\n‫للمدعــى عليــه الثانــي وصــور ًا آلثــار اإلطــارات يف موقــع احلادثــة كمــا‬\n‫تضمــن صــورة حلــذاء املدعــى عليــه ‪ ...‬وصــورة ألثــر متشــابه معهــا يف‬\n‫موقــع احلادثــة كمــا تضمــن التقريــر الفنــي يف النتيجــة مــا نصــه «مت‬\n\n\n                                                                                         ‫‪184‬‬\n\f      ‫مضاهــاة الصــور وتبــن أنهــا متشــابه إلــى حــد كبيــر مــع أن ذلــك ال‬\n      ‫يعطــي نتيجــة قطعيــة حيــث أن اآلثــار ملــاركات ويصنــع منهــا العديــد‬\n      ‫بنفــس الشــكل وليســت ببصمــة ثانيــة « انتهــى نصــه ثــم جــرى االطــاع‬\n      ‫علــى تقريــر قصــاص األثــر املــدون علــى الصحيفــة رقــم ‪ 8‬مــن ملــف‬\n      ‫التحقيــق املرفــق باملعاملــة لفــة رقــم ‪ 2‬فوجدنــاه تضمــن مــا نــص احلاجــة‬\n      ‫منــه «وبعــد شــخوصي علــى اآلثــار املشــار إليهــا يف مــكان القضيــة‬\n      ‫ومعاينــة إطــارات الســيارة املشــتبه بهــا واملوجــودة يف مخفــر شــرطة‬\n      ‫جــرب أقــرر اآلتــي ‪ /1 :‬آثــار اإلطــارات يف مــكان القضيــة علــى طريــق‬\n      ‫‪ ......‬تنطبــق علــى إطــارات الســيارة املشــتبه بهــا مــن نــوع ‪ ....‬لوحــة رقــم‬\n      ‫(‪ /2 )....‬فيمــا يتعلــق بآثــار األقــدام يف مــكان اجلرميــة لــم تكــن واضحــة‬\n      ‫لــي بالشــكل املطلــوب ولــم نتمكــن مــن مقارنتهــا مــن قبلــي مــع آثــار‬\n      ‫أقــدام الوافــد املبلــغ واملشــتبه بهــم علــى ذمــة القضيــة « انتهــى نصــه وذيــل‬\n      ‫بتوقيــع قصــاص األثــر ‪ ، ........‬ثــم جــرى االطــاع علــى محضــر التعــرف‬\n      ‫املــدون علــى الصحيفــة رقــم ‪ 3‬مــن امللــف املرفــق باملعاملــة لفــة رقــم ‪2‬‬\n      ‫واملــؤرخ يف ‪1433/4/18‬ه ـ فوجدنــاه تضمــن عــرض املدعــى عليهمــا مــع‬\n      ‫عــدة أشــخاص علــى الوافــد املدعــو ‪ ....‬فتعــرف علــى املدعــى عليهمــا‬\n      ‫انتهــى مضمونــه وبعرضــه علــى املدعــى عليهمــا أجابــا بقولهمــا إن‬\n      ‫احملقــق كان يحقــق معنــا قبــل العــرض وهــذا الوافــد يشــاهدنا طــوال‬\n      ‫مــدة التحقيــق هكــذا أجابــا كمــا تضمــن امللــف علــى الصحيفــة رقــم‬\n      ‫‪ 5-4‬محضــر تعــرف الوافــد علــى ســيارة املدعــى عليهمــا ‪ ،‬كمــا تضمــن‬\n      ‫أن األوصــاف التــي ذكرهــا املبلــغ لشــكل ومالبــس املدعــى عليهمــا‬\n      ‫كانــت مطابقــة لألشــخاص املشــتبه بهــم ا‪.‬ه ـ كمــا جــرى االطــاع على‬\n      ‫محضــر االتصــال املــدون بالصحيفــة رقــم ‪ 5‬مــن امللــف املرفــق باملعاملــة‬\n\n\n‫‪185‬‬\n\f‫لفــة رقــم ‪ 4‬فوجدنــاه تضمــن إفــادة املبلــغ املدعــو ‪ .....‬بأنــه يف يــوم الســبت‬\n‫املوافــق ‪1433/4/18‬ه ـ عنــد وصولــه جــرب ركــب مــع ابنــه متجهــن‬\n‫ملركــز ‪ ......‬عبــر طريــق ‪ ......‬وكان ذلــك بعــد الظهــر وأثنــاء ســيرهم‬\n‫شــاهد ســيارة ‪ ......‬مــن (‪ ).....‬خارجــة مــن مــكان بــري بجانــب طريــق‬\n‫‪ .....‬إلــى اإلســفلت متجهــة باجتــاه مركــز ‪ .....‬يركبهــا شــخصني ثــم‬\n‫رأى شــخص أســود البشــرة يجــري خلــف تلــك الســيارة فتوقــف عنــده‬\n‫ولــم يأخــذ رقــم لوحــة الســيارة وال أوصــاف ســائقها ومرافقــه انتهــى‬\n‫مضمونــه ثــم جــرى االطــاع علــى التقريــر الكيميائــي الشــرعي رقــم‬\n‫‪/3857‬س ص‪1433/‬ه ـ الصــادر مــن مركــز مراقبــة الســموم مبنطقــة‬\n‫مكــة املكرمــة واملرفــق باملعاملــة لفــة رقــم ‪ 103‬فوجدنــاه تضمــن‬\n‫أن عينــة الــدم والبــول املأخــوذة مــن رقــم (‪12‬س) العمــر ‪ 35‬عــام ثبــت‬\n‫أنهــا حتتــوي علــى مــادة االمفيتامــن ا‪ .‬ه ـ كمــا جــرى االطــاع علــى‬\n‫التقريــر الكيميائــي الشــرعي رقــم ‪/9858‬س‪1433/3‬ه ـ الصــادر مــن‬\n‫مركــز مراقبــة الســموم مبنطقــة مكــة املكرمــة واملرفــق باملعاملــة‬\n‫لفــة رقــم ‪ 104‬فوجدنــاه تضمــن أن عينــة الــدم والبــول املأخــوذة مــن‬\n‫(‪13‬س) العمــر ‪ 27‬عــام ثبــت أنهــا حتتــوي علــى مــادة االمفيتامــن‬\n‫انتهــى مضمونــه وبعرضهــا علــى املدعــى عليهمــا أنكــرا صحــة مــا جــاء‬\n‫فيهــا كمــا جــرى االطــاع علــى صحيفــة ســوابق املدعــى عليــه األول‬\n‫‪ ...‬واملرفقــة باملعاملــة لفــة رقــم ‪ 57-55‬فوجدنــاه تضمــن تســجيل ثــاث‬\n‫ســوابق علــى املدعــى عليــه األولــى حيــازة قــات والثانيــة ســرقة أمــوال‬\n‫مســجلة عليــه عــام ‪1423‬ه ـ والثالثــة مقاومــة رجــال األمــن وهــروب مــن‬\n‫الســلطة وســرقة مســجلة عليــه يف عــام ‪1432‬ه ـ وبعرضهــا علــى املدعــى‬\n‫عليــه األول وســؤاله عنهــا صــادق علــى صحتهــا وقــرر قائــا أن الســرقة‬\n\n\n                                                                                         ‫‪186‬‬\n\f      ‫األولــى غيــر صحيحــة حيــث أن جــدي ألمــي تقــدم علــي ببــاغ كاذب‬\n      ‫نظــرا ألننــي أخــذت مــال لــي مــن جدتــي فقــط ‪ ،‬والســرقة األخيــرة‬\n      ‫كذلــك غيــر صحيحــة وهــي مضاربــة وإطــاق نــار فقــط هكــذا قــرر‬\n      ‫‪ ،‬كمــا جــرى االطــاع علــى صحيفــة ســوابق املدعــى عليــه الثانــي علــي‬\n      ‫املرفقــة باملعاملــة لفــة رقــم ‪ 42‬فوجدناهــا تضمنــت عــدم تســجيل ســوابق‬\n      ‫عليــه ا‪.‬ه ـ ‪ ،‬وبســؤال املدعــي العــام واملدعــى عليهمــا إن كان لديهمــا مــا‬\n      ‫يــودان إضافتــه علــى مــا ســبق ضبطــه قــرر كل منهــم بقولــه ليــس لــدي‬\n      ‫ســوى مــا ســبق فقفلنــا بــاب املرافعــة وبنــاء علــى مــا تقــدم مــن الدعــوى‬\n      ‫واإلجابــة ومــا قــرره الطرفــان ونظــرا إلنــكار املدعــى عليهمــا جميــع مــا‬\n      ‫نســبه إليهمــا املدعــي العــام يف دعــواه ونظــرا لعــدم وجــود بينــة موصلــة‬\n      ‫لــدى املدعــي العــام وبنــاء علــى مــا جــاء يف أوراق املعاملــة املرصــود نصهــا‬\n      ‫أعــاه مــن تقريــر قصــاص األثــر ومــا جــاء يف إفــادة املبلــغ ‪ .....‬ومــا جــاء‬\n      ‫يف محضــر التعــرف ومطابقــة أوصــاف مالبــس املدعــى عليهمــا حــن‬\n      ‫القبــض عليهمــا مــع مــا جــاء يف إفــادة املجنــي عليــه ونظــرا إلــى أن هــذه‬\n      ‫مبجموعهــا قرائــن ترجــح جانــب التهمــة بحــق املدعــى عليهمــا مبــا نســب‬\n      ‫إليهمــا مــن قطــع الطريــق وإخافــة الســبيل وســلب الوافــد ‪ ،‬وبنــاء علــى‬\n      ‫مــا جــاء يف التقاريــر الكيميائيــة للمدعــى عليهمــا املتضمنــة إيجابيــة‬\n      ‫العينــات املأخــوذة منهمــا ملــادة االمفيتامــن احملظــورة احملرمــة شــرعا‬\n      ‫ونظــرا لوجــود ســوابق علــى املدعــى عليــه األول األمــر الــذي يؤخــذ يف‬\n      ‫احلســبان عنــد تقديــر العقوبــة ونظــرا إلــى أن مــا نســب للمدعــى عليهمــا‬\n      ‫وتوجهــت التهمــة لهمــا بــه عمــل محــرم شــرعا وجــرأة يف الباطــل ومــن‬\n      ‫اإلفســاد يف األرض واهلل ســبحانه يقول يف كتابه العزيز ((وال تفســدوا‬\n      ‫يف األرض بعــد إصالحهــا)) ويقــول عليــه الصــاة والســام (( املســلم مــن‬\n\n\n‫‪187‬‬\n\f                                            ‫ســلم املســلمون مــن لســانه ويــده ))‪.‬‬\n‫ونظــرا ألن املدعــى عليهمــا يســتحقان العقوبــة طبقــا للقواعــد الشــرعية‬\n‫وبنــاء علــى القاعــدة الشــرعية املقــررة مــن أهــل العلــم بــأن اخلطــأ يف‬\n‫العفــو خيــر مــن اخلطــأ يف العقوبــة ونظــرا لضعــف التهمــة املوجهــة‬\n‫للمدعــى عليهمــا وعــدم وجــود ســوابق للمدعــى عليــه الثانــي وانتهــاء احلق‬\n‫اخلــاص بالتنــازل ولــكل مــا تقــدم فقــد توجهــت التهمــة للمدعــى عليهمــا‬\n‫باالشــتراك يف جرميــة قطــع الطريــق وإخافــة الســبيل وســلب وافــد علــى‬\n‫ســبيل الغلبــة والقهــر وتوجــه التهمــة لهمــا بتعاطــي مــادة االمفيتامــن‬\n‫املنبهــة احملظــورة واحملرمــة شــرعا وحكمنــا مبــا يلــي‪ :‬أوال ‪/‬رد دعــوى‬\n‫املدعــي العــام بطلــب إقامــة حــد احلرابــة ومصــادرة الســيارة والســكني‬\n‫واحلكــم بالســجن وفقــا للمــادة رقــم ‪ 41‬مــن نظــام مكافحــة املخــدرات‬\n‫واملنــع مــن الســفر وإدانــة األول بقيــادة الســيارة حتــت تأثيــر املخــدر لعــدم‬\n‫ثبــوت موجبهــا‪ .‬ثانيــا‪ /‬تعزيــر املدعــى عليــه األول ‪ ....‬لقــاء التهمــة املوجهــة‬\n‫إليــه وذلــك بســجنه مــدة عشــرة أشــهر حتســب منهــا مــدة إيقافــه بســبب‬\n‫هــذه القضيــة وجلــده مائــة وخمســون جلــدة مفرقــة علــى ثــاث دفعــات‬\n‫قــدر كل دفعــة خمســون جلــدة وبــن كل دفعــة وأخــرى عشــرة أيــام‪.‬‬\n‫ثالثــا‪ /‬تعزيــر املدعــى عليــه الثانــي لقــاء التهمــة املوجهــة إليــه وذلــك‬\n‫بســجنه مدة ثمانية أشــهر يتحســب منها مدة إيقافه بســبب هذه القضية‬\n‫وجلــده مائــة وخمســون جلــدة مفرقــة علــى ثــاث دفعــات قــدر كل دفعــة‬\n‫خمســون جلــدة وبــن كل دفعــة وأخــرى عشــرة أيــام وبعــرض احلكــم‬\n‫علــى املدعــي العــام و املدعــى عليهمــا قــرر املدعــى عليهمــا قناعتهمــا بــه‬\n‫وقــرر املدعــي العــام اعتراضــه عليــه مســتعدا بتقــدمي الئحــة اعتراضيــة‬\n‫فأفهــم باملراجعــة يــوم األربعــاء املوافــق ‪1433/8/28‬ه ـ الســتالم نســخة‬\n\n\n                                                                                         ‫‪188‬‬\n\f      ‫مــن القــرار وتقــدمي الئحتــه االعتراضيــة عليــه خــال ثالثــن يومــا مــن‬\n      ‫تاريخــه وإذا لــم يتقــدم باعتراضــه خــال املــدة فســيتم رفــع كامــل أوراق‬\n      ‫املعاملــة حملكمــة االســتئناف بــدون الئحتــه ففهــم ذلــك وختمــت اجللســة‬\n      ‫الســاعة احلاديــة عشــرة وأربعــن دقيقــة وصلــى اهلل علــى نبينــا محمــد‬\n                                   ‫وآلــه وصحبــه وســلم‪ .‬حــرر يف ‪1433/8/26‬ه ـ‬\n                 ‫احلمد هلل وحده والصالة والسالم على من ال نبي بعده ‪ ،‬وبعد‪:‬‬\n      ‫فقــد جــرى منــا نحــن قضــاة الدائــرة اجلزائيــة اخلماســية الثالثــة‬\n      ‫مبحكمــة االســتئناف مبنطقــة مكــة املكرمــة االطــاع علــى املعاملــة‬\n      ‫الــواردة مــن فضيلــة رئيــس احملكمــة العامــة بالباحــة برقــم ‪3469720‬‬\n      ‫وتاريــخ ‪1434/1/10‬ه ـ املرفــق بهــا القــرار رقــم ‪ 33396148‬وتاريــخ‬\n      ‫‪1433/8/27‬ه ـ الصــادر مــن أصحــاب الفضيلــة القضــاة باحملكمــة‬\n      ‫العامــة بالباحــة الشــيخ ‪ .....‬والشــيخ ‪ .....‬والشــيخ ‪ .....‬املتضمــن دعــوى‬\n      ‫املدعــي العــام ضــد‪ ..... /‬ورفيقــه ‪ ،‬املتهمــن يف ســلب ‪ ،‬احملكــوم فيــه‬\n      ‫مــا دون باطنــه ‪ .‬وبدراســة احلكــم وصــورة ضبطــه والئحتــه االعتراضيــة‬\n      ‫تقــررت املوافقــة علــى احلكــم ‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n                                              ‫محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪189‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"41499c81-d627-5952-8b7f-c01b2e788165","source_page_start":176,"source_page_end":189,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"15c6f8263f1e22c59c535edf43c65a42bf945b3c8a92f6c138e05a2ecf9ed715","normalized_text_hash":"e2e60af4b2ed1013079a4c6287b65c7cb2eea1074889da32288fa81c46867851","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v27-p176-33396148"},{"id":"6d88fcab-746c-5acc-913b-90abb8d06f7c","document_type":"judgment","category":"judicial","subcategory":"general","title":"حرابة -اغتصاب -خلوة محرمة -إقامة عالقة مع فتاة -استدراج فتاة وفعل الفاحشة بها بالقوة -اإلقرار بفعل الفاحشة وإيواء فتاة وإنكار االستدراج واستعمال القوة -رد دعوى احلرابة -احلكم بحد الزاني غير احملصن -تعزيره بالسجن واجللد.","document_number":"3441136","case_number":"33553652","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة باخلبر","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/19","year":"1434","subject":"حرابة -اغتصاب -خلوة محرمة -إقامة عالقة مع فتاة -استدراج فتاة وفعل الفاحشة بها بالقوة -اإلقرار بفعل الفاحشة وإيواء فتاة وإنكار االستدراج واستعمال القوة -رد دعوى احلرابة -احلكم بحد الزاني غير احملصن -تعزيره بالسجن واجللد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫رقم الصك‪ 3441136 :‬تاريخه‪1434/2/19 :‬هـ‬\n                   ‫رقم الدعوى‪33553652 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 34182762‬تاريخه‪1434/4/8 :‬هـ‬\n\n\n‫حرابــة ‪ -‬اغتصــاب ‪ -‬خلــوة محرمــة ‪ -‬إقامــة عالقــة مــع فتــاة ‪ -‬اســتدراج‬\n‫فتــاة وفعــل الفاحشــة بهــا بالقــوة ‪ -‬اإلقــرار بفعــل الفاحشــة وإيــواء فتــاة‬\n‫وإنــكار االســتدراج واســتعمال القــوة ‪ -‬رد دعــوى احلرابــة ‪ -‬احلكــم بحــد‬\n                         ‫الزانــي غيــر احملصــن ‪ -‬تعزيــره بالســجن واجللــد‪.‬‬\n\n\n\n\n‫‪ -1‬قــول اهلل تعالــى‪« :‬والزانيــة والزانــي فاجلــدوا كل واحــد منهمــا‬\n                                                               ‫مائــة جلــدة»‪.‬‬\n‫‪ -2‬عــن عبــادة بــن الصامــت أن النبــي صلــى اهلل عليــه وســلم قــال‪« :‬البكر‬\n                          ‫بالبكــر جلــد مائــة وتغريــب عام» أخرجه مســلم‪.‬‬\n\n\n\n\n‫جــرى توجيــه االتهــام مــن املدعــي العــام للمدعــى عليــه باســتدراج فتــاة‬\n‫وفعــل فاحشــة الزنــا بهــا بالقــوة بعــد التغريــر بهــا وطلــب إثبــات مــا أســند‬\n‫إليــه وإقامــة حــد احلرابــة والزانــي احملصــن عليــه حيــث تلقــت الشــرطة‬\n‫بالغــا عــن دخــول فتــاة املستشــفى لتعرضهــا العتــداء وبضبــط أقوالهــا‬\n‫قــررت بأنهــا تعرفــت علــى شــخص عبــر الهاتــف تطــورت لعالقــة فطلــب‬\n‫منهــا أن يراهــا للــزواج بهــا فخرجــت معــه فذهــب بهــا الســتراحة يف‬\n‫مــكان بعيــد فطلــب منهــا أن تدخــل غرفــة النــوم ثــم قام بإنزال مالبســها‬\n\n                                                                                         ‫‪190‬‬\n\f      ‫وفعــل الفاحشــة بهــا بالقــوة وبعــد التحــري عنــه جــرى القبــض عليــه وأقــر‬\n      ‫بوجــود عالقــة بينــه وبــن الفتــاة عــن طريــق الهاتــف وأنــه ركبــت معــه‬\n      ‫مــرة وأنهــا رفضــت الرجــوع ملنزلهــا وطلبــت منــه الــزواج فأخذهــا لغرفتــه‬\n      ‫وفعــل الفاحشــة بهــا بإيــاج برضاهــا مرتــن وأنــه قــام بفــض بكارتهــا‬\n      ‫‪ ،‬أقــر املدعــى عليــه بأنــه قــام بإيــواء الفتــاة يومــا كامــا وفعــل بهــا‬\n      ‫الفاحشــة بإيــاج برضاهــا وأنــه غيــر محصــن لــم يســبق لــه الــزواج‬\n      ‫ونــادم علــى مــا صــدر منــه وال صحــة بأنــه قــام باســتدراجها وأنهــا بالغــة‬\n      ‫راشــدة وأنهــا مــن قامــت باالتصــال بــه وذكــرت بأنهــا علــى الكورنيــش‬\n      ‫وركبــت معهــا بطوعهــا ورفضــت أن تعــود لبيــت أهلهــا ‪ ،‬جــرى ســؤال‬\n      ‫املدعــي العــام البينــة فقــرر بــأن بينتــه مــا ورد يف أوراق املعاملــة وبالرجــوع‬\n      ‫لهــا لــم يظهــر منهــا مــا يــدل علــى اســتدراجها ‪ ،‬وألن املدعــى عليــه آوى‬\n      ‫الفتــاة وأخفاهــا عــن أهلهــا إضافــة لفعــل الفاحشــة بهــا لــذا فلــم يثبــت‬\n      ‫لــدى الدائــرة مــا يوجــب إقامــة حــد احلرابــة علــى املدعــى عليــه وحكمــت‬\n      ‫عليــه بجلــده مئــة جلــدة دفعــة واحــدة وســجنه ســنة حــدا لزنــا البكــر‪،‬‬\n      ‫كمــا حكمــت عليــه بســجنه ســنة إضافيــة وجلــده مئــة جلــدة أخــرى‬\n      ‫علــى فترتــن كل فتــرة خمســون جلــدة وذلــك إليوائــه للفتــاة يف الدعــوى‬\n      ‫وإبقائهــا معــه وإخفائهــا عــن أهلهــا اعتبــارا مــن تاريــخ دخولــه الســجن ‪،‬‬\n      ‫قــرر املدعــى عليــه القناعــة باحلكــم واملدعــي العــام عدمهــا بــدون تقــدمي‬\n                               ‫الئحــة ‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫‪191‬‬\n\f‫احلمــد هلل وحــده وبعــد فلدينــا نحــن كال مــن ‪...........‬و‪...........‬و‪...........‬‬\n‫القضــاة يف احملكمــة العامــة باخلبــر وبنــاء علــى املعاملــة احملالــة لنــا مــن‬\n‫فضيلــة رئيــس احملكمــة العامــة باخلبــر املســاعد برقــم ‪33553652‬‬\n‫وتاريــخ ‪1433/08/28‬ه ـ املقيــدة باحملكمــة برقــم ‪331624426‬‬\n‫وتاريــخ ‪1433/08/28‬ه ـ ففــي يــوم األحــد املوافق‪1433/11/28‬ه ـ‬\n‫افتتحــت اجللســة الســاعة ‪-10 : 00‬وفيهــا حضــر املدعــي العــام وأقــر‬\n‫قائــا بصفتــي مدعيــا عامــا بدائــرة االدعــاء العــام مبحافظــة اخلبــر‬\n‫ادعــي علــى ‪ ،...........‬البالــغ مــن العمــر (‪ )27‬عامــا ‪ ،‬ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم (‪ ، )...........‬موظــف ‪ ،‬غيــر محصــن ‪،‬‬\n‫قبــض عليــه بتاريــخ ‪1433/6/18‬ه ـ وموقــوف بقســم ســجن اخلبــر وفقــا‬\n‫للمــادة (‪ ) 113‬مــن نظــام اإلجــراءات اجلزائيــة فبتاريــخ ‪1433/6/18‬ه ـ‬\n‫ورد بــاغ لشــرطة اخلبــر مــن املستشــفى اجلامعــي باخلبــر عــن دخــول فتــاة‬\n‫تدعــى‪........... /‬إلــى املستشــفى وتدعــي تعرضهــا لالعتــداء وبضبــط‬\n‫إفــادة املدعيــة ‪ )17(........... /‬عام ـ ًا أفــادت أنهــا تعرفــت علــى شــخص‬\n‫يدعــى ‪...........‬عــن طريــق اجلــوال وحصــل بينهمــا عالقــة عــن طريــق‬\n‫الهاتــف وطلــب منهــا الشــخص أن يراهــا لغــرض الــزواج بهــا وواعدهــا‬\n‫عنــد بنــك ‪...........‬وخرجــت معــه علــى ســيارة صغيــرة بيضــاء اللــون مظللــة‬\n‫بالكامل وأدلت مبواصفات الشــخص وأنه أســمر البشــرة طويل القامة‬\n‫وأخذهــا بســيارته إلــى مــكان بعيــد عبــارة عــن حــوش بــه غرفــة وصالــة‬\n‫تعتقــد أنــه اســتراحة وطلــب منهــا الدخــول لغرفــة النــوم وأعطاهــا اجلــوال‬\n‫لتلعــب بــه وكان يقــول لهــا أنــه يحبهــا ويريــد الــزواج منهــا وقــام بإنــزال‬\n\n\n                                                                                        ‫‪192‬‬\n\f      ‫مالبســها بالقــوة وفعــل بهــا فاحشــة الزنــا فقامــت بالصــراخ وابتعــد عنهــا‬\n      ‫ثــم أعــاد الفعــل مــرة أخــرى وبعدهــا أعادهــا للمنــزل وحاولــت االنتحــار‬\n      ‫بســبب ذلــك وأنــه اتصــل بهــا بعــد ذلــك وأدلــت مبعلومــات عــن املدعــى‬\n      ‫عليــه وأوصافــه ورقــم جوالــه ومواصفــات ســيارته وأفــادت أنهــا حاولــت‬\n      ‫االنتحــار وبحثــت عــن مســدس والدهــا ولــم تعثــر عليــه وأخــذت ثــاث‬\n      ‫طلقــات وخرجــت مــن البيــت محاولــة االنتحــار بــأن تصدمهــا ســيارة ثــم‬\n      ‫توقف شــخص وقام بلف جســدها وحاول أن يفعل بها الفاحشــة فدفعته‬\n      ‫وصرخــت ودفعتــه وقــام بتصويرهــا وأخــذ جوالهــا ثــم قــام بتوصيلهــا‬\n      ‫إلــى املستشــفى وبالتحــري والبحــث عــن املدعــى عليــه مت القبــض عليــه‬\n      ‫بتاريــخ ‪1433/6/18‬ه ـ وقــد اتضــح انطبــاق مــا أدلــت بــه املدعيــة مــن‬\n      ‫أوصــاف عــن املدعــى عليــه وســيارته وباســتجوابه‪ /‬أقــر بوجــود عالقــة‬\n      ‫محرمــة مــع الفتــاة عــن طريــق الهاتــف وأنــه قابلهــا مــرة واحــدة فقــط‬\n      ‫وذهبــت معــه بســيارته للتمشــية وأنهــا رفضــت الرجــوع إلــى منــزل أهلهــا‬\n      ‫وطلبــت منــه الــزواج وعنــد ذلــك قــام بأخذهــا ملقــر ســكنه يف ‪ ...‬إلــى‬\n      ‫غرفتــه اخلاصــة وأقــر بقيامــه بتقبيلهــا وفعــل الفاحشــة بهــا مفاخــذة‬\n      ‫وأنــه بعــد ذلــك قــام بإعادتهــا ملنــزل أهلهــا وأفــاد بأنــه يكنــى بــ‪...........‬‬\n      ‫وســيارته ‪ ......‬مظللــة بالكامــل وأفــاد بأنهــا قامــت بإنــزال مالبســها‬\n      ‫برضاهــا وبإعــادة اســتجواب املدعــى عليــه ‪ /‬أقــر بفعــل فاحشــة الزنــا‬\n      ‫بالفتــاة املدعيــة وفــض بكارتهــا برضاهــا مرتــن بإيــاج وباالنتقــال‬\n      ‫واملعاينــة ملســرح احلــادث تبــن أن املوقــع هــو ســكن بالقــرب مــن ‪........‬‬\n      ‫وهــو عبــارة عــن بركــس صغيــر يوجــد بــه باملدخــل صالــة صغيــرة بهــا‬\n      ‫كنــب ســكري وبالدخــول لغرفــة املدعــى عليــه وهــي غرفــة صغيــرة‬\n      ‫مكونــة مــن ثالثــة أمتــار تقريبـ ًا ولــون اجلــدار أبيــض والســرير مــن جهــة‬\n\n\n‫‪193‬‬\n\f‫البــاب مــن اليمــن كمــا يوجــد بهــا جلســة صغيــرة عبــارة عــن مســند‬\n‫وســدوب األرض ومســتودع للمالبــس صغيــر خشــبي والســرير عليــه‬\n‫فــراش أبيــض ومخــدة خضــراء كمــا عثــر بالغرفــة علــى شيشــة معســل‬\n‫زجــاج صغيــرة ولــم يعثــر علــى أي مناديــل أو آثــار دمــاء بــاألرض والغرفــة‬\n‫مرتبــة غيــر مبعثــرة وانتهــى التحقيــق إلــى توجيــه االتهــام ل‪...........‬ب ـ ‪:‬‬\n‫اســتدراج فتــاة وفعــل فاحشــة الزنــا بالقــوة بعــد التغريــر بهــا وذلــك لألدلــة‬\n                                                                   ‫والقرائــن اآلتيــة ‪:‬‬\n‫‪ -1‬إقــرار املدعــى عليــه مبحضــر االســتجواب املــدون علــى صفحــة رقــم‬\n                                                               ‫(‪ )23‬لفــه رقــم(‪.)13‬‬\n‫‪ -2‬تطابــق أقــوال الفتــاة مــع أقــوال املدعــى عليــه علــى صفحــة رقــم (‪-13‬‬\n                                                                ‫‪ )18‬لفــه رقــم ( ‪)13‬‬\n‫‪ -3‬توافــق وصــف املدعيــة لســيارة املدعــى عليــه وأوصافــه الشــكلية‬\n                                    ‫ومقــر ســكنه مبــا أفــاد بــه املدعــى عليــه‬\n‫‪ -4‬محاولــة الفتــاة لالنتحــار بعــد احلادثــة قرينــة قويــة علــى كونهــا بفعــل‬\n‫الفاحشــة بالقــوة وفــق مــا ورد يف محضــر ســماع األقــوال لفــه رقــم(‪)1‬‬\n‫صفحــة رقــم(‪ )11‬ومــا ورد بدفتــر التحقيــق لفــه رقــم (‪)13‬صفحــة (‪)19‬‬\n‫‪ -5‬مــا ورد يف محضــر االنتقــال واملعاينــة علــى الصفحــة رقــم (‪ )1‬لفــه‬\n                                                                           ‫رقــم (‪. )59‬‬\n‫وبالبحــث عمــا إذا كان لديــه ســوابق تبــن وجــود ســابقة عليــه وهــي‬\n‫حيــازة قــات وحيــث أن مــا أقــدم عليــه املدعــى عليــه ‪ ،‬وهــو بكامــل‬\n‫أهليتــه املعتبــرة شــرع ًا ‪ ،‬فعــل محــرم ومجــرم نظامــا أطلــب إثبــات مــا‬\n‫أســند إليــه واحلكــم عليــه بحــد احلرابــة الــوارد يف اآليــة الكرميــة رقــم‬\n‫(‪ )33‬مــن ســورة املائــدة يف ضــوء قــرار هيئــة كبــار العلمــاء رقــم (‪)85‬‬\n\n\n                                                                                           ‫‪194‬‬\n\f      ‫وتاريــخ ‪1401/11/11‬ه ـ واحلكــم عليــه بحــد الزانــي البكــر تطهيــر ًا‬\n      ‫لــه حلــظ نفســه اســتناد ًا لقولــه تعالــى ( الزانيــة والزانــي فاجلــدوا كل‬\n      ‫واحــد منهمــا مائــة جلــدة ‪ ) ....‬اآليــة (ســورة النــور) مصــادرة اجلــوال نــوع‬\n      ‫‪ ......‬ذي الرقــم التسلســلي (‪ )...........‬وإســقاط الشــريحة التــي حتمــل‬\n      ‫رقــم اجلــوال(‪ ( )...........‬علمـ ًا بــأن احلــق اخلــاص مــازال قائمـ ًا ) ونظــرا ألن‬\n      ‫فضيلــة القاضــي ‪...........‬يتمتــع بإجــازة رســمية لــذا رفعــت اجللســة وبــاهلل‬\n            ‫التوفيــق وصلــى اهلل علــى ســيدنا محمــد وعلــى ألــه وصحبــه وســلم‪.‬‬\n      ‫احلمــد هلل وحــده ففــي يــوم األحــد املوافق‪1434/02/17‬ه ـ افتتحــت‬\n      ‫اجللســة الســاعة ‪11,00‬صباح ـ ًا وفيهــا حضــر املدعــي العــام واملدعــى‬\n      ‫عليــه وبعــرض دعــوى املدعــي العــام علــى املدعــى عليــه قــال الصحيــح‬\n      ‫أننــي آويــت املــرأة املذكــورة يف الدعــوى مــدة يــوم كامــل وقــد فعلــت‬\n      ‫الفاحشــة بهــا بإيــاج وأنــا غيــر محصــن فلــم يســبق لــي الــزواج ونــادم‬\n      ‫علــى مــا صــدر منــي وال صحــة ملــا ذكــره املدعــي العــام باســتدراج الفتــاة‬\n      ‫املذكــورة وهــي كبيــرة وتبلــغ مــن العمــر ســبعة عشــر عامــا وهــي التــي‬\n      ‫اتصلــت بــي وذكــرت أنهــا موجــودة يف كورنيــش اخلبــر وحضــرت‬\n      ‫إليهــا بســيارتي فركبــت بطوعهــا واختيارهــا ولــم أقــم باســتدراجها‬\n      ‫وال خطفهــا وهــي التــي رفضــت العــودة إلــى بيــت أهلهــا هكــذا أجــاب‬\n      ‫وبعــرض ذلــك علــى املدعــي العــام وطلــب البينــة منــه علــى أن املدعــى‬\n      ‫عليــه قــام باســتدراج الفتــاة املذكــورة قــال بينتــي مــا يف أوراق املعاملــة‬\n      ‫وبالرجــوع إلــى أوراق املعاملــة لــم جنــد فيهــا مــا يثبــت أن املدعــى عليــه‬\n      ‫قــام باســتدراج الفتــاة املذكــورة فبنــاء علــى مــا تقــدم وحيــث أقــر‬\n      ‫املدعــى عليــه بأنــه قــام بفعــل الفاحشــة بالفتــاة املذكــورة بإيــاج وهــو‬\n      ‫غيــر محصــن ولقولــه تعالــى (والزانيــة والزانــي فاجلــدوا كل واحــد‬\n\n\n‫‪195‬‬\n\f‫منهمــا مائــة جلدة)ولقولــه صلــى اهلل عليــه وســلم (البكــر بالبكــر جلــد‬\n‫مائــة وتغريــب عــام ) وألن املدعــى عليــه آوى املــرأة املذكــورة وأخفاهــا‬\n‫عــن أهلهــا باإلضافــة إلــى فعــل الفاحشــة بهــا لــذا فلــم يثبــت لدينــا مــا‬\n‫يوجــب إقامــة حــد احلرابــة علــى املدعــى عليــه وحكمنــا علــى املدعــى‬\n‫عليــه بجلــده مائــة جلــدة دفعــة واحــدة وســجنه ســنة حــد ًا لزنــا البكــر‬\n‫كمــا حكمنــا عليــه بســجنه ســنة إضافيــة وجلــده مائــة جلــدة أخــرى‬\n‫علــى فترتــن كل فتــرة خمســون جلــده وذلــك إليوائــه للفتــاة املذكــورة‬\n‫يف الدعــوى وابقائهــا معــه واخفائهــا عــن أهلهــا اعتبــارا مــن تاريــخ‬\n‫دخولــه الســجن يف ‪1433/6/18‬ه ـ وبعــرض احلكــم علــى املدعــى عليــه‬\n‫قــرر قناعتــه باحلكــم وأمــا املدعــى العــام فقــرر عــدم قناعتــه باحلكــم‬\n‫واكتفــى مبــا قدمــه يف أوراق املعاملــة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/2/17‬هــ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ففي يوم االثنني املوافق‪1434/04/22‬هـ افتتحت‬\n‫اجللســة الســاعة ‪ 11.45‬وفيهــا عــادت املعاملــة مــن محكمــة االســتئناف‬\n‫باملنطقــة الشــرقية برفقهــا القــرار رقــم ‪ 34182762‬يف ‪1434/04/08‬هـ‬\n‫واملتضمــن املصادقــة علــى احلكــم وللبيــان جــرى حتريــره وبــاهلل التوفيــق‬\n‫‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                               ‫‪ 1434/04/22‬هـ ‪.‬‬\n\n\n\n\n                                                                                      ‫‪196‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"41499c81-d627-5952-8b7f-c01b2e788165","source_page_start":190,"source_page_end":196,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"7ee53df7af163fe5daccc930f307fc1b78d1ca4eacc07b1512044034a642d942","normalized_text_hash":"5e04bda67c25a8bfc28ecbce8735633f19259e93db46d81e0698bf1777e770c6","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v27-p190-3441136"},{"id":"16eedbc8-35b9-59d4-9bdc-8235c5fd8c23","document_type":"judgment","category":"judicial","subcategory":"general","title":"حرابة -لواط -ارتكاب فاحشة اللواط -اعتداء بالضرب -رد دعوى -تعزير للتهمة -تعزير بالسجن واجللد.","document_number":"33474652","case_number":"33572047","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة االحساء ب","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/4","year":"1434","subject":"حرابة -لواط -ارتكاب فاحشة اللواط -اعتداء بالضرب -رد دعوى -تعزير للتهمة -تعزير بالسجن واجللد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 33474652:‬تاريخه ‪1434/1/4 :‬هـ‬\n                        ‫رقم الدعوى‪33572047 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 34189957‬تاريخه‪1434/4/16 :‬هـ‬\n\n\n      ‫حرابــة ‪ -‬لــواط ‪ -‬ارتــكاب فاحشــة اللــواط ‪ -‬اعتــداء بالضــرب ‪ -‬رد دعوى‬\n                                     ‫‪ -‬تعزيــر للتهمــة ‪ -‬تعزيــر بالســجن واجللد‪.‬‬\n\n\n\n\n           ‫األصل عصمة الدماء واالحتياط فيها إال مبوجب شرعي ظاهر‪.‬‬\n\n\n\n\n      ‫الئحــة الدعــوى العامــة ضــد املدعــى عليهمــا باتهامهــا بفعــل الفاحشــة‬\n      ‫مفاخــذة بأحــد األشــخاص بالقــوة ‪ ،‬وطلــب املدعــي العــام إثبــات مــا‬\n      ‫أســند إليهمــا واحلكــم عليهمــا بحــد احلرابــة ‪ ،‬مت القبــض علــى املدعــى‬\n      ‫عليهمــا إثــر بــاغ تقــدم بــه خــال املجنــي عليــه يتضمــن قيــام املدعــى‬\n      ‫عليهمــا بفعــل الفاحشــة باملجنــي عليــه مفاخــذة بالقــوة وذلــك يف أحــد‬\n      ‫االســتراحات‪ ،‬جــرى عــرض الدعــوى علــى املدعــى عليهمــا فأجابــا‬\n      ‫باإلنــكار ‪ ،‬جــرى االطــاع علــى أوراق املعاملة فوجدت شــهادات مدونه‬\n      ‫يف دفاتــر التحقيــق تتضمــن أحــد هــذه الشــهادات انــه شــوهد املجنــي‬\n      ‫عليــه مــرة يف االســتراحة التــي يرتادهــا املدعــى عليهمــا وكان لوحــده‬\n      ‫كمــا تضمنــت شــهادة أحــد الشــهود أنــه ســمع املدعــى عليهمــا يحــاوالن‬\n      ‫إقنــاع املجنــي عليــه بالتنــازل وإقنــاع الشــاهد بالضغــط علــى املجنــي عليه‬\n      ‫ليتنــازل وأنــه ســمعهما يقــوالن أن مــا فعــاه زلــة شــيطان وأظهــرا النــدم‪،‬‬\n\n‫‪197‬‬\n\f‫مت طلــب الشــاهد الــذي تضمنــت شــهادته أنــه ســمع املدعــى عليهمــا‬\n‫يطلبــان التنــازل مــن املجنــي عليــه‪ ،‬ولــم يحضــر الشــاهد‪ ،‬مت تأمــل‬\n‫بينــات املدعــي العــام فوجــد أنهــا غيــر موصلــة‪ ،‬مــا قــدم املدعــي العــام‬\n‫مــن شــهادة الشــاهد يف محضــر التحقيــق يعتبــر قرينــة توجــب الشــبهة‬\n‫ضــد املدعــى عليهمــا‪ ،‬صــدر احلكــم بــرد دعــوى املدعــي املطالبــة بحــد‬\n‫احلرابــة‪ ،‬تعزيــر املدعــى عليهمــا للتهمــة بالســجن ســنة وجلــد كل واحــد‬\n‫منهمــا مائــة وخمســن جلــده مفرقــة علــى ثــاث دفعــات بواقــع خمســن‬\n      ‫جلــده كل دفعــة‪ ،‬مت تصديــق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫العامــة‬\n    ‫ّ‬    ‫احلمــد هلل وحــده وبعــد فلدينــا نحــن ‪ ......‬القاضــي يف احملكمــة‬\n‫باألحســاء ‪ .....‬مســاعد رئيــس احملكمــة وفضيلــة القائــم بعمــل املكتــب‬\n‫القضائــي الســابع الشــيخ ‪ .....‬وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n‫رئيــس احملكمــة العامــة مبحافظــة االحســاء برقــم ‪ 33572047‬وتاريــخ‬\n‫‪1433/09/12‬ه ـ املقيــدة باحملكمــة برقــم ‪ 331692663‬وتاريــخ‬\n‫‪ 1433/09/12‬ه ـ حضــر املدعــي العــام ‪ ....‬ســعودي اجلنســية مبوجــب‬\n‫رقــم ‪ ............‬وحضــر املدعــى عليهمــا ‪ .....‬ســعودي اجلنســية مبوجــب‬\n‫الســجل املدنــي رقــم ‪ .....‬وحضــر ‪ ......‬ســعودي اجلنســية مبوجــب الســجل‬\n‫املدنــي رقــم ‪.....‬وبســؤال املدعــي العــام عــن دعــواه قــدم الئحــة تتضمــن مــا‬\n‫عامــا بدائــرة االدعــاء العــام مبحافظة األحســاء‬   ‫نصــه ‪ :‬فبصفتــي مدعيـ ًا ً‬\n‫أدعي على كل من‪ 19 ، ........... /1 :‬عام ًا ‪ ،‬ســعودي اجلنســية مبوجب‬\n‫الســجل املدنــي رقــم (‪ )....‬طالــب ‪ ،‬غيــر محصــن ‪ ،‬أوقــف بتاريــخ‬\n‫‪1433/2/20‬ه ـ وأفــرج عنــه بتاريــخ ‪1433/2/24‬ه ـ ثــم أعيــد إيقافــه‬\n                                                                                         ‫‪198‬‬\n\f      ‫بتاريــخ ‪1433/3/20‬ه ـ وجــرى التمديــد لــه مبوجــب أمــر التمديــد رقــم‬\n      ‫(ه ـ ق‪ )15169/3/1‬وتاريــخ ‪1433/3/23‬ه ـ وأحيــل لشــعبة ســجن‬\n      ‫محافظــة االحســاء اســتناد ًا للفقــرة األولــى مــن القــرار الــوزاري رقــم‬\n      ‫(‪ )1900‬وتاريــخ ‪1428/7/9‬ه ـ ‪ 18 ، ..... /2 .‬عامـ ًا ‪ ،‬ســعودي اجلنســية‬\n      ‫مبوجــب الســجل املدنــي رقــم (‪ ).....‬طالــب ‪ ،‬غيــر محصــن ‪ ،‬أوقــف‬\n      ‫بتاريــخ ‪1433/2/20‬ه ـ وأفــرج عنــه بتاريــخ ‪1433/2/24‬ه ـ ثــم أعيــد‬\n      ‫إيقافــه بتاريــخ ‪1433/3/20‬ه ـ وجــرى التمديــد لــه مبوجــب أمــر التمديد‬\n      ‫رقــم (ه ـ ق‪ )15215/3/1‬وتاريــخ ‪1433/3/23‬ه ـ وأحيــل لشــعبة ســجن‬\n      ‫محافظــة االحســاء اســتناد ًا للفقــرة األولــى مــن القــرار الــوزاري رقــم‬\n      ‫(‪ )1900‬وتاريــخ ‪1428/7/9‬ه ـ ‪ .‬مت القبــض علــى املدعــى عليهمــا بتاريــخ‬\n      ‫‪1433/3/20‬ه ـ إثــر بــاغ تقــدم بــه ‪ ...../‬خــال املجنــي عليــه ‪ ..../‬يتضمــن‬\n      ‫قيــام املدعــى عليهمــا بفعــل الفاحشــة باملجنــي عليــه مفاخــذة يف‬\n      ‫االســتراحة التــي يرتادونهــا ‪ .‬وبســماع أقــوال املجنــي عليــه أفــاد بأنــه يف‬\n      ‫صبــاح يــوم األربعــاء و بعــد انتهائــه مــن االختبــارات يف متــام الســاعة‬\n      ‫التاســعة صباح ـ ًا تقريب ـ ًا ذهــب إلــى االســتراحة و نــام يف أحــد الغــرف‬\n      ‫وبعــد ذلــك حضــر لــه املدعــى عليــه األول (‪ )...‬و طلــب منــه فعــل الفاحشــة‬\n      ‫بــه بعــد أن قــام بقفــل البــاب وبعــد رفضــه لذلــك قــام بتثبيتــه وإســقاطه‬\n      ‫علــى األرض ونــزع مالبســه وفعــل بــه الفاحشــة مفاخــذة حتــى انتهــى‬\n      ‫وبعــد ذلــك دخــل عليــه املدعــى عليــه الثانــي (‪ )....‬وطلــب منــه فعــل‬\n      ‫الفاحشــة كمــا فعــل املدعــى عليــه األول و فعــل بــه الفاحشــة مفاخــذة‬\n      ‫حتــى انتهــى‪ .‬وباالنتقــال ومعاينــة مــكان اجلرميــة اتضــح أن القريــة تقــع‬\n      ‫علــى طريــق القــرى الشــرقية علــى امتــداد (‪ )......‬واالســتراحة لهــا بــاب‬\n      ‫واحــد فقــط مــن اخلــارج وهــي عبــارة عــن جلســة أرضيــة بالداخــل رفــع‬\n\n\n‫‪199‬‬\n\f‫منهــا عــدد مــن املناديــل وعــدد (‪ )7‬ســبع صــور مــن خبيــر البصمــات‬\n‫وتعــذر رفــع البصمــات لعــدم وجودهــا‪ .‬وقــد أثبــت برنــت االتصــاالت‬\n‫وجــود مكاملتــن بــن املدعــى عليهمــا يف نفــس يــوم احلادثــة األولــى‬\n‫كانت يف متام الســاعة العاشــرة وتســع وخمســن دقيقة صباح ًا والثانية‬\n‫كانــت يف متــام الســاعة احلاديــة عشــر وخمــس دقائــق صباحـاً‪ .‬وبضبــط‬\n‫أقــوال الشــاهد األول‪ ...../‬أفــاد بأنــه يف يــوم الواقعــة حضــر إليــه املجنــي‬\n‫عليــه و أخبــره بــأن املدعــى عليهمــا قامــا بفعــل الفاحشــة بــه مفاخــذة‬\n‫وذهــب معــه لتقــدمي شــكوى ضــد املدعــى عليهمــا فطلبــوا منــه مركــز‬\n‫الشــرطة أن يحضــر أحــد أقاربــه فأحضــروا خالــه الــذي بــدوره قــام‬\n‫بتقــدمي الشــكوى لــدى الشــرطة وبعــد علــم املدعــى عليهمــا بذلــك‬\n‫حضــرا إليــه وأخبــراه بندمهمــا و أن مــا فعــاه زلــة شــيطان وعنــد ســؤاله‬\n‫لهمــا عــن فعلهمــا بــه الفاحشــة قــررا ذلــك بعــدم إنكارهمــا و بقولهمــا‬\n‫بأنهــا غلطــة و لــن تتكــرر‪ .‬وبضبــط أقــوال الشــاهد الثانــي‪ ..../‬أفــاد بأنه‬\n‫شــاهد املجنــي عليــه يف االســتراحة و كان فيهــا املدعــى عليهمــا‬\n‫‪،‬وكذلــك أفــاد بعلمــه مبــا فعلــه املدعــى عليهمــا ‪ .‬وباســتجواب املدعــى‬\n‫عليــه األول ‪ :‬أقــر مبعرفتــه باملجنــي عليــه وعــدم ذهابــه للمدرســة يف يــوم‬\n‫احلادثــة ‪ .‬وباســتجواب املدعــى عليــه الثانــي ‪ :‬أقــر مبعرفتــه باملجنــي عليــه‬\n‫وعــدم ذهابــه للمدرســة يف يــوم احلادثــة ‪ .‬وبعــرض املدعــى عليهما باملجني‬\n‫عليــه تعــرف عليهمــا و أنهمــا مــن فعــل بــه الفاحشــة و بعرض ذلــك عليهما‬\n‫أنكــرا فعلهمــا الفاحشــة بــه وأصــر كل علــى أقوالــه‪ .‬ومبواجهة املدعى‬\n‫عليهمــا بالشــاهد األول‪ /‬أصــر كل مــن املدعــى عليهمــا والشــاهد علــى‬\n‫أقوالهــم‪ .‬ومبواجهــة املدعــى عليهمــا بالشــاهد الثانــي‪ /‬أصــر كل مــن‬\n‫املدعــى عليهمــا والشــاهد علــى أقوالهــم‪ .‬وقــد أســفر التحقيق عــن توجيه‬\n\n\n                                                                                      ‫‪200‬‬\n\f      ‫االتهــام لــأول وللثانــي بفعــل الفاحشــة مفاخــذة باملجنــي عليــه بالقــوة‪.‬‬\n      ‫وذلــك لألدلــة والقرائــن التاليــة ‪ /1:‬شــهادة‪ .......‬املدونــة علــى الصفحــة‬\n      ‫رقــم (‪ )3‬مــن دفتــر التحقيــق رقــم(‪ )2‬لفــة رقــم(‪ /2 .)39‬شــهادة املدعــو‬\n      ‫‪ .......‬املدونــة علــى الصفحــة رقــم (‪ )5‬مــن دفتــر التحقيــق رقــم(‪ )2‬لفــة‬\n      ‫رقــم(‪ /3 . )39‬محضــر مواجهــة املدعــى عليهمــا بالشــاهد األول املدونــة‬\n      ‫علــى الصفحــة رقــم (‪ )4‬مــن دفتــر التحقيــق رقــم(‪ )4‬لفــة رقــم (‪/4 .)112‬‬\n      ‫محضــر مواجهــة املدعــى عليهمــا بالشــاهد الثانــي املدونــة علــى الصفحــة‬\n      ‫رقــم (‪ )3‬مــن دفتــر التحقيــق رقــم(‪ )4‬لفــة رقــم (‪ /5 .)112‬محضــر‬\n      ‫املواجهــة املدعــى عليهمــا باملجنــي عليــه املــدون علــى الصفحــة رقــم (‪-1‬‬\n      ‫‪ )2‬مــن دفتــر التحقيــق رقــم (‪ )2‬املرفــق علــى اللفــة رقــم (‪ /6 .)39‬برنــت‬\n      ‫االتصــاالت اخلــاص بجــوال املدعــى عليهمــا املرفــق لفــة رقــم (‪/7 .)97‬‬\n      ‫تراجــع املدعــى عليــه الثانــي عــن أقوالــه وإقــراره مبعرفتــه باملجنــي عليــه‬\n      ‫بعــد أن كان منكــر ًا لهــا املــدون علــى الصفحــة رقــم (‪ )2-1‬مــن دفتــر‬\n      ‫التحقيــق رقــم (‪ )4‬لفــة رقــم (‪ /8 .)112‬تراجــع املدعــى عليــه الثانــي عــن‬\n      ‫أقوالــه وإقــراره بعالقتــه باملدعــى عليــه األول بعــد أن كان منكــر ًا لهــا‬\n      ‫املــدون علــى الصفحــة رقــم (‪ )9-8‬مــن دفتــر التحقيــق رقــم (‪ )4‬لفــة‬\n      ‫رقــم(‪ .)112‬وحيــث إن مــا أقــدم عليــه املدعــى عليهمــا وهمــا بكامــل‬\n      ‫أهليتهمــا املعتبــرة شــرع ًا فعــل محــرم ومعاقــب عليــه شــرع ًا وأن مــا فعلــوه‬\n      ‫يعــد ضرب ـ ًا مــن ضــروب احلرابــة والســعي واإلفســاد يف األرض وترويــع‬\n      ‫لآلمنــن وانتهــاك ألعــراض املســلمني علــى ســبيل الغلبــة والقهــر لــذا‬\n      ‫أطلــب إثبــات مــا أســند إليهمــا واحلكــم عليهمــا بحــد احلرابــة الــوارد يف‬\n      ‫اآليــة الكرميــة رقــم (‪ )33‬مــن ســورة املائــدة يف ضــوء قــرار هيئــة كبــار‬\n      ‫العلماء رقـم (‪ )85‬وتاريـخ ‪1401 /11 /11‬هـ وبعرض ذلك على املدعى‬\n\n\n‫‪201‬‬\n\f‫إن مــا جــاء يف دعــوى املدعــي العــام غيــر‬  ‫عليهمــا أجــاب األول بقولــه َّ‬\n‫صحيــح جملــة وتفصيــا وأجــاب الثانــي مبثــل مــا أجــاب بــه األول وبطلــب‬\n‫البينــة مــن املدعــي العــام قــال البينــة مــا يف أوراق املعاملــة وبتصفــح‬\n‫أوراق املعاملــة جــرى االطــاع علــى محضــر االســتجواب اخلــاص باملدعــى‬\n‫عليــه ‪ .......‬املــؤرخ يف ‪1433/2/21‬ه ـ علــى اللفــة رقــم ‪ 14‬صفحــة رقــم ‪1‬‬\n‫املتضمــن إنــكاره تهمــة فعــل الفاحشــة باملجنــي عليــه وأنــه ال توجــد بينــه‬\n‫وبــن املجنــي عليــه احلــدث ‪ ....‬أي عالقــة وأقــر بزمالتــه للمدعــى عليــه‬\n‫الثانــي ‪ ....‬انتهــى املقصــود مــن هــذا احملضــر كمــا جــرى االطــاع علــى‬\n‫تقريــر الفحــوص احليويــة رقــم ‪ 73‬يف ‪143/2/21‬ه ـ لفــة رقــم ‪ 34‬املتعلــق‬\n‫بفحــص العينــات التــي تخــص تعــرض املواطــن ‪ .....‬لفعــل فاحشــة اللــواط‬\n‫والعينــات هــي ثــاث أعــواد أذان ومجموعــة مناديــل وظهــر بالكشــف‬\n‫ســلبية هــذه العينــات للتلوثــات املنويــة وهــذا التقريــر صــادر مــن مديــر‬\n‫إدارة األدلــة اجلنائيــة باملنطقــة الشــرقية كمــا جــرى االطــاع علــى‬\n‫محضــر ضبــط شــهادة املدعــو ‪ ...‬علــى اللفــة ‪ 39‬صفحــة ‪ 5‬واملتضمــن أنــه‬\n‫شــاهد املجنــي عليــه ‪ ...‬يف أحــد املــرات يف االســتراحة التــي يرتادهــا‬\n‫املدعــى عليهمــا وكان لوحــده انتهــى املضمــون مــن هــذا احملضــر كمــا‬\n‫جــرى االطــاع علــى محضــر الشــهادة املــؤرخ يف ‪1433/3/16‬ه ـ مــع‬\n‫الشــاهد ‪ ...‬علــى نفــس اللفــة صفحــة ‪ 3‬واملتضمــن أنــه ســمع املدعــى‬\n‫عليهمــا يحــاوالن إقنــاع املجنــي عليــه بالتنــازل وإقناعــه أي الشــاهد‬\n‫بالضغــط علــى ‪ ...‬لكــي يتنــازل وســمعهما يقــوالن أن مــا فعــاه زلــة‬\n‫شــيطان وقــد أظهــرا النــدم علــى ذلــك انتهــى املقصــود مــن هــذا احملضــر‬\n‫كمــا جــرى االطــاع علــى محضــر االســتجواب اخلــاص باملدعــى عليــه‬\n‫الثانــي ‪ ...‬علــى اللفــة رقــم ‪ 14‬صفحــة ‪ 3‬واملتضمــن إنــكاره تهمــة فعــل‬\n\n\n                                                                                     ‫‪202‬‬\n\f      ‫الفاحشــة وأنــه يعــرف املجنــي عليــه عــن طريــق االســتراحة التــي جتمعهــم‬\n      ‫وعالقتــه بــه ســطحية انتهــى املقصــود مــن احملضــر وبســؤال املدعــي‬\n      ‫العــام هــل يســتطيع إحضــار الشــاهد ‪ .....‬فقــال إننــي قــد طلبــت إحضــار‬\n      ‫الشــاهد املذكــور باخلطــاب املوجــه لشــرطة ‪ .....‬للحضــور هــذا اليــوم‬\n      ‫الســاعة التاســعة صباح ـ ًا وحتــى موعــد هــذه اجللســة لــم يحضــر وهــذا‬\n      ‫اخلطــاب برقــم ‪ 2‬ه ـ ق ‪ 12740/2/‬يف ‪1433/11/17‬ه ـ ومت إرفاقــه يف‬\n      ‫املعاملــة كمــا جــرى االطــاع علــى التقريــر احليــوي رقــم ‪ 238‬يف تاريــخ‬\n      ‫‪1433/6/29‬ه ـ الصــادر مــن مديــر إدارة األدلــة اجلنائيــة باملنطقــة‬\n      ‫الشــرقية وهــي لعينــة مــن زي رياضــي كحلــي اللــون خاصــة مبالبــس‬\n      ‫املجنــي عليــه للكشــف عــن التلوثــات املنويــة والنتيجــة ســلبية هــذه العينة‬\n      ‫ـاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وحيــث‬   ‫انتهــى املقصــود منــه فبنـ ً‬\n      ‫إن املدعــي العــام يطالــب بإقامــة حــد احلرابــة ضــد املدعــى عليهمــا لقــاء‬\n      ‫التهمــة املنســوبة لهمــا وأنكــر املدعــى عليهمــا مــا ُنســب لهمــا وليــس‬\n      ‫هنــاك بينــة ســوى مــا يف أوراق املعاملــة وبتأمــل البينــات املرفقــة يف‬\n      ‫املعاملــة وجدنــا أنهــا غيــر موصلــة ملــا يطالــب بــه املدعــي العــام مــن القتــل‬\n      ‫حرابــة لكونهــا ضعيفــة وال ترتقــي إلــى تطبيــق العقوبــة القصــوى‬\n      ‫ولكــون أن األصــل عصمــة الدمــاء واالحتيــاط فيهــا إال مبوجــب شــرعي‬\n      ‫ظاهــر وهــذا غيــر متوفــر يف هــذه القضيــة ومــع ذلــك فــإن احملكمــة‬\n      ‫تــرى أن مــا أبــرزه املدعــي العــام مــن شــهادة الشــاهد يف محضــر ضبــط‬\n      ‫إفــادة أحــد األشــخاص املدونــة شــهادته مبحضــر االســتجواب يعتبــر‬\n      ‫قرينــة توجــب الشــبهة ضــد املدعــى عليهمــا وال تعفيهمــا مــن العقوبــة‬\n      ‫املناســبة لــذا فقــد حكمنــا مبــا يلــي‪ :‬أوالً‪ :‬رد دعــوى املدعــي العــام يف‬\n      ‫املطالبــة بحــد احلرابــة لعــدم موجبــه‪ .‬ثانيـاً‪ :‬تعزيــر املدعــى عليهمــا للتهمــة‬\n\n\n‫‪203‬‬\n\f‫بســجنهما ســنة مــن تاريــخ إيقافهمــا وجلــد كل واحــد منهمــا مائــة‬\n‫وخمســون جلــدة علــى ثــاث دفعــات بواقــع خمســن جلــدة لــكل دفعــة‬\n‫بــن الدفعــة والتــي تليهــا مــدة ال تقــل عــن عشــرين يومـ ًا وبعــرض احلكــم‬\n‫علــى املدعــى العــام واملدعــى عليهمــا قــرروا جميع ـ ًا عــدم قناعتهــم‬\n‫باحلكــم وطلبــوا محكمــة االســتئناف وقررنــا تزويــد اجلميــع بصــورة‬\n‫مــن احلكــم لتقــدمي االعتــراض عليــه خــال املــدة النظاميــة وهــي ثالثــون‬\n‫يوم ـ ًا مــن تاريــخ اســتالمهم النســخة ويف حــال مضــي املــدة دون تقــدمي‬\n‫االعتــراض فســوف يتــم رفــع املعاملــة حملكمــة االســتئناف بــدون اللوائــح‬\n‫وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                              ‫وسلم ‪ .‬حرر يف ‪ 1433/12/19‬هـ‬\n‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعنــا نحــن ق ــضاة الدائـ ــرة اجلزائـي ــة‬\n‫اخلماسـيـة األولى يف محكمة االستئناف باملنطقة ‪ ............‬على املعاملة‬\n‫الــواردة مــن فضيلــة رئيــس احملكمــة العامــة مبحافظــة األحســاء برقــم‬\n‫‪ 33/1692663‬وتاريــخ ‪1434/3/7‬ه ـ واملقيــدة لــدى احملكمــة برقــم‬\n‫‪/34/622684‬خ‪ 1‬وتاريــخ ‪1434/3/11‬ه ـ املرفــق بهــا القــرار الشــرعي‬\n‫ذو الرقــم ‪ 33474652‬والتاريــخ ‪1433/12/21‬ه ـ الصــادر مــن أصحــاب‬\n‫الفضيلــة القضــاة باحملكمــة الشــيخ‪ ...../‬مســاعد رئيــس احملكمــة‬\n‫ـد‪/‬كل‬\n ‫ٍ‬         ‫والشــيخ‪ ..../‬والشــيخ‪ ..../‬اخلــاص بدعــوى‪ /‬املدعــي العــام ضـ‬\n‫مــن ‪ ... -2 .... -1‬يف قضيــة فاحشــة لــواط وقــد تضمــن القــرار حكــم‬\n‫أصحــاب الفضيلــة مبــا هــو مــدون ومفصــل فيــه‪ .‬وبدراســة القــرار‬\n‫وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة قررنــا املصادقــة‬\n‫علــى احلكــم‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه‬\n                                               ‫وســلم حــرر يف ‪ 1434/4/16‬ه ـ ‪.‬‬\n\n\n                                                                                        ‫‪204‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"41499c81-d627-5952-8b7f-c01b2e788165","source_page_start":197,"source_page_end":204,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"afb7562185576452492e7d1ee8a98d437a6a55be74fba3789a23aae5ebd638cb","normalized_text_hash":"dbd6f4f869b62095707a628ae5ea911ab6e108883f50646eaf3d2e71d1d078da","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v27-p197-33474652"},{"id":"c603b3a4-f864-5cc4-a323-ceb7f2aedba9","document_type":"judgment","category":"judicial","subcategory":"general","title":"حرابة -زنا -فعل الفاحشة بالقوة -اغتصاب -انتهاك حرمة منزل بقصد االعتداء على العرض -توفر شروط إقامة حد الزاني املسلم غير احملصن -إقامة حد الزاني غير احملصن -جلده مائة جلده -تغريب عام مسافة قصر .","document_number":"34266715","case_number":"33581946","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالدمام كل من","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/12","year":"1434","subject":"حرابة -زنا -فعل الفاحشة بالقوة -اغتصاب -انتهاك حرمة منزل بقصد االعتداء على العرض -توفر شروط إقامة حد الزاني املسلم غير احملصن -إقامة حد الزاني غير احملصن -جلده مائة جلده -تغريب عام مسافة قصر .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 34266715 :‬تاريخه ‪1434/7/12 :‬هـ‬\n                          ‫رقم الدعوى‪33581946 :‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 35102257‬تاريخه‪1435/1/2 :‬هـ‬\n\n\n       ‫حرابــة ‪ -‬زنــا ‪ -‬فعــل الفاحشــة بالقــوة ‪ -‬اغتصــاب ‪ -‬انتهــاك حرمــة‬\n       ‫منــزل بقصــد االعتــداء علــى العــرض ‪ -‬توفــر شــروط إقامــة حــد الزانــي‬\n       ‫املســلم غيــر احملصــن ‪ -‬إقامــة حــد الزانــي غيــر احملصــن ‪ -‬جلــده مائــة‬\n                                             ‫جلــده ‪ -‬تغريــب عــام مســافة قصــر ‪.‬‬\n\n\n\n\n          ‫قول اهلل تعالى ‪ ( :‬وال تقربوا الزنا إنه كان فاحشة وساء سبيال )‪.‬‬\n\n\n\n\n       ‫الئحــة الدعــوى العامــة ضــد املدعــى عليــه وافــد مســلم غيــر محصــن‬\n       ‫باتهامــه بانتهــاك حرمــة منــزل بقصــد االعتــداء علــى العــرض واغتصــاب‬\n       ‫اخلادمــة املنزليــة وفعــل فاحشــة الزنــا بهــا بالقــوة وطلــب املدعــي العــام‬\n       ‫إثبــات مــا أســند إليــه واحلكــم عليــه بحــد احلرابــة‪ ،‬مت القبــض علــى‬\n       ‫املدعــى عليــه إثــر بــاغ تقــدم بــه أحــد املواطنــن مدعي ـ ًا أن املدعــى‬\n       ‫عليــه أتــى إلــى منزلــه ولــم يكــن موجــود ًا بــه غيــر اخلادمــة حيــث كانــوا‬\n       ‫مســافرين وأتــى املتهــم حيــث كان يعمــل ســائق ًا خاص ـ ًا لديــه ودخــل‬\n       ‫املنــزل وقــام باغتصــاب اخلادمــة وأن اخلادمــة أبلغتــه بذلــك‪ ،‬جــرى عــرض‬\n       ‫الدعــوى علــى املدعــى عليــه فصــادق علــى دخــول املنــزل وقــرر أنــه فعــل‬\n       ‫فاحشــة الزنــا باخلادمــة برضاهــا وبطلــب منهــا‪ ،‬عــدم وجود بينــة للمدعي‬\n\n‫‪205‬‬\n\f‫العــام علــى فعــل فاحشــة الزنــا بالقــوة‪ ،‬رد دعــوى املدعــي العــام إقامة حد‬\n‫احلرابــة‪ ،‬لتوفــر شــروط إقامــة حــد الزانــي غيــر احملصــن صــدر احلكــم‬\n‫بإقامــة حــد الزانــي غيــر احملصــن علــى املدعــى عليــه بجلــده مائــة جلــده‬\n     ‫وتغريبــه عــام مســافة قصــر‪ ،‬مت تصديــق احلكــم مــن االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده الصــاة والســام علــى مــن ال نبــي بعــده وبعــد لدينــا‬\n‫نحــن قضــاة احملكمــة العامــة بالدمــام كل مــن‪ ..... :‬و‪ .....‬و‪ .....‬فتحــت‬\n‫ـاء علــى‬\n       ‫اجللســة متــام العاشــرة مــن صبــاح يــوم االثنــن ‪1434/4/1‬ه ـ بنـ ً‬\n‫املعاملــة احملالــة إلينــا مــن فضيلــة الرئيــس برقــم‪ 33581946‬املقيــدة‬\n‫لــدى احملكمــة برقــم‪ 331731677‬وتاريــخ ‪1433/9/19‬ه ـ وكان‬\n‫املقــرر لنظرهــا يــوم االثنــن ‪1434/3/2‬ه ـ فوافــق إجــازة اعتياديــة‬\n‫لرئيــس اجللســة مبوجــب خطــاب فضيلــة الرئيــس رقــم ‪34508301‬‬\n‫وتاريخ‪1434/2/30‬ه ـ وبهــا حضــر املدعــي العــام وادعــى علــى احلاضــر‬\n‫معــه بنجالديشــي اجلنســية مبوجــب بطاقــة بديلــة رقــم يف ‪1433/7/15‬هـ‬\n‫ا يف‬ ‫املوقــوف بشــعبة إصالحيــة الدمــام منــذ ‪1433/7/15‬ه ـ قائ ـ ً‬\n‫دعــواه عليــه‪ :‬إنــه بتاريــخ ‪1433/7/13‬ه ـ تقــدم إلــى مركــز شــرطة‬\n‫جنــوب الدمــام املواطــن ‪ .....‬مدعي ـ ًا دخــول املدعــى عليــه إلــى منزلــه‬\n‫ولــم يكــن متواجــد ًا يف املنــزل ســوى اخلادمــة‪ .‬وبضبــط بالغــه أفــاد‬\n‫أنــه قبــل أســبوعني كانــوا مســافرين وأتــى املتهــم كان يشــتغل لديهــم‬\n‫ســائق ًا خاص ـ ًا ســابق ًا وقــد دخــل إلــى املنــزل وقــام باغتصــاب اخلادمــة‬\n‫وأفــاد أن اخلادمــة هــي مــن أخبرتهــم عــن احلادثــة‪ .‬وأفــاد أنــه مت إحضــار‬\n‫املدعــى عليــه وأقــر لديهــم بفعلتــه‪ .‬وبضبــط أقــوال اخلادمــة أفــادت أن‬\n                                                                                     ‫‪206‬‬\n\f      ‫املتهــم كان يشــتغل لــدى كفيلهــا ســابق ًا وطلــب منهــا أنــه تصادقــه‬\n      ‫فرفضــت ذلــك وذات مــرة خرجــت لرمــي القمامــة فرأتــه داخــل املنــزل‬\n      ‫يف كــراج الســيارات فقــام مبســكها وإدخالهــا إلــى غرفــة نومهــا وقــام‬\n      ‫بتعريتهــا مــن املالبــس ثــم قــام باغتصابهــا‪ .‬ومبواجهــة املتهــم باخلادمــة‬\n      ‫أصــرت اخلادمــة أنــه قــام باغتصابهــا بالقــوة وأنكــر املتهــم ذلــك وأفــاد‬\n      ‫أن اخلادمــة هــي مــن فتحــت لــه البــاب وطلبــت منــه فعــل الفاحشــة بهــا‬\n      ‫وأنكــرت اخلادمــة ذلــك‪ .‬وباســتجواب املدعــى عليــه أقــر بدخــول املنــزل‬\n      ‫والزنــا باخلادمــة ‪ .....‬حيــث أفــاد أن العائلــة كانــت يف ســفر حيــث كان‬\n      ‫يف وقتهــا يعمــل لديهــم ســائقاً‪ ،‬وقــد كانــت اخلادمــة تطلــب منــه يف‬\n      ‫بعــض األحيــان الدخــول للمنــزل إلصــاح بعــض احلاجيــات وذات مــرة‬\n      ‫طلبــت منــه اخلادمــة الدخــول للمنــزل وحــن دخــل أقفلــت اخلادمــة البــاب‬\n      ‫وطلبــت منــه فعــل الفاحشــة‪ .‬وأفــاد أنــه قــام بفعــل الفاحشــة بهــا بإيــاج‬\n      ‫وأنــزل منيــه داخــل فرجهــا‪ .‬وقــد انتهــى التحقيــق إلــى اتهامــه بانتهــاك‬\n      ‫حرمــة منــزل بقصــد االعتــداء علــى العــرض واغتصــاب اخلادمــة املنزليــة‬\n      ‫وفعــل فاحشــة الزنــا بهــا بالقــوة‪ .‬وحيــث إن مــا أقــدم عليــه املذكــور‬\n      ‫وهــو بكامــل أهليتــه املعتبــرة شــرع ًا فعــل محــرم ومعاقــب عليــه شــرع ًا‬\n      ‫وضــرب مــن ضــروب اإلفســاد يف األرض وانتهــاك ألعــراض املعصومــن‬\n      ‫علــى ســبيل الغلبــة والقهــر واإلفســاد أطلــب إثبــات ما أســند إليه واحلكم‬\n      ‫عليــه بحــد احلرابــة الــوارد يف اآليــة رقــم (‪ )33‬مــن ســورة املائــدة يف ضــوء‬\n      ‫قــرار هيئــة كبــار العلمــاء رقــم (‪ )85‬وتاريــخ ‪1401/11/11‬هـ‪.‬علمـ ًا بــأن‬\n      ‫احلــق اخلــاص ال زال قائم ـاً‪ .‬هــذه دعــواي‪ .‬وبســؤال املدعــى عليــه أجــاب‬\n      ‫قائ ـاً‪ :‬مــا ذكــره املدعــي العــام يف دعــواه بعضــه صحيــح وبعضــه غيــر‬\n      ‫صحيــح فمــا ذكــره مــن كونــي فعلــت الفاحشــة باخلادمــة املذكــورة‬\n\n\n‫‪207‬‬\n\f‫وأننــي أنزلــت املنــي داخــل فرجهــا وأننــي كنــت أعمــل ســائق ًا لــدى املبلــغ‬\n‫فهــذا صحيــح أمــا مــا ذكــره يف باقــي دعــواه فغيــر صحيــح أبــد ًا فلــم‬\n‫أقــم باغتصــاب اخلادمــة ولــم أقــم بتعريتهــا مــن مالبســها والــذي حصــل‬\n‫أنــه يف يــوم الواقعــة كان كفيلــي وأهلــه خــارج املنــزل فاتصلــت بــي‬\n‫اخلادمــة وطلبــت منــي إحضــار وجبــة مــن مطعــم هارديــز فلمــا أحضرتهــا‬\n‫فتحــت لــي البــاب ثــم أمســكت بيــدي وطلبــت منــي فعــل الفاحشــة بهــا‬\n‫فمارســت معهــا فاحشــة الزنــا مــرة واحــدة وهــي راضيــة فقــد أوجلــت‬\n‫ذكــري يف فرجهــا وأنزلــت املنــي بداخلهــا وال شــبهة لــي بهــذا الــوطء‬\n‫ـادم علــى‬\n         ‫وأنــا مســلم وغيــر محصــن فلــم يســبق لــي الــزواج أبــد ًا وأنــا نـ ٌ‬\n‫مــا فعلــت وتائــب إلــى اهلل تعالــى‪ .‬هــذه إجابتــي‪ .‬وبعــد ســماع الدعــوى‬\n‫واإلجابــة قــال املدعــي العــام الصحيــح مــا ذكرتــه وال صحــة ملــا ذكــره‬\n‫املدعــى عليــه ولــدي البينــة علــى ذلــك وهــي مــا يف أوراق املعاملــة أطلــب‬\n‫االطــاع عليهــا‪ .‬اهــ‪ .‬وقــد قــام بــدور الترجمــة املتعــاون مــع احملكمــة ‪.....‬‬\n‫بنجالديشــي اجلنســية مســلم الديانــة مبوجــب رخصــة إقامــة رقــم ‪ .....‬يف‬\n‫جلســة أخــرى فتحــت مبشــاركة فضيلــة الشــيخ وبهــا حضــر املدعــي‬\n‫العــام واملدعــى عليــه وجــرى تــاوة مــا ســبق ضبطــه مــن قبــل الشــيخ‬\n                                                                    ‫فصادقــا عليــه‪.‬‬\n‫ثــم كــرر املدعــى عليــه جوابــه املرصود يف اجللســة الســابقة ثالث مرات‪.‬‬\n‫اهــ‪ .‬بعدهــا جــرى االطــاع علــى اللفــة رقــم (‪ )1‬وقــد تضمــن التحقيــق‬\n‫مــع املدعــى عليــه مــن قبــل شــرطة جنــوب الدمــام وقــد تضمنــت أجوبتــه‬\n‫طبــق مــا ذكــره يف جوابــه عــن الدعــوى‪ .‬اهــ‪ .‬كمــا جــرى االطــاع علــى‬\n‫اللفــة رقــم (‪ )6-5‬وقــد تضمــن التحقيــق مــع املدعــى عليــه مــن قبــل‬\n‫هيئــة التحقيــق واالدعــاء العــام وقــد تضمنــت أجوبتــه طبــق مــا ذكــره‬\n\n\n                                                                                       ‫‪208‬‬\n\f      ‫أيض ـاً‪ .‬اهــ‪ .‬كمــا جــرى االطــاع علــى التحقيــق مــع املدعيــة مــن قبــل‬\n      ‫هيئــة التحقيــق واالدعــاء العــام املرفــق باملعاملــة لفــة رقــم (‪ )12‬وكذلــك‬\n      ‫محضــر املواجهــة بينهــا وبــن املدعــى عليهــا وقــد ذكــرت املدعيــة أنهــا‬\n      ‫قــام باغتصابهــا بينمــا ذكــر املدعــى عليــه طبــق جوابــه‪ .‬اهــ‪ .‬ثــم جــرى‬\n      ‫االطــاع علــى جميــع طيــات املعاملــة ولــم جنــد فيهــا مــا يؤثــر ‪.‬اهــ‪ .‬وقــد‬\n      ‫قــام بــدور الترجمــة املوظــف ‪ .....‬يف احملكمــة باكســتاني اجلنســية ويف‬\n      ‫جلســة أخــرى حضــر املدعــي العــام واملدعــى عليــه ويف هــذه اجللســة قــال‬\n      ‫ـاء علــى‬‫املدعــي العــام‪ :‬ليــس لــدي زيــادة بينــة ســوى مــا ذكــرت‪ .‬اهــ‪ .‬فبنـ ً‬\n      ‫مــا تقــدم مــن دعــوى املدعــي العــام املتضمنــة قيــام املدعــى عليــه بانتهــاك‬\n      ‫حرمــة إحــدى املنــازل بقصــد االعتــداء علــى العــرض واغتصــاب اخلادمــة‬\n      ‫املنزليــة وفعــل فاحشــة الزنــا بالقــوة وجــواب املدعــى عليــه املتضمــن‬\n      ‫مصادقتــه علــى فعــل فاحشــة الزنــا باخلادمــة برضاهــا وأنــه أولــج ذكــره‬\n      ‫يف فرجهــا وأنــزل املنــي بداخلهــا وذلــك بإحــدى املنــازل وأنكــر فعلــه‬\n      ‫الفاحشــة بالقــوة ومبــا أن املدعــي العــام لــم يقدم بينة على فعله الفاحشــة‬\n      ‫بالقــوة وليــس ثمــة قرائــن تتجــه عليــه ومبــا أنــه قــد توفــرت شــروط إقامــة‬\n      ‫حــد الزانــي علــى املدعــى عليــه فهــو مســلم غيــر محصــن وأقــد أقـ َّـر‬\n      ‫أن الزنــا مــن‬‫أربــع مــرات وصـ َّـرح بحقيقــة الــوطء وال شــبهة لــه بــه ومبــا َّ‬\n      ‫الســبع املوبقــات وقــد قــال تعالــى (( وال تقربــوا الزنــا إنــه كان فاحشــة‬\n      ‫ـك لألعــراض‬      ‫ـؤذن بخطـ ٍـر جســيم وفيــه هتـ ٌ‬\n                                                       ‫ال )) فانتشــاره مـ ٌ‬  ‫ـاء ســبي ً‬\n                                                                                      ‫وسـ َ‬\n      ‫واختــاط يف النســل وكالهمــا جــاء الشــرع بحفظهــا وصيانتهــا ومبا أن‬\n      ‫املدعــى عليــه يعمــل ســائق ًا لــدى املنــزل الــذي مت فيــه فعــل الفاحشــة ممــا‬\n      ‫يعنــي أن دخــول للمنــزل أمـ ٌـر معتــاد وليــس فيــه هتــك حلرمتــه لذلــك كلــه‬\n      ‫فقــد قررنــا اآلتــي‪ :‬أوالً‪ /‬رددنــا دعــوى املدعــي العــام ضــد املدعــى عليــه‬\n\n\n‫‪209‬‬\n\f‫بإقامــة حــد احلرابــة عليــه‪ .‬ثاني ـاً‪ /‬ثبــت لدينــا إدانــة املدعــى عليــه بفعــل‬\n‫فاحشــة الزنــا وقررنــا إقامــة حــد الزانــي غيــر احملصــن عليــه بجلــده مائــة‬\n‫جلــدة دفعــة واحــدة وتغريبــه عامـ ًا مســافة قصــر وبذلــك كلــه حكمنــا‪.‬‬\n‫وبعــرض احلكــم علــى املدعــي العــام قــرر عــدم القناعــة وطلــب رفــع‬\n‫املعاملــة إلــى محكمــة االســتئناف بالئحــة اعتراضيــة فأفهــم باســتالم‬\n‫نســخة احلكــم بتاريــخ ‪1434/7/17‬ه ـ لتقــدمي اعتراضــه عليــه يف مــدة‬\n‫أقصاهــا ثالثــون يوم ـ ًا فــإذا مضــت ولــم يقــدم اعتراضــه فســيتم رفــع‬\n‫كافــة أوراق املعاملــة إلــى محكمــة االســتئناف بــدون الئحــة كمــا قــرر‬\n‫املدعــى عليــه قناعتــه بــه وقــد قــام بــدور الترجمــة املوظــف يف احملكمــة‬\n‫‪ .....‬هويتــه ســابق ًا وكانــت ســاعة النطــق باحلكــم متــام الســاعة التاســعة‬\n‫وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                               ‫وســلم‪ .‬حــرر يف ‪1434/7/10‬هــ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعنــا نحــن ق ــضاة الدائـ ــرة اجلزائـي ــة‬\n‫اخلماسـي ــة األولــى يف محكمــة االســتئناف باملنطقــة ‪ .....‬علــى املعاملــة‬\n‫الــواردة مــن فضيلــة رئيــس احملكمــة العامــة مبدينــة الدمــام برقــم‬\n‫‪ 33/1731677‬وتاريــخ ‪1434/12/24‬ه ـ واملقيــدة لــدى احملكمــة‬\n‫برقــم ‪/34/ 2908389‬خ‪ 1‬وتاريــخ ‪1434/12/ 29‬ه ـ املرفــق بهــا القــرار‬\n‫الشــرعي ذو الرقــم ‪ 34266715‬والتاريــخ ‪1434/ 7/ 12‬ه ـ الصــادر مــن‬\n‫أصحــاب الفضيلــة القضــاة باحملكمــة الشــيخ‪ ...‬والشــيخ‪ ...‬والشــيخ‪...‬‬\n‫اخلــاص بدعــوى ‪ ...‬املدعــي العــام ضــد‪ ، ...‬اجلنســية يف قضيــة فاحشــة زنــا‬\n‫وقــد تضمــن القــرار حكــم أصحــاب الفضيلــة مبــا هــو مــدون ومفصــل‬\n‫فيــه‪ .‬وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة قررنــا املصادقــة‬\n‫علــى احلكــم‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه‬\n                                                ‫وســلم حــرر يف ‪ 1435/1/2‬ه ـ ‪.‬‬\n                                                                                         ‫‪210‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"41499c81-d627-5952-8b7f-c01b2e788165","source_page_start":205,"source_page_end":210,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"cff259af47492026a233d616a2c9f8e4fd6170624aa6a3472678279d824f486b","normalized_text_hash":"fa864c2c7477bc93fd3de2a0d70ba53cbc1adcb64deb43477d2728b0917f375e","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v27-p205-34266715"},{"id":"146d3f2d-5c92-5051-a996-1f9d7fa46652","document_type":"judgment","category":"judicial","subcategory":"general","title":"حرابة -خطف -اغتصاب -إقرار بارتكاب الفاحشة برضى املدعى عليها -رد دعوى احلرابة لعدم ثبوت موجبها -تطبيق حد الزاني احملصن -رجوع عن إقرار -درء حد الزاني احملصن -التعزير بالسجن واجللد واإلبعاد عن الباد .","document_number":"3423681","case_number":"33612676","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة وباالشتراك مع القاضي","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/26","year":"1434","subject":"حرابة -خطف -اغتصاب -إقرار بارتكاب الفاحشة برضى املدعى عليها -رد دعوى احلرابة لعدم ثبوت موجبها -تطبيق حد الزاني احملصن -رجوع عن إقرار -درء حد الزاني احملصن -التعزير بالسجن واجللد واإلبعاد عن الباد .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫رقم الصك‪ 3423681 :‬تاريخه‪1434/1/26:‬هـ‬\n                        ‫رقم الدعوى‪33612676 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 34247530‬تاريخه‪1434/6/20 :‬هـ‬\n\n\n      ‫حرابــة ‪ -‬خطــف ‪ -‬اغتصــاب ‪ -‬إقــرار بارتــكاب الفاحشــة برضــى املدعــى‬\n      ‫عليهــا ‪ -‬رد دعــوى احلرابــة لعــدم ثبــوت موجبهــا ‪ -‬تطبيــق حــد الزانــي‬\n      ‫احملصــن ‪ -‬رجــوع عــن إقــرار ‪ -‬درء حــد الزانــي احملصــن ‪ -‬التعزيــر‬\n                                      ‫بالســجن واجللــد واإلبعــاد عــن البــاد ‪.‬‬\n\n\n\n\n      ‫‪ -1‬قــول النبــي صلــى اهلل عليــه وســلم ‪« :‬واغــد يــا أنيــس إلــى امــرأة هــذا‬\n                    ‫‪ ،‬فــإن اعترفــت فارجمهــا» فاعترفــت فرجمهــا رواه البخــاري‪.‬‬\n      ‫‪ -2‬حديــث ابــن عبــاس رضــي اهلل عنهمــا قــال ‪ :‬ملــا أتــى ماعــز بــن مالــك‬\n      ‫النبــي صلــى اهلل عليــه وســلم قــال لــه (لعلــك قبلــت‪ ،‬أو غمــزت أو‬\n      ‫نظــرت) قــال ‪ :‬ال يــا رســول اهلل ‪ ،‬قــال‪« :‬أنكتهــا» ال يكنــي‪ ،‬قــال ‪ :‬نعــم‪.‬‬\n                                  ‫فعنــد ذلــك أمــر برجمــه رواه البخــاري وغيــره‪.‬‬\n      ‫‪ -3‬جابــر بــن ســمرة قــال‪« :‬رأيــت ماعــز بــن مالــك حــن جــيء بــه إلــى‬\n      ‫النبــي صلــى اهلل عليــه وســلم رجــل قصيــر أعضل ليس عليه رداء فشــهد‬\n      ‫علــى نفســه أربــع مــرات أنــه زنــى فقــال رســول اهلل صلــى اهلل عليــه وســلم‬\n      ‫(فلعلــك) قــال ‪ :‬ال واهلل ‪ ،‬إنــه قــد زنــى اآلخــر قــال ‪ :‬فرجمــه رواه مســلم‪.‬‬\n      ‫‪ -4‬أبــي هريــرة رضــي اهلل عنــه يف قصــة ماعــز وفيــه ‪ :‬فقــال يــا رســول اهلل‬\n      ‫إنــه قــد زنــى فأعــرض عنــه ثــم جــاء مــن شــقه اآلخــر فقــال يــا رســول اهلل‬\n      ‫إنــه قــد زنــى فأمــر بــه يف الرابعــة فأخــرج إلــى احلــرة فرجــم باحلجــارة‬\n      ‫فلمــا وجــد مــس احلجــارة فــر يشــتد حتــى مــر برجــل معــه حلــي جمــل‬\n‫‪211‬‬\n\f‫فضربــه بــه وضربــه النــاس حتــى مــات فذكــروا ذلــك لرســول اهلل‬\n‫صلــى اهلل عليــه وســلم أنــه فــر حــن وجــد مــس احلجــارة ومــس املــوت‬\n               ‫فقــال رســول اهلل صلــى اهلل عليــه وســلم هــا تركتمــوه ‪.‬‬\n\n\n\n\n‫جــرى توجيــه االتهــام مــن املدعــي العــام للمدعــى عليــه بخطــف فتــاة‬\n‫قاصــرة وفعــل فاحشــة الزنــا بهــا حتــت تهديــد الســاح ممــا أدى حلملهــا‬\n‫منــه ســفاحا وطلــب إثبــات مــا أســند إليــه واحلكــم عليــه بحــد احلرابــة‬\n‫حيــث قبــض عليــه علــى إثــر بــاغ مــن الفتــاة بأنهــا كانــت تســير يف‬\n‫الطريــق حتــى اقتربــت مــن البقالــة التــي يعمــل بهــا املدعــى عليــه فأقفــل‬\n‫بقالتــه واجتــه نحوهــا وبيــده ســكينا وأمســك بهــا وأدخلهــا العمــارة التي‬\n‫بهــا منزلــه فأنــزل مالبســها واغتصبهــا وقــام بتصويرهــا وهــي عاريــة‬\n‫وكــرر معهــا الفعــل أكثــر مــن مــرة ثــم خرجــت ولــم تخبــر أحــدا مــن‬\n‫أهلهــا لكونهــا خائفــة وبعــد ظهــور عالمــات احلمــل أخبــرت والدتهــا‪،‬‬\n‫جــرى فحــص عينــة الــدم القياســية للمدعــى عليــه ومقارنتهــا بعينــة الــدم‬\n‫للطفــل الــذي أجنبتــه الفتــاة بتقنية احلمض النووي (‪ )DNA‬فظهر بأنها‬\n‫متطابقــة ممــا يثبــت بأنــه والــد الطفــل ‪ ،‬أنكــر املدعــى عليــه الدعــوى‬\n‫والتهمــة جملــة وتفصيــا ‪ ،‬مبواجهتــه مبــا تضمنــه حتليــل احلمض النووي‬\n‫أقــر بأنــه فعــل بهــا الفاحشــة برضاهــا مــرة واحــدة بعدمــا طرقــت عليــه‬\n‫البــاب وطلبــت منــه ذلــك مقابــل مئــة ريــال فوافــق ‪ ،‬أقــر املدعــى عليــه‬\n‫بفعــل الفاحشــة بالفتــاة برضاهــا أربــع مــرات ‪ ،‬فقــد ثبــت قيــام املدعــى‬\n‫عليــه بفعــل الفاحشــة بالفتــاة وحكمــت بــرد دعــوى املدعــي العــام إقامــة‬\n‫حــد احلرابــة لعــدم ثبــوت موجبــه‪ ،‬وحكمــت علــى املدعــى عليــه بالرجــم‬\n\n                                                                                     ‫‪212‬‬\n\f      ‫حتــى املــوت حــد الزانــي احملصــن‪ ،‬وبعــرض احلكــم عليهمــا قــررا‬\n      ‫االعتــراض بالئحــة فأفهمــا بتعليمــات االســتئناف‪ ،‬ثــم فتحــت اجللســة‬\n      ‫بعدمــا قــدم املدعــى عليــه الئحتــه االعتراضيــة وجــرى إعــادة فتــح بــاب‬\n      ‫املرافعــة وقــرر بأنــه لــم يفعــل بالفتــاة فاحشــة الزنــا‪ ،‬وألن احلــدود تــدرأ‬\n      ‫بالشــبهات‪ ،‬لذلــك كلــه فقــد رجعــت احملكمــة عمــا حكمــت بــه مــن‬\n      ‫رجــم املدعــى عليــه حتــى املــوت حــد الزانــي احملصــن‪ ،‬مــع بقــاء حكمهــا‬\n      ‫الســابق فيمــا يخــص رد طلــب املدعــي العــام إقامــة حــد احلرابــة لعــدم‬\n      ‫ثبــوت موجبــه‪ ،‬وبنــاء علــى مــا ذكــر ســابق ًا مــن تســبيب للحكــم األول‬\n      ‫وبنــاء علــى مــا ذكــر مــن تســبيب للرجــوع ‪ ،‬فقــد حكمــت احملكمــة‬\n      ‫علــى املدعــى عليــه بالســجن خمــس ســنوات اعتبــارا مــن تاريــخ إيقافــه‬\n      ‫وجلــده خمســمائة جلــدة مفرقــة علــى دفعــات كل دفعــة خمســون جلدة‪،‬‬\n      ‫بــن كل دفعــة وأخــرى مــا ال يقــل عــن عشــرة أيــام ‪،‬وإبعــاده عــن البــاد‬\n      ‫بعــد تنفيــذ محكوميتــه ‪ ،‬وال يســمح لــه بالعــودة لهــا عــدا مــا تســمح بــه‬\n      ‫تعليمــات احلــج والعمــرة ‪ ،‬قــرر املدعــى عليــه القناعــة باحلكــم بينمــا قــرر‬\n        ‫املدعــي العــام االعتــراض ‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ......‬القاضــي يف احملكمــة العامــة‬\n      ‫مبحافظــة جــدة وباالشــتراك مــع القاضــي ‪ ........‬والقاضــي‪ ......‬وبنــاء‬\n      ‫علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة مبحافظــة‬\n      ‫جدة‪/‬املســاعد برقــم ‪ 33612676‬وتاريــخ ‪ 1433/10/21‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 331788526‬وتاريــخ ‪ 1433/10/11‬ه ـ ففــي يــوم‬\n      ‫االثنــن املوافــق‪ 1434/01/12‬ه ـ افتتحــت اجللســة الســاعة ‪: 30‬‬\n‫‪213‬‬\n\f‫‪11‬وفيهــا حضــر املدعــي العــام ‪ ........‬وادعــى علــى احلاضــر معــه ‪.......‬‬\n‫(‪ )44‬عام ـ ًا ‪ ،‬هنــدي اجلنســية مبوجــب رخصــة اإلقامــة رقــم (‪)...........‬‬\n‫بتاريــخ ‪1433/2/28‬ه ـ مت القبــض علــى املذكــور مــن قبــل التحريــات‬\n‫والبحــث اجلنائــي مبحافظــة جــدة بعــد ورود بــاغ مــن املجنــي عليهــا‬\n‫الفتــاة‪(........... /‬ســودانية اجلنســية) البالغــة مــن العمــر (‪ )14‬عام ـ ًا تفيــد‬\n‫فيــه بأنــه يف شــهر رجــب مــن عــام ‪1432‬ه ـ ويف حوالــي الســاعة الثالثــة‬\n‫ظهــر ًا كانــت ذاهبــة إلــى اخلياطــة املجــاورة ملنزلهــم وعندمــا اقتربــت مــن‬\n‫العمــارة التــي فيهــا البقالــة التــي يعمــل بهــا املدعــى عليــه أقفــل املدعــى‬\n‫عليــه البقالــة واجتــه نحوهــا و يف يــده ســكني وامســك بهــا مــن عباءتهــا‬\n‫وأدخلهــا إلــى العمــارة التــي بهــا منزلــه وهنــاك أنــزل مالبســها واغتصبهــا‬\n‫وذلــك بإدخــال ذكــره يف فرجهــا ثــم قــام بتصويرهــا بهاتفــه احملمــول‬\n‫وهــي عاريــة ثــم كــرر ممارســة فعــل الفاحشــة بهــا أكثــر مــن مــرة‬\n‫ثــم خرجــت مــن منزلــه وذهبــت إلــى منزلهــا دون أن تخبــر أحــد ًا مــن‬\n‫أهلهــا ألنهــا كانــت خائفــة وأفــادت أنــه هددهــا بالســكني ومــع ظهــور‬\n‫التغيــرات يف جســدها (أعــراض احلمــل) أخبــرت والدتهــا مبــا حــدث ‪.‬‬\n‫وصــدر التقريــر الطبــي بحــق املجنــي عليهــا مــن مستشــفى الــوالدة‬\n‫واألطفــال بــدون رقــم وبــدون تاريــخ املتضمــن وجــود حمــل داخــل الرحــم‬\n‫يف األســبوع التاســع والعشــرين وجــد غشــاء البــكارة متهتــك تهتــك‬\n‫قــدمي يف الســاعة ‪. 12-9-3‬كمــا صــدر تقريــر األدلــة اجلنائيــة الفنــي‬\n‫رقــم (‪ )...........‬بشــأن فحــص عينــة قياســية مــن املجنــي عليهــا وطفلتهــا‬\n‫ومقارنتهــا باملدعــى عليــه املذكــور إلثبــات صلــة القرابــة وذلــك عــن‬\n‫طريــق اختبــارات احلمــض النــووي الوراثــي (‪ )DNA‬املتضمــن اشــتراك‬\n‫العينــة القياســية التــي أخــذت مــن الطفــل بالعينــة القياســية التــي أخــذت‬\n\n\n                                                                                         ‫‪214‬‬\n\f      ‫مــن املدعــى عليــه وتطابــق تلــك العينــات ممــا يثبــت أن املدعــى عليــه هــو‬\n      ‫والــد الطفــل ‪ .‬وباســتجواب املدعــى عليــه أفــاد بأنــه قبــل تســعة أشــهر‬\n      ‫تقريب ـ ًا وبعدمــا اقفــل البقالــة التــي يعمــل بهــا بحــي … حوالــي الســاعة‬\n      ‫الثالثــة ظهــر ًا ذهــب إلــى منزلــه بنفــس العمــارة التــي بهــا البقالــة وعندمــا‬\n      ‫كان مبنزلــه طرقــت عليــه املجنــي عليهــا البــاب وفتــح لهــا البــاب ودخلت‬\n      ‫منزلــه مباشــرة وبعدهــا أخرجهــا بالقــوة واقفــل البــاب الن زوجتــه معــه‬\n      ‫بداخــل املنــزل وتدعــى‪( .........‬اندونيســية اجلنســية) والتــي تــزوج بهــا‬\n      ‫قبــل ســنه عنــد شــيخ اندونيســي مبهــر وقــدره ألــف ريــال وهــي مقيمــة‬\n      ‫بطريقــة غيــر نظاميــة بينمــا اعتــرف يف أقوالــه األوليــة بفعــل فاحشــة‬\n      ‫الزنــا باملجنــي عليهــا مبوافقتهــا مببلــغ مائــة ريــال ‪ .‬وقــد انتهــى التحقيــق‬\n      ‫إلــى توجيــه االتهــام إلــى املدعــى عليــه بخطــف فتــاة قاصــر وفعــل فاحشــة‬\n      ‫الزنــا بهــا حتــت تهديــد الســاح ممــا أدى إلــى حملهــا منــه ســفاحا طبقــا‬\n      ‫لقــرار االتهــام رقــم (‪ )........‬واملؤيــد بقــرار جلنــة إدارة الهيئــة رقــم (‪).........‬‬\n                                  ‫لعــام ‪ 1433‬ه ـ ‪ ،‬وذلــك لألدلــة والقرائــن التاليــة‪:‬‬\n      ‫‪ -1‬مــا جــاء بأقــوال املدعــى عليــه بحضــور الفتــاة ملنزلــه املدونــة علــى‬\n                   ‫الصفحــة رقــم (‪ )8-6‬مــن دفتــر التحقيــق املرفــق لفــه (‪)46‬‬\n      ‫‪ -2‬مــا جــاء بإقــرار املدعــى عليــه عنــد ســماع أقوالــه لــدى جهــة الضبــط‬\n      ‫املــدون علــى الصفحــة رقــم (‪ )7-6‬مــن محضــر االســتدالل املرفــق لفــه‬\n                                           ‫(‪)7‬مــن فعلــه لفاحشــة الزنــا باملجنــي عليهــا‬\n      ‫‪ -3‬مــا جــاء بالتقريــر الطبــي الصــادر بحــق املجنــي عليهــا املرفــق لفــه‬\n                                                                                           ‫(‪.)18‬‬\n      ‫‪ -4‬مــا جــاء بالتقريــر الفنــي رقــم (‪ )...........‬ورقــم (‪ )...........‬املتضمــن‬\n      ‫مطابقــة عينــة دم املدعــى عليــه بعينــة دم الطفــل املولــود املرفــق لفــه (‪-66‬‬\n\n\n‫‪215‬‬\n\f‫‪ )68‬ولفــه (‪ )74-72‬وباالطــاع علــى ســوابقه لــم يعثــر لــه علــى ســوابق‬\n‫مســجلة ‪ .‬وحيــث إن مــا أقــدم عليــه املدعــى عليــه وهــو بكامــل أهليتــه‬\n‫املعتبــرة شــرعا فعــل ومحــرم ومعاقــب عليــه شــرعا ويعــد انتهــاك ًا‬\n‫حلرمــات املســلمني علــى ســبيل املكابــرة واملجاهــرة لــذا أطلــب إثبــات مــا‬\n‫اســند إليــه واحلكــم عليــه بحــد احلرابــة وفقـ ًا لآليــة الكرميــة رقــم (‪)33‬‬\n‫مــن ســورة املائــدة يف ضــوء قــرار هيئــة كبــار العلمــاء رقــم (‪ )85‬وتاريــخ‬\n‫‪1401/11/11‬ه ـ ‪( .‬علمـ ًا بــأن احلــق اخلــاص مــازال قائمـاً) هــذه دعــواي‬\n‫‪ .‬وبعــرض دعــوى املدعــي العــام علــى املدعــى عليــه بواســطة املترجــم‬\n‫‪ ..........‬بنجالديشــي اجلنســية مبوجــب اإلقامــة رقــم ‪ ......‬واملترجــم‬\n‫‪ ...........‬باكســتاني اجلنســية مبوجــب اإلقامــة رقــم ‪ ....‬أجــاب قائــا‪:‬‬\n‫أن مــا ذكــره املدعــي العــام غيــر صحيــح جملــة وتفصيــا ومــا أقريــت‬\n‫بــه حتقيقــا كان حتــت اإلكــراه واإلجبــار ‪ ،‬ومــا ورد يف اســتجوابي‬\n‫مــن إقفــال البقالــة التــي أعمــل بهــا بحــي …… حوالــي الســاعة الثالثــة‬\n‫ظهــر ًا وأننــي ذهبــت إلــى منزلــي بنفــس العمــارة التــي بهــا البقالــة وأن لــي‬\n‫زوجــة معــي بداخــل املنــزل وتدعــى‪( .........../‬اندونيســية اجلنســية) والتــي‬\n‫تزوجــت بهــا قبــل ســنة عنــد شــيخ اندونيســي مبهــر وقــدره ألــف ريــال‬\n‫وهــي مقيمــة بطريقــة غيــر نظاميــة فصحيــح ‪ ،‬وأمــا مــا ورد مــن أننــي‬\n‫عندمــا كنــت مبنزلــي طرقــت علــي املجنــي عليهــا البــاب وفتحــت لهــا‬\n‫البــاب ودخلــت منزلــي مباشــرة وبعدهــا أخرجتهــا بالقــوة وأقفلــت البــاب‬\n‫فغيــر صحيــح ‪ .‬ومبواجهتــه بتقريــر األدلــة اجلنائيــة الفنــي رقــم (‪)........‬‬\n‫بشــأن فحــص عينــة قياســية مــن املجنــي عليهــا وطفلتهــا ومقارنتهــا‬\n‫باملدعــى عليــه املذكــور إلثبــات صلــة القرابــة وذلــك عــن طريــق‬\n‫اختبــارات احلمــض النــووي الوراثــي (‪ )DNA‬املتضمــن اشــتراك العينــة‬\n\n\n                                                                                         ‫‪216‬‬\n\f      ‫القياســية التــي أخــذت مــن الطفــل بالعينــة القياســية التــي أخــذت مــن‬\n      ‫املدعــى عليــه وتطابــق تلــك العينــات ممــا يثبــت أن املدعــى عليــه هــو والــد‬\n      ‫الطفــل ‪ ،‬قــال ‪ :‬يف احلقيقــة أننــي فعلــت مــع املجنــي عليهــا الفاحشــة مــرة‬\n      ‫واحــدة يف ذلــك الوقــت ‪ ،‬وقــد كانــت هــي مــن حضــرت إلــي يف الشــقة‬\n      ‫طالبــة منــي مبلغــا وقــدره مائــة ريــال ففعلــت معهــا الفاحشــة مقابــل هــذا‬\n      ‫املبلــغ وكان ذلــك بطــوع املجنــي عليهــا واختيارهــا ‪ .‬وبطلــب زيــادة بينــة‬\n      ‫مــن املدعــي العــام قــال أطلــب املهلــة إلحضارهــا يف اجللســة القادمــة ‪.‬‬\n      ‫ثــم رفعــت اجللســة لذلــك ‪ ،‬ويف يــوم االثنــن املوافــق ‪ 1434/01/19‬ه ـ‬\n      ‫افتتحــت اجللســة الســاعة ‪10 : 51‬وفيهــا حضــر الطرفــان ‪ ،‬وبســؤال‬\n      ‫املدعــي العــام عمــا طلــب اإلمهــال مــن أجلــه قــال ‪ :‬أطلــب اإلمهــال مــرة‬\n      ‫أخــرى إلحضــار زيــادة بينــة ‪ .‬فأفهــم بأنهــا املــرة الثانيــة التــي يطلــب‬\n      ‫فيهــا اإلفهــام ‪ ،‬ففهــم ذلــك ‪ .‬ثــم رفعــت اجللســة لذلــك ‪ ،‬ويف يــوم االثنــن‬\n      ‫املوافق ‪1434/01/26‬هـ افتتحت اجللســة الســاعة ‪ 11 : 00‬وفيها حضر‬\n      ‫الطرفــان ‪ ،‬وبســؤال املدعــي العــام عمــا طلــب اإلمهــال مــن أجلــه قــال ‪:‬‬\n      ‫أكتفــي مبــا جــاء يف أوراق املعاملــة ‪ .‬وبســؤال املدعــى عليــه عــن طريــق‬\n      ‫املترجــم ‪...........‬واملترجــم ‪......................‬هــل لديــك أوالد فقــال ‪ :‬نعــم ‪،‬‬\n      ‫لــدي ثالثــة أوالد يف الهنــد ‪ ،‬ولــم أرزق بــأوالد مــن زوجتــي االندونيســية‬\n      ‫التــي كانــت معــي يف الشــقة ‪ ،‬وكنــت أجامعهــا ‪ .‬وبتكــرار الســؤال‬\n      ‫للمدعــى عليــه عــن طريــق املترجمــن هــل جامــع املجنــي عليهــا ذلــك‬\n      ‫اليــوم قــال ‪ :‬نعــم فعلــت الفاحشــة مــع املجنــي عليهــا مــرة واحــدة وكان‬\n      ‫بطوعهــا واختيارهــا وكان بإيــاج نصــف العضــو الذكــري ‪ .‬وبســؤاله‬\n      ‫مــرة ثانيــة أجــاب بنفــس اإلجابــة ‪ ،‬وبســؤاله مــرة ثالثــة أجــاب بنفــس‬\n      ‫اإلجابــة ‪ ،‬وبســؤاله للمــرة الرابعــة أجــاب بنفــس اإلجابــة ‪ .‬فبنــاء علــى‬\n\n\n‫‪217‬‬\n\f‫مــا تقــدم مــن الدعــوى واإلجابــة ‪ ،‬وبنــاء علــى مــا جــاء بأقــوال املدعــى‬\n‫عليــه بحضــور الفتــاة ملنزلــه املدونــة علــى الصفحــة رقــم (‪ )8-6‬مــن دفتــر‬\n‫التحقيــق املرفــق لفــة (‪ ، )46‬وبنــاء علــى مــا جــاء بإقــرار املدعــى عليــه‬\n‫عنــد ســماع أقوالــه لــدى جهــة الضبــط املــدون علــى الصفحــة رقــم (‪)7-6‬‬\n‫مــن محضــر االســتدالل املرفــق لفــة (‪ )7‬مــن فعلــه لفاحشــة الزنــا باملجنــي‬\n‫عليهــا ‪،‬وبنــاء علــى مــا جــاء بالتقريــر الطبــي الصــادر بحــق املجنــي عليهــا‬\n‫املرفــق لفــه (‪،)18‬وبنــاء علــى مــا جــاء بالتقريــر الفنــي رقــم (‪/022345‬‬\n‫فحــوص وراثية‪1433/‬هــ) ورقــم (‪/022385‬فحــوص وراثية‪1433/‬هــ)‬\n‫املتضمــن مطابقــة عينــة دم املدعــى عليــه بعينــة دم الطفــل املولــود املرفــق‬\n‫لفــة (‪ )68-66‬ولفــة (‪ ، )74-72‬وبنــاء علــى إقــرار املدعــى عليــه يف‬\n‫املجلــس القضائــي مــن أنــه فعــل مــع املجنــي عليهــا الفاحشــة مــرة واحــدة‬\n‫يف ذلــك الوقــت ‪،‬وأنهــا هــي مــن حضــرت إليــه يف الشــقة طالبــة منــه‬\n‫مبلغــا وقــدره مائــة ريــال ففعــل معهــا الفاحشــة مقابــل هــذا املبلــغ وأن‬\n‫ذلــك كان بطــوع املجنــي عليهــا واختيارهــا ‪ ،‬وبنــاء علــى إقــرار املدعــى‬\n‫عليــه بذلــك أربــع مــرات يف مجلــس القضــاء ‪ ،‬وبنــاء علــى إقــرار املدعــى‬\n‫عليــه مــن أن لــه زوجــة معــه بداخــل املنــزل وتدعى‪(.........../‬اندونيســية‬\n‫اجلنســية) والتــي تــزوج بهــا قبــل ســنة عنــد شــيخ اندونيســي مبهــر قــدره‬\n‫ألــف ريــال وهــي مقيمــة بطريقــة غيــر نظاميــة وأنــه يجامعهــا ‪ ،‬وبنــاء‬\n‫علــى إقــرار املدعــى عليــه بــأن لــه ثالثــة مــن األوالد ‪ ،‬وبنــاء علــى إنــكار‬\n‫املدعــى عليــه فعــل الفاحشــة باإلكــراه ‪ ،‬ولــم يقــم املدعــي العــام البينــة‬\n‫علــى ذلــك ‪ ،‬وحلديــث (واغــد يــا أنيــس إلــى امــرأة هــذا ‪ ،‬فــإن اعترفــت‬\n‫فارجمهــا) فاعترفــت فرجمهــا رواه البخــاري ‪ ،‬وللحديــث الــذي رواه ابن‬\n‫عبــاس رضــي اهلل عنهمــا قــال ‪ :‬ملــا أتــى ماعــز بــن مالــك النبــي صلــى اهلل‬\n\n\n                                                                                        ‫‪218‬‬\n\f      ‫عليــه وســلم قــال لــه (لعلــك قبلــت ‪ ،‬أو غمــزت أو نظــرت) قــال ‪ :‬ال يــا‬\n      ‫رســول اهلل ‪ ،‬قــال ‪( :‬أنكتهــا) ال يكنــي‪ ،‬قــال ‪ :‬نعــم ‪ .‬فعنــد ذلــك أمــر‬\n      ‫برجمــه ‪ .‬رواه البخــاري وغيــره ‪،‬وللحديــث الــذي رواه جابــر بــن ســمرة‬\n      ‫قــال ‪ :‬رأيــت ماعــز بــن مالــك حــن جــيء بــه إلــى النبــي صلــى اهلل عليــه‬\n      ‫وســلم رجــل قصيــر أعضــل ليــس عليــه رداء فشــهد علــى نفســه أربــع‬\n      ‫مــرات أنــه زنــى فقــال رســول اهلل صلــى اهلل عليــه وســلم (فلعلــك) قــال ‪:‬‬\n      ‫ال واهلل ‪ ،‬إنــه قــد زنــى اآلخــر قــال ‪ :‬فرجمــه ‪ .‬رواه مســلم ‪،‬لذلــك كلــه‬\n      ‫‪ ،‬فقــد ثبــت لدينــا فعــل املدعــى عليــه ‪...........‬الفاحشــة باملجنــي عليهــا‬\n      ‫الفتــاة‪........... /‬بإيــاج ‪ ،‬وحكمنــا بــرد دعــوى املدعــي العــام إقامــة حــد‬\n      ‫احلرابــة لعــدم ثبــوت موجبــه ‪ ،‬وحكمنــا علــى املدعــى عليــه بالرجــم‬\n      ‫حتــى املــوت حــد الزانــي احملصــن‪ .‬وبــه حكمنــا ‪ .‬وبعــرض احلكــم قــرر‬\n      ‫الطرفــان االعتــراض ‪ ،‬وجــرى تســليمهما نســخة مــن احلكــم وإفهامهمــا‬\n      ‫بــأن لهمــا احلــق يف االعتــراض عليــه خــال ثالثــن يومــا ‪،‬وإال ســقط‬\n      ‫حقهمــا يف االعتــراض ‪ .‬وأقفلــت اجللســة الســاعة ‪ . 12 : 00‬وبــاهلل‬\n      ‫التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر‬\n                                                                 ‫يف ‪1434/01/26‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪...........‬القاضــي يف احملكمــة العامــة‬\n      ‫مبحافظــة جــدة وباالشــتراك مــع القاضــي ‪...........‬والقاضــي ‪...........‬‬\n      ‫ففــي يــوم االثنــن املوافــق ‪1434/03/09‬ه ـ افتتحــت اجللســة الســاعة ‪30‬‬\n      ‫‪ 10 :‬وفيهــا حضــر الطرفــان ‪ ،‬وقــدم املدعــى عليــه الئحــة اعتراضيــة‬\n      ‫برقــم ‪ 34/449978‬يف ‪1434/02/21‬ه ـ واملكونــة مــن ‪ 6‬ورقــات جــرى‬\n      ‫االطــاع عليهــا وقررنــا فتــح بــاب املرافعــة ومناقشــة املدعــى عليــه حــول‬\n      ‫مــا قدمــه يف الئحتــه االعتراضيــة بواســطة املترجــم ‪...........‬مينــي اجلنســية‬\n\n\n‫‪219‬‬\n\f‫باإلقامــة رقــم ‪...........‬فقــرر املدعــى عليــه قائــا ‪ :‬اننــي لــم أفعــل فاحشــة‬\n‫الزنــا باملجنــي عليهــا ‪ .‬فبنــاء علــى رجــوع املدعــى عليــه عــن إقــراره بفعــل‬\n‫فاحشــة الزنــا ‪،‬وبنــاء علــى حديــث أبــي هريــرة رضــي اهلل عنــه يف قصــة‬\n‫ماعــز وفيــه ‪ :‬فقــال يــا رســول اهلل إنــه قــد زنــى فأعــرض عنــه ثــم جــاء‬\n‫مــن شــقه اآلخــر فقــال يــا رســول اهلل إنــه قــد زنــى فأمــر بــه يف الرابعــة‬\n‫فأخــرج إلــى احلــرة فرجــم باحلجــارة فلمــا وجــد مــس احلجــارة فــر يشــتد‬\n‫حتــى مــر برجــل معــه حلــي جمــل فضربــه بــه وضربــه النــاس حتــى مــات‬\n‫فذكــروا ذلــك لرســول اهلل صلــى اهلل عليــه وســلم أنــه فــر حــن وجــد‬\n‫مــس احلجــارة ومــس املــوت فقــال رســول اهلل صلــى اهلل عليــه وســلم هــا‬\n‫تركتمــوه ‪ ،‬وبنــاء علــى أن احلــدود تــدرء بالشــبهات ‪ ،‬لذلــك كلــه فقــد‬\n‫رجعنــا عمــا حكمنــا بــه مــن رجــم املدعــى عليــه حتــى املــوت حــد الزانــي‬\n‫احملصــن ‪ ،‬مــع بقــاء حكمنــا الســابق فيمــا يخــص رد طلــب املدعــي‬\n‫العــام إقامــة حــد احلرابــة لعــدم ثبــوت موجبــه ‪ .‬وبــه حكمنــا ‪ .‬وبنــاء علــى‬\n‫مــا ذكــر ســابقا مــن تســبيب للحكــم األول وبنــاء علــى مــا ذكــر مــن‬\n‫تســبيب لرجوعنــا عــن احلكــم ‪ ،‬لذلــك كلــه ‪ ،‬فقــد حكمنــا علــى‬\n‫املدعــى عليــه ‪........... /‬مــدة خمــس ســنوات اعتبــارا مــن تاريــخ إيقافــه‬\n‫‪1433/02/28‬ه ـ وجلــده خمســمائة جلــده مفرقــة علــى دفعــات كل‬\n‫دفعــة خمســون جلــده ‪ ،‬بــن كل دفعــة وأخــرى ال يقــل عــن عشــرة أيــام‬\n‫‪ ،‬وإبعــاده عــن اململكــة العربيــة الســعودية بعــد تنفيــذ محكوميتــه ‪،‬‬\n‫وال يســمح لــه بالعــودة لهــا عــدا مــا تســمح بــه تعليمــات احلــج والعمــرة‬\n‫‪ .‬وبــه حكمنــا ‪ .‬وبعــرض احلكــم قــرر املدعــى عليــه القناعــة وقــرر‬\n‫املدعــي العــام االعتــراض وجــرى تســليمه نســخة مــن احلكــم وإفهامــه‬\n‫بــأن لــه احلــق االعتــراض عليــه خــال ثالثــن يومــا ‪ ،‬وإال ســقط حقــه يف‬\n\n\n                                                                                         ‫‪220‬‬\n\f      ‫االعتــراض ‪ .‬وأقفلــت اجللســة الســاعة ‪ 11 : 00‬وبــاهلل التوفيــق ‪ ،‬وصلــى‬\n      ‫اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/3/9‬هـ‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد‪-:‬‬\n      ‫فقــد جــرى منــا نحــن قضــاة الدائــرة اجلزائيــة اخلماســية االولــى‬\n      ‫مبحكمــة االســتئناف مبنطقــة مكــة املكرمــة االطــاع علــى املعاملــة‬\n      ‫الــواردة مــن فضيلــة رئيــس احملكمــة العامــة بجــدة برقــم ‪3444815‬‬\n      ‫وتاريــخ ‪1434/4/1‬ه ـ املرفــق بهــا الصــك رقــم ‪ 3423681‬وتاريــخ‬\n      ‫‪1434/1/26‬ه ـ الصــادر مــن أصحــاب الفضيلــة القضــاة باحملكمــة‬\n      ‫العامــة بجــدة الشــيخ‪........... /‬والشــيخ‪ ........... /‬والشــيخ‪........... /‬‬\n      ‫املتضمــن دعــوى املدعــي العــام ضــد‪........... /‬هنــدي اجلنســية ‪ ،‬املتهــم‬\n      ‫بخطــف فتــاة قاصــر وفعــل فاحشــة الزنــا بهــا حتــت تهديــد الســاح ممــا‬\n      ‫أدى إلــى حملهــا منــه ســفاحاً‪ ،‬احملكــوم فيــه مبــا دون باطنــه ‪.‬وبدراســة‬\n      ‫احلكــم وصــورة ضبطــه والئحتــه االعتراضيــة تقــررت املوافقــة علــى‬\n      ‫احلكــم ‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                                                    ‫وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪221‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"41499c81-d627-5952-8b7f-c01b2e788165","source_page_start":211,"source_page_end":221,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"61987c794bd22eb20a974dab482a2342ea5a81020b128e20f5fd3b1bd4ea73ba","normalized_text_hash":"c6ca4dcd2dd0fc1a7bf4ff87c473375a53495306015b4c6ebf003f6bb3d847b6","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v27-p211-3423681"}]$archive_payload$::jsonb AS data)
INSERT INTO public.legal_documents (
  id,document_type,category,subcategory,title,document_number,case_number,judgment_number,decision_number,
  circular_number,court,circuit,issuing_authority,document_date,hijri_date,year,subject,summary,facts,claims,
  reasoning,ruling,principle_text,full_text,legal_articles,source_id,source_file_id,source_page_start,
  source_page_end,original_source,acquisition_source,source_url,content_hash,normalized_text_hash,status,review_status
)
SELECT (x->>'id')::uuid,x->>'document_type',x->>'category',x->>'subcategory',x->>'title',x->>'document_number',
       x->>'case_number',x->>'judgment_number',x->>'decision_number',x->>'circular_number',x->>'court',x->>'circuit',
       x->>'issuing_authority',(x->>'document_date')::date,x->>'hijri_date',x->>'year',x->>'subject',x->>'summary',
       x->>'facts',x->>'claims',x->>'reasoning',x->>'ruling',x->>'principle_text',x->>'full_text',
       COALESCE(x->'legal_articles','[]'::jsonb),(x->>'source_id')::uuid,(x->>'source_file_id')::uuid,
       (x->>'source_page_start')::integer,(x->>'source_page_end')::integer,x->>'original_source',
       x->>'acquisition_source',x->>'source_url',x->>'content_hash',x->>'normalized_text_hash',x->>'status',x->>'review_status'
FROM payload CROSS JOIN LATERAL jsonb_array_elements(payload.data) AS x
LIMIT 25
ON CONFLICT (id) DO NOTHING;

